  FT["PH-CREATE-2021"] = {"id":"PH-CREATE-2021","coverage":"full","language":"en","sourceName":"The Lawphil Project — Arellano Law Foundation","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html","fetchedAt":"2026-10-02","articleCount":43,"title":{"zh":"企业复苏与税收优惠法案（CREATE）","en":"Corporate Recovery and Tax Incentives for Enterprises Act","orig":"Corporate Recovery and Tax Incentives for Enterprises Act","vi":"Đạo luật Phục hồi Doanh nghiệp và Ưu đãi Thuế (CREATE)","th":"พระราชบัญญัติการฟื้นฟูกิจการและสิ่งจูงใจทางภาษี (CREATE)","id":"Undang-Undang Pemulihan Perusahaan dan Insentif Pajak (CREATE)","ms":"Akta Pemulihan Perusahaan dan Insentif Cukai (CREATE)"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 11534","issuingBody":"菲律宾国会","promulgatedDate":"2021-03-26","effectiveDate":"2021-04-11","completenessNote":"官方页面所载为修订型法条：以其自身 Section 1–22 逐条修订，并在同一条内全文引述被修正的《1997年国家内部税收法典》相应条文（引文自带旧条号 SEC. 27–311）；本库按官方条号全文照录，保留引文及其旧条号，未增删。","country":"PH","countryName":"菲律宾","layer":"fulltext","articles":[{"id":"PH-CREATE-2021-A1","no":1,"noLabel":{"en":"Section 1."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Section 1. Short Title. — This Act shall be known as the \"Corporate Recovery and Tax Incentives for Enterprises Act\" or \"CREATE\"."},"paragraphs":["Short Title.","— This Act shall be known as the \"Corporate Recovery and Tax Incentives for Enterprises Act\" or \"CREATE\"."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 2. Declaration of Policy. — It is hereby declared the policy of the State to develop the national economy towards global competitiveness by implementing tax policies instrumental in attracting investments, which will result in productivity enhancement, employment generation, countrywide development, and a more inclusive economic growth, while at the same time maintaining fiscal prudence and stability. To achieve these objectives, the State shall: (a) Improve the equity and efficiency of the corporate tax system by lowering the rate, widening the tax base, and reducing tax distortions and leakages; (b) Develop, subject to the provisions of this Act, a more responsive and globally•competitive tax incentives regime that is performance-based, targeted, time-bound, and transparent; (c) Provide support to business in their recovery from unforeseen events such as an outbreak of communicable diseases or a global pandemic, and strengthen the nation's capability for similar circumstances in the future; and (d) Create a more equitable tax incentive system that will allow for inclusive growth and generation of jobs and opportunities in all the regions of the country, and ensure access and ease in the grant of these incentives especially for applicants in least developed areas."},"paragraphs":["Declaration of Policy.","— It is hereby declared the policy of the State to develop the national economy towards global competitiveness by implementing tax policies instrumental in attracting investments, which will result in productivity enhancement, employment generation, countrywide development, and a more inclusive economic growth, while at the same time maintaining fiscal prudence and stability. To achieve these objectives, the State shall: (a) Improve the equity and efficiency of the corporate tax system by lowering the rate, widening the tax base, and reducing tax distortions and leakages; (b) Develop, subject to the provisions of this Act, a more responsive and globally•competitive tax incentives regime that is performance-based, targeted, time-bound, and transparent; (c) Provide support to business in their recovery from unforeseen events such as an outbreak of communicable diseases or a global pandemic, and strengthen the nation's capability for similar circumstances in the future; and (d) Create a more equitable tax incentive system that will allow for inclusive growth and generation of jobs and opportunities in all the regions of the country, and ensure access and ease in the grant of these incentives especially for applicants in least developed areas."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A3","no":3,"noLabel":{"en":"Section 20."},"text":{"en":"Section 20. Submission of Report and Pertinent Information by the Commissioner. - \"(A) x x x \"(B) Submission of Tax-Related Information to the Department of Finance. - The Commissioner shall, upon the order of the Secretary of Finance specifically identifying the needed information and justification for such order in relation to the grant of incentives under title XIII, furnish the Secretary pertinent information on the entities receiving incentives under this Code: Provided, however, That the Secretary and the relevant officers handling such specific information shall be covered by the provisions of Section 270 unless the taxpayer consents in writing to such disclosure. \"(C) Report to Oversight Committee. - The Commissioner shall, with reference to Section 204 of this Code, submit to the Oversight Committee referred to in Section 290 hereof, through the Chairpersons of the Committees on Ways and Means of the Senate and House of Representatives, a report on the exercise of his powers pursuant to the said Section, every six (6) months of each calendar year.\""},"paragraphs":["Submission of Report and Pertinent Information by the Commissioner.","- \"(A) x x x \"(B) Submission of Tax-Related Information to the Department of Finance. - The Commissioner shall, upon the order of the Secretary of Finance specifically identifying the needed information and justification for such order in relation to the grant of incentives under title XIII, furnish the Secretary pertinent information on the entities receiving incentives under this Code:","Provided,","however, That the Secretary and the relevant officers handling such specific information shall be covered by the provisions of Section 270 unless the taxpayer consents in writing to such disclosure. \"(C) Report to Oversight Committee. - The Commissioner shall, with reference to Section 204 of this Code, submit to the Oversight Committee referred to in Section 290 hereof, through the Chairpersons of the Committees on Ways and Means of the Senate and House of Representatives, a report on the exercise of his powers pursuant to the said Section, every six (6) months of each calendar year.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A4","no":4,"noLabel":{"en":"Section 22."},"text":{"en":"Section 22. Definitions. - x x x \"(A) x x x \"(B) The term 'corporation' shall include one person corporations, partnerships, no matter how created or organized, joint-stock companies, joint accounts (cuentas en participation), associations, or insurance companies, but does not include general professional partnerships and a joint venture or consortium formed for the purpose of undertaking construction projects or engaging in petroleum, coal, geothermal and other energy operations pursuant to an operating consortium agreement under a service contract with the Government. 'General professional partnerships' are partnerships formed by persons for the sole purpose of exercising their common profession, no part of the income of which is derived from engaging in any trade or business. \"x x x.\""},"paragraphs":["Definitions.","- x x x \"(A) x x x \"(B) The term 'corporation' shall include one person corporations, partnerships, no matter how created or organized, joint-stock companies, joint accounts (cuentas en participation), associations, or insurance companies, but does not include general professional partnerships and a joint venture or consortium formed for the purpose of undertaking construction projects or engaging in petroleum, coal, geothermal and other energy operations pursuant to an operating consortium agreement under a service contract with the Government. 'General professional partnerships' are partnerships formed by persons for the sole purpose of exercising their common profession, no part of the income of which is derived from engaging in any trade or business. \"x x x.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A5","no":5,"noLabel":{"en":"Section 25."},"text":{"en":"Section 25. Tax on Nonresident Alien Individual. - \"(A) x x x \"(1) x x x \"(2) Cash and/or Property Dividends from a Domestic Corporation or Joint Stock Company, or Insurance or Mutual Fund Company or Regional Operating Headquarter or Multinational Company, or Share in the Distributable Net Income of a Partnership (Except a General Professional Partnership), Joint Account, Joint Venture Taxable as a Corporation or Association, Interests, Royalties, Prizes, and Other Winnings. - Cash and/or property dividends from a domestic corporation, or from a joint stock company, or from an insurance or mutual fund company or from a regional operating headquarter of multinational company, or the share of a nonresident alien individual in the distributable net income after tax of a partnership (except a general professional partnership) of which he is a partner, or the share of a nonresident alien individual in the net income after tax of an association, a joint account, or a joint venture taxable as a corporation of which he is a member or a co-venturer; interests; royalties (in a.ny form); and prizes (except prizes amounting to Ten thousand pesos (P10,000.00) or less which shall be subject to tax under Subsection (B)(l) of Section 24) and other winnings (except winnings amounting to Ten thousand pesos (P10,000.00) or less from Philippine Charity Sweepstakes Office (PCSO) games which shall be exempt); shall be subject to an income tax of twenty percent (20%) on the total amount thereof: Provided, however, That royalties on books as well as other literary works, and royalties on musical compositions shall be subject to a final tax of ten percent (10%) on the total amount thereof: Provided, further, That cinematographic films and similar works shall be subject to the tax provided under Section 28 of this Code: Provided, furthermore, That interest income from long-term deposit or investment in the form of savings, common or individual trust funds, deposit substitutes, investment management accounts and other investments evidenced by certificates in such form prescribed by the Bangko Sentral ng Pilipinas (BSP) shall be exempt from the tax imposed under this Subsection: Provided, finally, That should the holder of the certificate pre-terminate the deposit or investment before the fifth (5th) year, a final tax shall be imposed on the entire income and shall be deducted and withheld by the depository bank from the proceeds of the long-term deposit or investment certificate based on the remaining maturity thereof: \"Four (4) years to less than five (50 years - 5%; \"Three (3) years to less than four (4) years - 12%; \"Less than three (30 years - 20%. \"(3) x x x.\""},"paragraphs":["Tax on Nonresident Alien Individual.","- \"(A) x x x \"(1) x x x \"(2) Cash and/or Property Dividends from a Domestic Corporation or Joint Stock Company, or Insurance or Mutual Fund Company or Regional Operating Headquarter or Multinational Company, or Share in the Distributable Net Income of a Partnership (Except a General Professional Partnership), Joint Account, Joint Venture Taxable as a Corporation or Association, Interests, Royalties, Prizes, and Other Winnings. - Cash and/or property dividends from a domestic corporation, or from a joint stock company, or from an insurance or mutual fund company or from a regional operating headquarter of multinational company, or the share of a nonresident alien individual in the distributable net income after tax of a partnership (except a general professional partnership) of which he is a partner, or the share of a nonresident alien individual in the net income after tax of an association, a joint account, or a joint venture taxable as a corporation of which he is a member or a co-venturer; interests; royalties (in a.ny form); and prizes (except prizes amounting to Ten thousand pesos (P10,000.00) or less which shall be subject to tax under Subsection (B)(l) of Section 24) and other winnings (except winnings amounting to Ten thousand pesos (P10,000.00) or less from Philippine Charity Sweepstakes Office (PCSO) games which shall be exempt); shall be subject to an income tax of twenty percent (20%) on the total amount thereof:","Provided,","however, That royalties on books as well as other literary works, and royalties on musical compositions shall be subject to a final tax of ten percent (10%) on the total amount thereof:","Provided,","further, That cinematographic films and similar works shall be subject to the tax provided under Section 28 of this Code:","Provided,","furthermore, That interest income from long-term deposit or investment in the form of savings, common or individual trust funds, deposit substitutes, investment management accounts and other investments evidenced by certificates in such form prescribed by the Bangko Sentral ng Pilipinas (BSP) shall be exempt from the tax imposed under this Subsection:","Provided,","finally, That should the holder of the certificate pre-terminate the deposit or investment before the fifth (5th) year, a final tax shall be imposed on the entire income and shall be deducted and withheld by the depository bank from the proceeds of the long-term deposit or investment certificate based on the remaining maturity thereof: \"Four (4) years to less than five (50 years - 5%; \"Three (3) years to less than four (4) years - 12%; \"Less than three (30 years - 20%. \"(3) x x x.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A6","no":6,"noLabel":{"en":"SEC. 27."},"text":{"en":"SEC. 27. Rates of Income Tax on Domestic Corporations. - \"(A) In General, — Except as otherwise provided in this Code, an income tax rate of twenty-five percent (25%) effective July 1, 2020, is hereby imposed upon the taxable income derived during each taxable year from all sources within and without the Philippines by every corporation, as defined in Section 22(B) of this Code and taxable under this title as a corporation, organized in, or under the laws of the Philippines. \" Provided, That corporations with net taxable income not exceeding Five million pesos and with total assets not exceeding One hundred million pesos (P 100,000,000.00), excluding land on which the particular business entity's ofice, plant, and equipment are situated during the taxable year for which the tax is imposed, shall be taxed at twenty percent (20%). \"In the case of corporations adopting the fiscal-year accounting period, the taxable income shall be computed without regard to the specific date when specific sales, purchases and other transactions occur. Their income and expenses for the fiscal year shall be deemed to have been earned and spent equally for each month of the period. \"The corporate income tax rate shall be applied on the amount computed by multiplying the number of months covered by the new rate within the fiscal year by the taxable income of the corporations for the period, divided by twelve. \"(B) Proprietary Educational Institutions and Hospitals. - Proprietary educational institutions and hospitals which are nonprofit shall pay a tax of ten percent (10%) on their taxable income except those covered by Subsection (D) hereof: Provided, That beginning July 1, 2020 until June 30, 2023, the tax rate herein imposed shall be one percent (1%): Provided, further, That if the gross income from 'unrelated trade, business or other activity' exceeds fifty percent (50%) of the total gross income derived by such educational or hospitals from all sources, the tax prescribed in Subsection (A) hereof shall be imposed on the en&e taxable income. For purposes of this Subsection, the term 'unrelated trade, business or other activity' means any trade, business or other activity, the conduct of which is not substantially related to the exercise or performance by such educational institution or hospital of its primary purpose or function. 'Proprietary' means a private hospital, or any private school maintained and administered by private individuals or groups with an issued permit to operate from the Department of Education (DepEd), or the Commission on Higher Education (CHED), or the Technical Education and Skills Development Authority (TESDA), as the case may be, in accordance with existing laws and regulations. \"(C) Government-owned or -Controlled Corporations, Agencies or Instrumentalities. - The provisions of existing special or general laws to the contrary notwithstanding, all corporations, agencies, or owned or controlled by the Government, except the Government Service Insurance System (GSIS), the Social Security System (SSS), the Home Development Mutual Fund (HDMF), the Philippine Health Insurance Corporation (PHIC), and the local water districts shall pay such rate of tax upon their taxable income as are imposed by this Section upon corporations or associations engaged in a similar business, industry, or activity. \"(D) Rates of Tax on Certain Passive Incomes. - x x x \"x x x \"(4) Intercorporate Dividends. - Dividends received by a domestic corporation shall not be subject to tax under this title: Provided, That for foreign-sourced dividends to be exempt, the funds from such dividends actually received or remitted into the Philippines are reinvested in the business operations of the domestic corporation in the Philippines within the next taxable year from the time the foreign-sourced dividends were received and shall be limited to funding the working capital requirements, capital expenditures, dividend payments, investment in domestic subsidiaries, and infrastructure project: Provided, further, That the domestic corporation holds directly at least twenty percent (20%) of the outstanding shares of the foreign corporation and has held the shareholdings for a minimum of two (2) years at the time of the dividends distribution.\" \"(E) Minimum Corporate Income Tax on Domestic Corporations. \"(1) Imposition of Tax. — A minimum corporate income tax of two percent (2%) of the gross income as of the end of the taxable yea.r, as defined herein, is hereby i.mposed on a corporation taxable under this title, beginning on the fourth taxable year immediately following the year in which such corporation commenced its business operations, when the minimum income tax is greater than the tax computed under Subsection (A) of this Section for the taxable year: Provided, That effective July 1, 2020 until June 30, 2023, the rate shall be one percent (1%). \"(2) x x x \"(3) x x x \"(4) x x x.\""},"paragraphs":["Rates of Income Tax on Domestic Corporations.","- \"(A) In General, — Except as otherwise provided in this Code, an income tax rate of twenty-five percent (25%) effective July 1, 2020, is hereby imposed upon the taxable income derived during each taxable year from all sources within and without the Philippines by every corporation, as defined in Section 22(B) of this Code and taxable under this title as a corporation, organized in, or under the laws of the Philippines. \"","Provided,","That corporations with net taxable income not exceeding Five million pesos and with total assets not exceeding One hundred million pesos (P 100,000,000.00), excluding land on which the particular business entity's ofice, plant, and equipment are situated during the taxable year for which the tax is imposed, shall be taxed at twenty percent (20%). \"In the case of corporations adopting the fiscal-year accounting period, the taxable income shall be computed without regard to the specific date when specific sales, purchases and other transactions occur. Their income and expenses for the fiscal year shall be deemed to have been earned and spent equally for each month of the period. \"The corporate income tax rate shall be applied on the amount computed by multiplying the number of months covered by the new rate within the fiscal year by the taxable income of the corporations for the period, divided by twelve. \"(B) Proprietary Educational Institutions and Hospitals. - Proprietary educational institutions and hospitals which are nonprofit shall pay a tax of ten percent (10%) on their taxable income except those covered by Subsection (D) hereof:","Provided,","That beginning July 1, 2020 until June 30, 2023, the tax rate herein imposed shall be one percent (1%):","Provided,","further, That if the gross income from 'unrelated trade, business or other activity' exceeds fifty percent (50%) of the total gross income derived by such educational or hospitals from all sources, the tax prescribed in Subsection (A) hereof shall be imposed on the en&e taxable income. For purposes of this Subsection, the term 'unrelated trade, business or other activity' means any trade, business or other activity, the conduct of which is not substantially related to the exercise or performance by such educational institution or hospital of its primary purpose or function. 'Proprietary' means a private hospital, or any private school maintained and administered by private individuals or groups with an issued permit to operate from the Department of Education (DepEd), or the Commission on Higher Education (CHED), or the Technical Education and Skills Development Authority (TESDA), as the case may be, in accordance with existing laws and regulations. \"(C) Government-owned or -Controlled Corporations, Agencies or Instrumentalities. - The provisions of existing special or general laws to the contrary notwithstanding, all corporations, agencies, or owned or controlled by the Government, except the Government Service Insurance System (GSIS), the Social Security System (SSS), the Home Development Mutual Fund (HDMF), the Philippine Health Insurance Corporation (PHIC), and the local water districts shall pay such rate of tax upon their taxable income as are imposed by this Section upon corporations or associations engaged in a similar business, industry, or activity. \"(D) Rates of Tax on Certain Passive Incomes. - x x x \"x x x \"(4) Intercorporate Dividends. - Dividends received by a domestic corporation shall not be subject to tax under this title:","Provided,","That for foreign-sourced dividends to be exempt, the funds from such dividends actually received or remitted into the Philippines are reinvested in the business operations of the domestic corporation in the Philippines within the next taxable year from the time the foreign-sourced dividends were received and shall be limited to funding the working capital requirements, capital expenditures, dividend payments, investment in domestic subsidiaries, and infrastructure project:","Provided,","further, That the domestic corporation holds directly at least twenty percent (20%) of the outstanding shares of the foreign corporation and has held the shareholdings for a minimum of two (2) years at the time of the dividends distribution.\" \"(E) Minimum Corporate Income Tax on Domestic Corporations. \"(1) Imposition of Tax. — A minimum corporate income tax of two percent (2%) of the gross income as of the end of the taxable yea.r, as defined herein, is hereby i.mposed on a corporation taxable under this title, beginning on the fourth taxable year immediately following the year in which such corporation commenced its business operations, when the minimum income tax is greater than the tax computed under Subsection (A) of this Section for the taxable year:","Provided,","That effective July 1, 2020 until June 30, 2023, the rate shall be one percent (1%). \"(2) x x x \"(3) x x x \"(4) x x x.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A7","no":7,"noLabel":{"en":"SEC. 28."},"text":{"en":"SEC. 28. Rates of Income Tax on Foreign Corporations. - \"(1) In General. — Except as otherwise provided in this Code, a corporation organized, authorized, or existing under the laws of any foreign country, engaged in trade or business within the Philippines, shall be subject to an income tax equivalent to twenty-five percent (25%) of the taxable income derived in the preceding taxable year from all sources within the Philippines effective July 1, 2020. \"In the case of corporations adopting the fiscal-year accounting period, the taxable income shall be computed without regard to the specific date when sales, purchases and other transactions occur. Their income and expenses for the fiscal year shall be deemed to have been earned and spent equally for each month of the period. \"The corporate income tax rate shall be applied on the amount computed by multiplying the number of months covered by the new rate within the fiscal year by the taxable income of the corporation for the period, divided by twelve. \"(2) Minimum Corporate Income Tax of Resident Foreign Corporations. — A minimum corporate income tax of two percent (2%) of gross income, as prescribed under Section 27(E) of this Code, shall be imposed, under the same conditions, on a resident foreign corporation taxable under paragraph (1) of this Subsection: Provided, That effective July 1, 2020 until Ju.ne 303 2023, the rate shall be one percent (1%). \"(3) x x x \"(4) Tax on Branch Profits Remittances. - x x x \"(5) Regional or Area Headquarters and Regional Operating Headquarters of Multinational Companies. - \"(a) Regional or area headquarters as defined in Section 22 (DD) shall not be subject to income tax. \"(b) Regional operating headquarters as defined in Section 22 (EE) shall pay a tax of ten percent (10%) of their taxable income: Provided, That effective January 1, 2022, regional operating headquarters shall be subject to the regular corporate income tax. \"(6) Tax on Certain Incomes Received by a Resident Foreign Corporation. - \"(a) Interest from Deposits and Yield or any other Monetary Benefit from Deposit Substitutes, Trust Funds and Similar Arrangements and Royalties. — Interest from any currency bank deposit and yield or any other monetary benefit from deposit substitutes and from trust funds and similar arrangements and royalties derived from sources within the Philippines shall be subject to a final income tax at the rate of twenty percent (20%) of such interest: Provided, however, That interest income derived by a resident foreign corporation from a depository bank under the expanded foreign currency deposit system shall be subject to a final income tax at the rate of fifteen percent (15%) of such interest income. \"(b) Income Derived under the Expanded Foreign Currency Deposit System. - x x x \"(c) Capital Gains from Sale of Shares of Stock Not Traded in the Stock Exchange.ℒ&alpha;w&rho;hi&#2551 — A final tax at the rate of fifteen percent (15%) is hereby imposed upon the net capital gains realized during the taxable year from the sale, barter, exchange or other disposition of shares of stock in a domestic corporation except shares sold or disposed of through the stock exchange. \"(d) Intercorporate Dividends. - x x x \"(B) Tax on Nonresident Foreign Corporation. - \"(1) In General. — Except as otherwise provided in this Code, a foreign corporation not engaged in trade or business in the Philippines, effective January 1, 2021, shall pay a ta.x equal to twenty-five percent (25%) of the gross income received during each taxable year from all sources within the Philippines, such as interests, dividends, rents, royalties, salaries, premiums (except reinsurance premiums), annuities, emoluments or other fixed or determinable annual, periodic or casual gains, profits and income, and capital gains, except capital gains subject to tax under subparagraph 5(c). \"(2) x x x \"(3) x x x \"(4) x x x \"(5) Tax on Certain Incomes Received by a Nonresident Foreign Corporation. - \"(a) Interest on Foreign Loans. - x x x\" \"(b) Intercorporate Dividends. - A final withholding tax at the rate of fifteen percent (15%) is hereby imposed on the amount of cash and/or property dividends received from a domestic corporation, which shall be collected and paid as provided in Section 57(A) of this Code, subject to the condition that the country in which the nonresident foreign corporation is domiciled, shall allow a credit against the tax due from the nonresident foreign corporation taxes deemed to have been paid in the Philippines equivalent to fifteen percent (15%), which represents the difference between the regular income tax and the fifteen percent (15%) tax on dividends as provided in this subparagraph: Provided, That effective July 1, 2020, the credit against the tax due shall be equivalent to the difference between the regular income tax rate provided in Section 28(B)(1) of this Code and the fifteen percent (15%) tax on dividends; \"(c) Capital Gains from Sale of Shares of Stock Not Traded in the Stock Exchange. — A final senior high schools, public higher education tax at the rate of fifteen percent (15%) is hereby imposed upon the net capital gains realized during the taxable year from the sale, barter, exchange or other disposition of shares of stock in a domestic corporation, except shares sold, or disposed of the stock exchange."},"paragraphs":["Rates of Income Tax on Foreign Corporations.","- \"(1) In General. — Except as otherwise provided in this Code, a corporation organized, authorized, or existing under the laws of any foreign country, engaged in trade or business within the Philippines, shall be subject to an income tax equivalent to twenty-five percent (25%) of the taxable income derived in the preceding taxable year from all sources within the Philippines effective July 1, 2020. \"In the case of corporations adopting the fiscal-year accounting period, the taxable income shall be computed without regard to the specific date when sales, purchases and other transactions occur. Their income and expenses for the fiscal year shall be deemed to have been earned and spent equally for each month of the period. \"The corporate income tax rate shall be applied on the amount computed by multiplying the number of months covered by the new rate within the fiscal year by the taxable income of the corporation for the period, divided by twelve. \"(2) Minimum Corporate Income Tax of Resident Foreign Corporations. — A minimum corporate income tax of two percent (2%) of gross income, as prescribed under Section 27(E) of this Code, shall be imposed, under the same conditions, on a resident foreign corporation taxable under paragraph (1) of this Subsection:","Provided,","That effective July 1, 2020 until Ju.ne 303 2023, the rate shall be one percent (1%). \"(3) x x x \"(4) Tax on Branch Profits Remittances. - x x x \"(5) Regional or Area Headquarters and Regional Operating Headquarters of Multinational Companies. - \"(a) Regional or area headquarters as defined in Section 22 (DD) shall not be subject to income tax. \"(b) Regional operating headquarters as defined in Section 22 (EE) shall pay a tax of ten percent (10%) of their taxable income:","Provided,","That effective January 1, 2022, regional operating headquarters shall be subject to the regular corporate income tax. \"(6) Tax on Certain Incomes Received by a Resident Foreign Corporation. - \"(a) Interest from Deposits and Yield or any other Monetary Benefit from Deposit Substitutes, Trust Funds and Similar Arrangements and Royalties. — Interest from any currency bank deposit and yield or any other monetary benefit from deposit substitutes and from trust funds and similar arrangements and royalties derived from sources within the Philippines shall be subject to a final income tax at the rate of twenty percent (20%) of such interest:","Provided,","however, That interest income derived by a resident foreign corporation from a depository bank under the expanded foreign currency deposit system shall be subject to a final income tax at the rate of fifteen percent (15%) of such interest income. \"(b) Income Derived under the Expanded Foreign Currency Deposit System. - x x x \"(c) Capital Gains from Sale of Shares of Stock Not Traded in the Stock Exchange.ℒ&alpha;w&rho;hi&#2551 — A final tax at the rate of fifteen percent (15%) is hereby imposed upon the net capital gains realized during the taxable year from the sale, barter, exchange or other disposition of shares of stock in a domestic corporation except shares sold or disposed of through the stock exchange. \"(d) Intercorporate Dividends. - x x x \"(B) Tax on Nonresident Foreign Corporation. - \"(1) In General. — Except as otherwise provided in this Code, a foreign corporation not engaged in trade or business in the Philippines, effective January 1, 2021, shall pay a ta.x equal to twenty-five percent (25%) of the gross income received during each taxable year from all sources within the Philippines, such as interests, dividends, rents, royalties, salaries, premiums (except reinsurance premiums), annuities, emoluments or other fixed or determinable annual, periodic or casual gains, profits and income, and capital gains, except capital gains subject to tax under subparagraph 5(c). \"(2) x x x \"(3) x x x \"(4) x x x \"(5) Tax on Certain Incomes Received by a Nonresident Foreign Corporation. - \"(a) Interest on Foreign Loans. - x x x\" \"(b) Intercorporate Dividends. - A final withholding tax at the rate of fifteen percent (15%) is hereby imposed on the amount of cash and/or property dividends received from a domestic corporation, which shall be collected and paid as provided in Section 57(A) of this Code, subject to the condition that the country in which the nonresident foreign corporation is domiciled, shall allow a credit against the tax due from the nonresident foreign corporation taxes deemed to have been paid in the Philippines equivalent to fifteen percent (15%), which represents the difference between the regular income tax and the fifteen percent (15%) tax on dividends as provided in this subparagraph:","Provided,","That effective July 1, 2020, the credit against the tax due shall be equivalent to the difference between the regular income tax rate provided in Section 28(B)(1) of this Code and the fifteen percent (15%) tax on dividends; \"(c) Capital Gains from Sale of Shares of Stock Not Traded in the Stock Exchange. — A final senior high schools, public higher education tax at the rate of fifteen percent (15%) is hereby imposed upon the net capital gains realized during the taxable year from the sale, barter, exchange or other disposition of shares of stock in a domestic corporation, except shares sold, or disposed of the stock exchange."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 8. Section 29 of the National Internal Revenue Code of 1997, as amended, on the imposition of improperly accumulated earnings tax, is hereby repealed."},"paragraphs":["Section 29 of the National Internal Revenue Code of 1997, as amended, on the imposition of improperly accumulated earnings tax, is hereby repealed."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A9","no":9,"noLabel":{"en":"SEC. 34."},"text":{"en":"SEC. 34. Deductions from Gross Income. - Except for taxpayers earning compensation income arising from personal services rendered under an employer-employee relationship where no deductions shall be allowed under this Section, in computing taxable income subject to income tax under Sections 24(A); 25(A); 26; 27(A), (B), and (C); and 28(A)(I), there shall be allowed the following deductions from gross income: \"(A) Expenses. - \"(1) Ordinary and Necessary trade, Business or Professional Expenses. - \"(a) x x x \"(i) x x x \"x x x \"(v) An additional deduction from taxable income of one-half (1/2) of the value of labor training expenses incurred for skills development of enterprise-based trainees enrolled in public senior high schools, public higher education institutions, or public technical and vocational institutions and duly covered by an apprenticeship agreement under Presidential Decree No. 442, series of 1974, or the 'Labor Code of the Philippines', as amended, shall be granted to enterprises: Provided, further, That for the additional deduction foe enterprise-based training of students from public educational institutions, the enterprise shall secure proper certification from the DepEd, TESDA, or CHED: Provided, finally, That such deduction shall not exceed ten percent (10%) of direct labor wage. \"(B) Interest. - \"(1) In General. - The amount of interest paid or incurred within a taxable year on indebtedness in connection with the taxpayer's profession, trade or business shall be allowed as deduction from gross income: Provided, however, That the taxpayer's otherwise allowable deduction for interest expense shall be reduced by twenty percent (20%) of the interest income subjected to final tax: Provided, finally, That if the interest income tax is adjusted in the future, the interest expense reduction rate shall be adjusted accordingly based on the prescribed standard formula as defined in the rules and regulations to be promulgated by the Secretary of Finance, upon the recommendation of the Commissioner of Internal Revenue. \"(2) x x x \"(C) Taxes. - x x x \"(D) Losses. - x x x \"(E) Bad debts. - x x x \"(F) Depreciation. - x x x \"(G) Depletion of Oil and Gas Wells and Mines. - x x x \"(H) Charitable and Other Contributions. - x x x \"(I) Research and Development. - x x x \"(J) Pension Trusts. - x x x \"(K) Additional Requirements for Deductibility of Certain Payments. - x x x \"(L) Optional Standard Deduction (OSD). - x x x."},"paragraphs":["Deductions from Gross Income.","- Except for taxpayers earning compensation income arising from personal services rendered under an employer-employee relationship where no deductions shall be allowed under this Section, in computing taxable income subject to income tax under Sections 24(A); 25(A); 26; 27(A), (B), and (C); and 28(A)(I), there shall be allowed the following deductions from gross income: \"(A) Expenses. - \"(1) Ordinary and Necessary trade, Business or Professional Expenses. - \"(a) x x x \"(i) x x x \"x x x \"(v) An additional deduction from taxable income of one-half (1/2) of the value of labor training expenses incurred for skills development of enterprise-based trainees enrolled in public senior high schools, public higher education institutions, or public technical and vocational institutions and duly covered by an apprenticeship agreement under Presidential Decree No. 442, series of 1974, or the 'Labor Code of the Philippines', as amended, shall be granted to enterprises:","Provided,","further, That for the additional deduction foe enterprise-based training of students from public educational institutions, the enterprise shall secure proper certification from the DepEd, TESDA, or CHED:","Provided,","finally, That such deduction shall not exceed ten percent (10%) of direct labor wage. \"(B) Interest. - \"(1) In General. - The amount of interest paid or incurred within a taxable year on indebtedness in connection with the taxpayer's profession, trade or business shall be allowed as deduction from gross income:","Provided,","however, That the taxpayer's otherwise allowable deduction for interest expense shall be reduced by twenty percent (20%) of the interest income subjected to final tax:","Provided,","finally, That if the interest income tax is adjusted in the future, the interest expense reduction rate shall be adjusted accordingly based on the prescribed standard formula as defined in the rules and regulations to be promulgated by the Secretary of Finance, upon the recommendation of the Commissioner of Internal Revenue. \"(2) x x x \"(C) Taxes. - x x x \"(D) Losses. - x x x \"(E) Bad debts. - x x x \"(F) Depreciation. - x x x \"(G) Depletion of Oil and Gas Wells and Mines. - x x x \"(H) Charitable and Other Contributions. - x x x \"(I) Research and Development. - x x x \"(J) Pension Trusts. - x x x \"(K) Additional Requirements for Deductibility of Certain Payments. - x x x \"(L) Optional Standard Deduction (OSD). - x x x."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A10","no":10,"noLabel":{"en":"SEC. 40."},"text":{"en":"SEC. 40. Determination of Amount and Recognition of Gain or Loss. - \"(A) x x x \"\"(B) x x x \"(C) Exchange of Property. - x x x \"(1) General Rule. - x x x \"(2) Exception. - No gain or loss shall be recognized on a corporation or on it stocks or securities if such corporation is a party to a reorganization and exchanges property in pursuance of a plan of reorganization solely for stock or securities in another corporation that is a party to the reorganization. A reorganization is defined as: \"(a) A corporation, which is a party to a merger or consolidation, exchanges property solely for stock in a corporation, which is a party to the merger or consolidation; or \"(b) The acquisition by one corporation, in exchange solely for all or a part of its voting stock, or in exchange solely for all or part of the voting stock of a corporation which is in control of the acquiring corporation, of stock of another corporation if, immediately after the acquisition, the acquiring corporation has control of such other corporation whether or not such acquiring corporation had control immediately before the acquisition; or \"(c) The acquisition by one corporation, in exchange solely for all or a part of its voting stock or in exchange solely for all or part of the voting stock of a corporation which is in control of the acquiring corporation, of substantially all of the properties of another corporation. In determining whether the exchange is solely for stock, the assumption by the acquiring corporation of a liability of the others shall be disregarded; or \"(d) A recapitalization, which shall mean an arrangement whereby the stock and bonds of a corporation are readjusted as to amount, income, or priority or an arrangement of all stockholders and creditors to change and increase or decrease the capitalization or debts of the corporation or both; or \"(e) A reincorporation, which shall mean the formation of the same corporate business with the same assets and the same stakeholders surviving under a new charter. \"No gain or loss shall also be recognized if property is transferred to a corporation by a person, alone or together with others, not exceeding four (4) persons, in exchange for stock or unit of participation in such a corporation of which as a result of such exchange the transferor or transferors, collectively, gains or maintains control of said corporation: Provided, That stocks issued for services shall not be considered as issued in return for property. \"Sale or exchange of property used for business for shares of stock covered under this Subsection shall not be subject to value-added tax. \"In all of the foregoing instances of exchange of property, prior Bureau of Internal Revenue confirmation or tax ruling shall not be required for purposes of availing the tax exemption. \"x x x \"(6) Definitions. - \"(a) x x x \"(b) x x x \"(c) The term 'control', when used in this Section, shall mean ownership of stocks in a corporation after the transfer of property possessing at least fifty-one percent (51%) of the total voting power of all classes of stocks entitled to vote: Provided, That the collective and not the individual ownership of all classes of stocks entitled to vote of the transferor or transferors under this Section shall be used in determining the presence of control. \"x x x."},"paragraphs":["Determination of Amount and Recognition of Gain or Loss.","- \"(A) x x x \"\"(B) x x x \"(C) Exchange of Property. - x x x \"(1) General Rule. - x x x \"(2) Exception. - No gain or loss shall be recognized on a corporation or on it stocks or securities if such corporation is a party to a reorganization and exchanges property in pursuance of a plan of reorganization solely for stock or securities in another corporation that is a party to the reorganization. A reorganization is defined as: \"(a) A corporation, which is a party to a merger or consolidation, exchanges property solely for stock in a corporation, which is a party to the merger or consolidation; or \"(b) The acquisition by one corporation, in exchange solely for all or a part of its voting stock, or in exchange solely for all or part of the voting stock of a corporation which is in control of the acquiring corporation, of stock of another corporation if, immediately after the acquisition, the acquiring corporation has control of such other corporation whether or not such acquiring corporation had control immediately before the acquisition; or \"(c) The acquisition by one corporation, in exchange solely for all or a part of its voting stock or in exchange solely for all or part of the voting stock of a corporation which is in control of the acquiring corporation, of substantially all of the properties of another corporation. In determining whether the exchange is solely for stock, the assumption by the acquiring corporation of a liability of the others shall be disregarded; or \"(d) A recapitalization, which shall mean an arrangement whereby the stock and bonds of a corporation are readjusted as to amount, income, or priority or an arrangement of all stockholders and creditors to change and increase or decrease the capitalization or debts of the corporation or both; or \"(e) A reincorporation, which shall mean the formation of the same corporate business with the same assets and the same stakeholders surviving under a new charter. \"No gain or loss shall also be recognized if property is transferred to a corporation by a person, alone or together with others, not exceeding four (4) persons, in exchange for stock or unit of participation in such a corporation of which as a result of such exchange the transferor or transferors, collectively, gains or maintains control of said corporation:","Provided,","That stocks issued for services shall not be considered as issued in return for property. \"Sale or exchange of property used for business for shares of stock covered under this Subsection shall not be subject to value-added tax. \"In all of the foregoing instances of exchange of property, prior Bureau of Internal Revenue confirmation or tax ruling shall not be required for purposes of availing the tax exemption. \"x x x \"(6) Definitions. - \"(a) x x x \"(b) x x x \"(c) The term 'control', when used in this Section, shall mean ownership of stocks in a corporation after the transfer of property possessing at least fifty-one percent (51%) of the total voting power of all classes of stocks entitled to vote:","Provided,","That the collective and not the individual ownership of all classes of stocks entitled to vote of the transferor or transferors under this Section shall be used in determining the presence of control. \"x x x."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A11","no":11,"noLabel":{"en":"SEC. 57."},"text":{"en":"SEC. 57. Withholding of Tax at Source. - \"(A) x x x \"(B) x x x \"(C) x x x \"The Department of Finance shall review, at least once every three (3) years, regulations and processes for the withholding of creditable tax under this Code, and direct the Bureau of Internal Revenue to amend rules and regulations for the same, should it be found during the review that the existing rules, regulations, and processes for the withholding of creditable tax under this Code adversely and materially impact the taxpayer."},"paragraphs":["Withholding of Tax at Source.","- \"(A) x x x \"(B) x x x \"(C) x x x \"The Department of Finance shall review, at least once every three (3) years, regulations and processes for the withholding of creditable tax under this Code, and direct the Bureau of Internal Revenue to amend rules and regulations for the same, should it be found during the review that the existing rules, regulations, and processes for the withholding of creditable tax under this Code adversely and materially impact the taxpayer."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A12","no":12,"noLabel":{"en":"SEC. 109."},"text":{"en":"SEC. 109. Exempt Transactions. - \"(1) Subject to the provisions of Subsection (2) hereof, the following transactions shall be exempt from the value-added tax: \"x x x \"(P) Sale of property not primarily held for sale to customers or held for lease in the ordinary course of trade or business or real property utilized for low-cost and socialized housing as defined by Republic Act No. 7279, otherwise known as the 'Urban Development and Housing Act of 1992,' and other related laws, residential lot valued at Two million five hundred thousand pesos (P2,500,000.00) and below, house and lot, and other residential dwellings valued at Four million two hundred thousand pesos (P4,200,000.00) and below: provided, That beginning January 1, 2024 and every three (3) years thereafter, the amounts herein stated shall be adjusted to present values using the Consumer Price Index, as published by the Philippine Statistics Authority (PSA). \"x x x \"(R) Sale, importation, printing or publication of books, and any newspaper, magazine, journal, review bulletin, or any such educational reading material covered by the UNESCO Agreement on the Importation of Education, Scientific, and Cultural Materials, including the digital or electronic format thereof: provided, That the materials enumerated herein are not devoted principally to the publication of paid advertisements; \"x x x \"(AA) Sale of or importation of prescription drugs and medicines for: \"(i) Diabetes, high cholesterol, and hypertension beginning January 1, 2020; and \"(ii) Cancer, mental illness, tuberculosis, and kidney diseases beginning January 1, 2021; \" Provided, That the DOH shall issue a list of approved drugs and medicines form this purpose within sixty (60) days from the effectivity of this Act; and \"(BB) Sale or importation of the following beginning January 1, 2021 to December 31, 2023: \"(i) Capital equipment, its spare parts and raw materials, necessary for the production of personal protective equipment components such as coveralls, gown, surgical cap, surgical mask, N-95 mask, scrub suits, goggles and face shield, double or surgical gloves, dedicated shoes, and shoe covers, for COVID-19 prevention; \"(ii) All drugs, vaccines and medical devices specifically prescribed and directly used for the treatment of COVID-19; and \"(iii) Drugs for the treatment of COVID-19 approved by the Food and Drug Administration (FDA) for use in clinical trials, including raw materials directly necessary for the production of such drugs: Provided, That the Department of Trade and Industry (DTI) shall certify that such equipment, spare parts or raw materials for importation are not locally available or insufficient in quantity, or not in accordance with the quality or specification required: Provided, further, That for item (ii), within sixty (60) days from the effectivity of this Act, and every three (3) months thereafter, the Department of Health (DOH) shall issue a list of prescription drugs and medical devices covered by this provision: Provided, finally, That the exemption claimed under this Subsection shall be subject to post audit by the Bureau of Internal Revenue or the Bureau of Customs as may be applicable. \"(CC) Sale or lease of goods or properties or the performance of services other than the transactions mentioned in the preceding paragraphs, the gross annual sales and/or receipts do not exceed the amount of Three million (P3,000,000.00)."},"paragraphs":["Exempt Transactions.","- \"(1) Subject to the provisions of Subsection (2) hereof, the following transactions shall be exempt from the value-added tax: \"x x x \"(P) Sale of property not primarily held for sale to customers or held for lease in the ordinary course of trade or business or real property utilized for low-cost and socialized housing as defined by Republic Act No. 7279, otherwise known as the 'Urban Development and Housing Act of 1992,' and other related laws, residential lot valued at Two million five hundred thousand pesos (P2,500,000.00) and below, house and lot, and other residential dwellings valued at Four million two hundred thousand pesos (P4,200,000.00) and below: provided, That beginning January 1, 2024 and every three (3) years thereafter, the amounts herein stated shall be adjusted to present values using the Consumer Price Index, as published by the Philippine Statistics Authority (PSA). \"x x x \"(R) Sale, importation, printing or publication of books, and any newspaper, magazine, journal, review bulletin, or any such educational reading material covered by the UNESCO Agreement on the Importation of Education, Scientific, and Cultural Materials, including the digital or electronic format thereof: provided, That the materials enumerated herein are not devoted principally to the publication of paid advertisements; \"x x x \"(AA) Sale of or importation of prescription drugs and medicines for: \"(i) Diabetes, high cholesterol, and hypertension beginning January 1, 2020; and \"(ii) Cancer, mental illness, tuberculosis, and kidney diseases beginning January 1, 2021; \"","Provided,","That the DOH shall issue a list of approved drugs and medicines form this purpose within sixty (60) days from the effectivity of this Act; and \"(BB) Sale or importation of the following beginning January 1, 2021 to December 31, 2023: \"(i) Capital equipment, its spare parts and raw materials, necessary for the production of personal protective equipment components such as coveralls, gown, surgical cap, surgical mask, N-95 mask, scrub suits, goggles and face shield, double or surgical gloves, dedicated shoes, and shoe covers, for COVID-19 prevention; \"(ii) All drugs, vaccines and medical devices specifically prescribed and directly used for the treatment of COVID-19; and \"(iii) Drugs for the treatment of COVID-19 approved by the Food and Drug Administration (FDA) for use in clinical trials, including raw materials directly necessary for the production of such drugs:","Provided,","That the Department of Trade and Industry (DTI) shall certify that such equipment, spare parts or raw materials for importation are not locally available or insufficient in quantity, or not in accordance with the quality or specification required:","Provided,","further, That for item (ii), within sixty (60) days from the effectivity of this Act, and every three (3) months thereafter, the Department of Health (DOH) shall issue a list of prescription drugs and medical devices covered by this provision:","Provided,","finally, That the exemption claimed under this Subsection shall be subject to post audit by the Bureau of Internal Revenue or the Bureau of Customs as may be applicable. \"(CC) Sale or lease of goods or properties or the performance of services other than the transactions mentioned in the preceding paragraphs, the gross annual sales and/or receipts do not exceed the amount of Three million (P3,000,000.00)."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A13","no":13,"noLabel":{"en":"SEC. 116."},"text":{"en":"SEC. 116. Tax on Persons Exempt from Value-Added Tax (VAT). - Any person whose sales or receipts are exempt under Section 109(CC) of this Code from the payment of value-added tax and who is not a VAT-registered person shall pay a tax equivalent to three percent (3%) of his gross quarterly sales or receipts: Provided, That cooperatives, shall be exempt from the three percent (3%) gross receipts tax herein imposed: Provided, further, That effective July 1, 2020 until June 30, 2023, the rates shall be one percent (1%)."},"paragraphs":["Tax on Persons Exempt from Value-Added Tax (VAT).","- Any person whose sales or receipts are exempt under Section 109(CC) of this Code from the payment of value-added tax and who is not a VAT-registered person shall pay a tax equivalent to three percent (3%) of his gross quarterly sales or receipts:","Provided,","That cooperatives, shall be exempt from the three percent (3%) gross receipts tax herein imposed:","Provided,","further, That effective July 1, 2020 until June 30, 2023, the rates shall be one percent (1%)."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A14","no":14,"noLabel":{"en":"SEC. 204."},"text":{"en":"SEC. 204. Authority of the Commissioner to Compromise, Abate, and Refund or Credit Taxes. - The Commissioner may - \"(A) x x x \"(B) x x x \"(C) Credit or refund taxes erroneously or illegally received or penalties imposed without authority, refund the value of internal revenue stamps when they are returned in good condition by the purchaser, and in his discretion, redeem or change unused stamps that have been rendered unfit for use and refund their value upon proof of destruction. No credit or refund of taxes or penalties shall be allowed unless the taxpayer files in writing with the Commissioner a claim or refund within two (2) years after the payment of the tax or penalty: Provided, however, That a refund filed showing an overpayment shall be considered as a written claim for credit or refund: Provided, further, That That in proper cases, the Commissioner shall grant a refund for taxes or penalties within ninety (90) days from the date of complete submission of the documents in support of the application filed: Provided, furthermore, That should the Commissioner find that the grant of refund is not proper, the Commissioner must state in writing the legal and factual basis for the denial: Provided, finally, That in case of full or partial denial of the claim for tax refund, the taxpayer affected may, within thirty (30) days from the receipt of the decision denying the claim, appeal the decision with the Court of tax Appeals. x x x."},"paragraphs":["Authority of the Commissioner to Compromise, Abate, and Refund or Credit Taxes.","- The Commissioner may - \"(A) x x x \"(B) x x x \"(C) Credit or refund taxes erroneously or illegally received or penalties imposed without authority, refund the value of internal revenue stamps when they are returned in good condition by the purchaser, and in his discretion, redeem or change unused stamps that have been rendered unfit for use and refund their value upon proof of destruction. No credit or refund of taxes or penalties shall be allowed unless the taxpayer files in writing with the Commissioner a claim or refund within two (2) years after the payment of the tax or penalty:","Provided,","however, That a refund filed showing an overpayment shall be considered as a written claim for credit or refund:","Provided,","further, That That in proper cases, the Commissioner shall grant a refund for taxes or penalties within ninety (90) days from the date of complete submission of the documents in support of the application filed:","Provided,","furthermore, That should the Commissioner find that the grant of refund is not proper, the Commissioner must state in writing the legal and factual basis for the denial:","Provided,","finally, That in case of full or partial denial of the claim for tax refund, the taxpayer affected may, within thirty (30) days from the receipt of the decision denying the claim, appeal the decision with the Court of tax Appeals. x x x."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A15","no":15,"noLabel":{"en":"SEC. 290."},"text":{"en":"SEC. 290. Congressional Oversight Committee. \"A Congressional Oversight Committee, hereinafter referred to as the Committee, is herevy constituted in accordance with the provisions of this Code. The Committee shall be composed of the Chairperson of the Committee on Ways and Means of the Senate and House of Representatives and four (4) additional members from each House, to be designated by the"},"paragraphs":["Congressional Oversight Committee.","\"A Congressional Oversight Committee, hereinafter referred to as the Committee, is herevy constituted in accordance with the provisions of this Code. The Committee shall be composed of the Chairperson of the Committee on Ways and Means of the Senate and House of Representatives and four (4) additional members from each House, to be designated by the Speaker of the House of Representatives and the Senate President, respectively. \"The Committee shall, among others, in aid of legislation: \"(1) x x x; \"(2) x x x; \"(3) x x x; \"(4) x x x; and \"(5) Review the performance of the Fiscal Incentives Review Board. x x x."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Section 16. A new Title XIII shall be introduced in the National Internal Revenue Code of 1997, as amended, and the existing Title XIII and XIV shall re-sectioned accordingly. The new title XIII shall read as follows: \" INCENTIVES \" PROVISIONS ON TAX INCENTIVES"},"paragraphs":["A new Title XIII shall be introduced in the National Internal Revenue Code of 1997, as amended, and the existing Title XIII and XIV shall re-sectioned accordingly. The new title XIII shall read as follows:","\"","INCENTIVES \"","PROVISIONS ON TAX INCENTIVES"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A17","no":17,"noLabel":{"en":"SEC. 291."},"chapter":{"en":"CHAPTER IGENERAL PROVISIONS ON TAX INCENTIVES"},"text":{"en":"SEC. 291. Scope and Coverage."},"paragraphs":["Scope and Coverage."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A18","no":18,"noLabel":{"en":"SEC. 292."},"text":{"en":"SEC. 292. Extent of Authority to Grant Tax Incentives."},"paragraphs":["Extent of Authority to Grant Tax Incentives."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A19","no":19,"noLabel":{"en":"SEC. 293."},"text":{"en":"SEC. 293. Definitions. - When used in this title: \"(A) Capital equipment refers to machinery, equipment, major components thereof, tools, devices, applications or apparatus, which are directly or reasonably needed in the registered project or activity of the registered enterprise; \"(B) Direct local employment refers to the full and decent employment of Filipinos by registered business enterprise under a employer-employee relationship to perform functions that are directly related to the production of goods or performance of services under the registered project or activity; \"(C) Domestic input refers to purchases of locally manufactured goods or locally produced raw materials or domestically outsourced services known as services embedded in manufacturing that are used directly in the production of goods under the registered project or activity. In the case of locally manufactured goods, fifty percent (50%) of the value-added of the said good should likewise be locally produced or manufactured; \"(D) Domestic market enterprise refers to any enterprise registered with the Investment Promotion Agency other than export enterprise; \"(E) Export enterprise refers to any individual, partnership, corporation, Philippine branch of a foreign corporation, or other entity organized and existing under Philippine laws and registered with the Investment Promotion Agency to engage in manufacturing, assembling or processing activity, and services such as information technology (IT) activities and business process outsourcing (BPO), and resulting in the direct exportation, and/or sale of its manufactured, assembled or processed product or IT/BPO services to another registered export enterprise that will form part of the final export product or export service of the latter, of at least seventy percent (70%) of its total production or output; \"(F) Freeport zones refers to an isolated and policed area adjacent to a port of entry, which shall be operated and managed as a separate customs territory to ensure free flow or movement of goods, except those expressly prohibited by law, within, into, and exported out of the freeport zone where imported goods may be unloaded for immediate transshipment or stored, repacked, sorted, mixed, or otherwise manipulated without being subject to import duties. However, movement of these imported goods from the free-trade area to a non-free trade area in the country shall be subject to all applicable internal revenue taxes and duties: Provided, That for the freeport to shall have a permanent customs control or customs office at its perimeter; \"(G) Investment capital refers to the value of investment indicated in Philippine currency, excluding the value of land and working capital, that shall be used to carry out a registered project or activity, except that land shall be included as investment capital for registered real estate development. Investment capital may include the cost of land improvements, building, leasehold improvements, machinery and equipment, and other non-current tangible assets; \"(H) Investment Promotion Agencies refer to government entities created by law, executive order, decree or other issuance, in charge of promoting investments, granting and administering tax and non-tax incentives, and overseeing the operations of the different economic zones and freeports in accordance with their respective special laws. These include the Board of Investments (BOI), Regional Board of Investments-Autonomous Region in Muslim Mindanao (RBOI-ARMM), Philippine Economic Zone Authority (PEZA), Bases Conversion and Development Corporation (BCDA), Subic Bay Metropolitan Authority (SBMA), Clark Development Corporation (CDC), John Hay Management Corporation (JHMC), Poro Point Management Corporation (PPMC), Cagayan Economic Zone Authority (CEZA). Zamboanga City Special Economic Zone Authority (ZCSEZA), PHIVIDEC Industrial Authority (PIA), Aurora Pacific Economic Zone and Freeport Authority (APECO), Authority of the Freeport Area of Bataan (AFAB), Tourism Infrastructure and Enterprise Zone Authority (TIEZA), and all other similar existing authorities or that may be created by law unless otherwise specifically exempted from the coverage of this Code; \"(I) Metropolitan areas refers to Metro Cebu and Metro Davao or those local government units which are later qualified or grouped as such by the National Economic Development Authority or through laws or executive issuances; \"(J) Other govenrment agencies administering tax incentives refer to government agencies other than Investment Promotion Agencies which register or administer tax incentives of any kind to any specific entities and/or class of persons pursuant to any law; \"(K) Other registered entities refer to any individual, partnership, organization, corporation, Philippine branch of a foreign corporation, or other entity incorporated and/or organized and existing under Philippine laws, and registered with other government agencies administering tax incentives; \"(L) Qualified capital expenditure refers to purchases of capital goods with a useful life of more than one (1) year acquired for the entity's production of goods and services to be directly used in the project or activity of the registered business enterprise; \"(M) Registered business enterprise refers to any individual, partnership, corporation, Philippine branch of a foreign corporation, or other entity organized and existing under Philippine laws and registered with an Investment Promotion Agency excluding service enterprises such as those engaged in customs brokerage, trucking or forwarding services, janitorial services, security services, insurance, banking, and other financial services, consumers' cooperatives, credit unions, consultancy services, retail enterprises, restaurants, or such other similar services, as may be determined by the Fiscal Incentives Review Board, irrespective of location, whether inside or outside the zones, duly accredited or licensed by any of the Investment Promotion Agencies and whose income delivered within the economic zones shall be subject to taxes under the National Internal Revenue Code of 1997, as amended; \"(N) Research and development refers to experimental or other related projects or activities: \"(1) Whose outcome cannot be known or determined in advance on the basis of current knowledge, information or experience, but can only be determined by applying a systematic progression of work; \"(i) Based on principles of established science; and \"(ii) Proceeds from hypothesis to experiment, observation and evaluation, and leads to logical conclusions. \"(2) That are conducted for the purpose of generating new knowledge, including new knowledge in the form of new or improved materials, products, devices, processes or services; \"(O) Sophisticated refers to the state when a product or service requires a high level of technology, human capital, competencies or know-how, and infrastructure to be produced or offered; \"(P) Sophistication refers to the level of technology, human capital, competencies or know-how, and infrastructure required for a product or service to be offered by an economy like that of the Philippines; \"(Q) Source document refers to input materials and documents reasonable needed by information technology (IT) and IT-enabled industries such as books, directories, magazines, newspapers, brochures, pamphlets, medical records or files, legal records or files, instruction materials, and drawings, blueprints, or outlines; \"(R) Special economic zone or ecozone refers to a selected area, which shall be operated and managed as a separate customs territory that is highly developed or has the potential to be developed into an agro-industrial, industrial, information technology, or tourist/recreational area, whose metes and bounds are fixed or delimited by presidential proclamations and within a specific geographical area which includes industrial estates (IEs), export processing zone (EPZs), ICT parks and centers, and free trade zones: Provided, That for the ecozone to qualify as a separate customs territory, an ecozone shall have a permanent customs control or customs office at its perimeter: Provided, however, That areas where mining extraction is undertaken shall not be declared as an ecozone: Provided, further, That vertical ecozones, such as, but not limited to, buildings, selected floors within buildings, and selected areas on a floor, need to comply with the minimum contiguous land area as determined by the Fiscal Incentives Review Board; and \"(S) Training refers to courses, curricula, certifications or modules provided to Filipino employees that are directly related to the production of goods and performance of service under the registered project or activity and that are of a technical nature, which shall develop or improve the specific skills or practical knowledge of the employee especially in the mechanical, industrial art, scientific field or practical science of a particular position or job function in the registered project or activity, or in preparation for enhancing the value chain.\" \" AND DUTY INCENTIVES"},"paragraphs":["Definitions.","- When used in this title: \"(A) Capital equipment refers to machinery, equipment, major components thereof, tools, devices, applications or apparatus, which are directly or reasonably needed in the registered project or activity of the registered enterprise; \"(B) Direct local employment refers to the full and decent employment of Filipinos by registered business enterprise under a employer-employee relationship to perform functions that are directly related to the production of goods or performance of services under the registered project or activity; \"(C) Domestic input refers to purchases of locally manufactured goods or locally produced raw materials or domestically outsourced services known as services embedded in manufacturing that are used directly in the production of goods under the registered project or activity. In the case of locally manufactured goods, fifty percent (50%) of the value-added of the said good should likewise be locally produced or manufactured; \"(D) Domestic market enterprise refers to any enterprise registered with the Investment Promotion Agency other than export enterprise; \"(E) Export enterprise refers to any individual, partnership, corporation, Philippine branch of a foreign corporation, or other entity organized and existing under Philippine laws and registered with the Investment Promotion Agency to engage in manufacturing, assembling or processing activity, and services such as information technology (IT) activities and business process outsourcing (BPO), and resulting in the direct exportation, and/or sale of its manufactured, assembled or processed product or IT/BPO services to another registered export enterprise that will form part of the final export product or export service of the latter, of at least seventy percent (70%) of its total production or output; \"(F) Freeport zones refers to an isolated and policed area adjacent to a port of entry, which shall be operated and managed as a separate customs territory to ensure free flow or movement of goods, except those expressly prohibited by law, within, into, and exported out of the freeport zone where imported goods may be unloaded for immediate transshipment or stored, repacked, sorted, mixed, or otherwise manipulated without being subject to import duties. However, movement of these imported goods from the free-trade area to a non-free trade area in the country shall be subject to all applicable internal revenue taxes and duties:","Provided,","That for the freeport to shall have a permanent customs control or customs office at its perimeter; \"(G) Investment capital refers to the value of investment indicated in Philippine currency, excluding the value of land and working capital, that shall be used to carry out a registered project or activity, except that land shall be included as investment capital for registered real estate development. Investment capital may include the cost of land improvements, building, leasehold improvements, machinery and equipment, and other non-current tangible assets; \"(H) Investment Promotion Agencies refer to government entities created by law, executive order, decree or other issuance, in charge of promoting investments, granting and administering tax and non-tax incentives, and overseeing the operations of the different economic zones and freeports in accordance with their respective special laws. These include the Board of Investments (BOI), Regional Board of Investments-Autonomous Region in Muslim Mindanao (RBOI-ARMM), Philippine Economic Zone Authority (PEZA), Bases Conversion and Development Corporation (BCDA), Subic Bay Metropolitan Authority (SBMA), Clark Development Corporation (CDC), John Hay Management Corporation (JHMC), Poro Point Management Corporation (PPMC), Cagayan Economic Zone Authority (CEZA). Zamboanga City Special Economic Zone Authority (ZCSEZA), PHIVIDEC Industrial Authority (PIA), Aurora Pacific Economic Zone and Freeport Authority (APECO), Authority of the Freeport Area of Bataan (AFAB), Tourism Infrastructure and Enterprise Zone Authority (TIEZA), and all other similar existing authorities or that may be created by law unless otherwise specifically exempted from the coverage of this Code; \"(I) Metropolitan areas refers to Metro Cebu and Metro Davao or those local government units which are later qualified or grouped as such by the National Economic Development Authority or through laws or executive issuances; \"(J) Other govenrment agencies administering tax incentives refer to government agencies other than Investment Promotion Agencies which register or administer tax incentives of any kind to any specific entities and/or class of persons pursuant to any law; \"(K) Other registered entities refer to any individual, partnership, organization, corporation, Philippine branch of a foreign corporation, or other entity incorporated and/or organized and existing under Philippine laws, and registered with other government agencies administering tax incentives; \"(L) Qualified capital expenditure refers to purchases of capital goods with a useful life of more than one (1) year acquired for the entity's production of goods and services to be directly used in the project or activity of the registered business enterprise; \"(M) Registered business enterprise refers to any individual, partnership, corporation, Philippine branch of a foreign corporation, or other entity organized and existing under Philippine laws and registered with an Investment Promotion Agency excluding service enterprises such as those engaged in customs brokerage, trucking or forwarding services, janitorial services, security services, insurance, banking, and other financial services, consumers' cooperatives, credit unions, consultancy services, retail enterprises, restaurants, or such other similar services, as may be determined by the Fiscal Incentives Review Board, irrespective of location, whether inside or outside the zones, duly accredited or licensed by any of the Investment Promotion Agencies and whose income delivered within the economic zones shall be subject to taxes under the National Internal Revenue Code of 1997, as amended; \"(N) Research and development refers to experimental or other related projects or activities: \"(1) Whose outcome cannot be known or determined in advance on the basis of current knowledge, information or experience, but can only be determined by applying a systematic progression of work; \"(i) Based on principles of established science; and \"(ii) Proceeds from hypothesis to experiment, observation and evaluation, and leads to logical conclusions. \"(2) That are conducted for the purpose of generating new knowledge, including new knowledge in the form of new or improved materials, products, devices, processes or services; \"(O) Sophisticated refers to the state when a product or service requires a high level of technology, human capital, competencies or know-how, and infrastructure to be produced or offered; \"(P) Sophistication refers to the level of technology, human capital, competencies or know-how, and infrastructure required for a product or service to be offered by an economy like that of the Philippines; \"(Q) Source document refers to input materials and documents reasonable needed by information technology (IT) and IT-enabled industries such as books, directories, magazines, newspapers, brochures, pamphlets, medical records or files, legal records or files, instruction materials, and drawings, blueprints, or outlines; \"(R) Special economic zone or ecozone refers to a selected area, which shall be operated and managed as a separate customs territory that is highly developed or has the potential to be developed into an agro-industrial, industrial, information technology, or tourist/recreational area, whose metes and bounds are fixed or delimited by presidential proclamations and within a specific geographical area which includes industrial estates (IEs), export processing zone (EPZs), ICT parks and centers, and free trade zones:","Provided,","That for the ecozone to qualify as a separate customs territory, an ecozone shall have a permanent customs control or customs office at its perimeter:","Provided,","however, That areas where mining extraction is undertaken shall not be declared as an ecozone:","Provided,","further, That vertical ecozones, such as, but not limited to, buildings, selected floors within buildings, and selected areas on a floor, need to comply with the minimum contiguous land area as determined by the Fiscal Incentives Review Board; and \"(S) Training refers to courses, curricula, certifications or modules provided to Filipino employees that are directly related to the production of goods and performance of service under the registered project or activity and that are of a technical nature, which shall develop or improve the specific skills or practical knowledge of the employee especially in the mechanical, industrial art, scientific field or practical science of a particular position or job function in the registered project or activity, or in preparation for enhancing the value chain.\"","\"","AND DUTY INCENTIVES"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A20","no":20,"noLabel":{"en":"SEC. 294."},"chapter":{"en":"CHAPTER IITAX AND DUTY INCENTIVES"},"text":{"en":"SEC. 294. Incentives. - Subject to the condition and period of availment in Sections 295 and 296, respectively, the following types of tax incentives may be granted to registered projects or activities: \"(A) Income Tax Holiday (ITH); \"(B) Special Corporate Income Tax (SCIT) Rate - For export enterprise, domestic market enterprise with a minimum investment capital of Five hundred million pesos (P500,000,000.00), and domestic market enterprise under the Strategic Investment Priority Plan engaged in activities that are classified as 'critical', a tax rate equivalent to five percent (5%) effective July 1, 2020, based on the gross income earned, in lieu of all national and local taxes. \"The domestic market enterprise under the Strategic Investment Priority Plan engaged in activities that are classified as 'critical' shall refer to those enterprises belonging to industries identified by the National Economic and Development Authority to be crucial to national development. \"The period of availment of the Special Corporate Income Tax shall be subject to the conditions set under paragraphs (A) and (B) of Section 296 of this Act: \" Provided, That the national government share shall be three percent (3%) of the gross income earned effective July 1, 2020: Provided, further, That, if applicable, the shares of the local government units and the Investment Promotion Agencies under the special laws governing the latter shall be observed and shall not result in the diminution of their respective shares: Provided,"},"paragraphs":["Incentives.","- Subject to the condition and period of availment in Sections 295 and 296, respectively, the following types of tax incentives may be granted to registered projects or activities: \"(A) Income Tax Holiday (ITH); \"(B) Special Corporate Income Tax (SCIT) Rate - For export enterprise, domestic market enterprise with a minimum investment capital of Five hundred million pesos (P500,000,000.00), and domestic market enterprise under the Strategic Investment Priority Plan engaged in activities that are classified as 'critical', a tax rate equivalent to five percent (5%) effective July 1, 2020, based on the gross income earned, in lieu of all national and local taxes. \"The domestic market enterprise under the Strategic Investment Priority Plan engaged in activities that are classified as 'critical' shall refer to those enterprises belonging to industries identified by the National Economic and Development Authority to be crucial to national development. \"The period of availment of the Special Corporate Income Tax shall be subject to the conditions set under paragraphs (A) and (B) of Section 296 of this Act: \"","Provided,","That the national government share shall be three percent (3%) of the gross income earned effective July 1, 2020:","Provided,","further, That, if applicable, the shares of the local government units and the Investment Promotion Agencies under the special laws governing the latter shall be observed and shall not result in the diminution of their respective shares:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A21","no":21,"noLabel":{"en":"SEC. 295."},"text":{"en":"SEC. 295. Conditions of Availment. - The tax incentives in the preceding Section shall be governed by the following rules: \"(A) The income tax holiday shall be followed by the Special Corporate Income Tax rate or Enhanced Deductions. \"(B) At the option of the export enterprise, the domestic market enterprise with a minimum investment capital of Five hundred million pesos (P500,000,000.00), and the domestic market enterprise engaged in activities that are classified as 'critical,' the Special Corporate Income Tax rate or enhanced deductions shall be granted: Provided, That in no case shall the enhanced deductions be granted simultaneously with the Special Corporate Income Tax. \"The following conditions for the availment of each enhanced deductions shall complied with: \"(1) The depreciation allowance of the assets acquired for the entity's production of goods and services (qualified capital expenditure) shall be allowed for assets that are directly related to the registered enterprise's production of goods and services other than administrative and other support services. \"(2) The additional deduction on the labor expense shall not include salaries, wages, benefits, and other personnel costs incurred for managerial, administrative, indirect, labor,, and support services. \"(3) The additional deduction on research and development expense shall only apply to research and development directly related to the registered project or activity of the entity and shall be limited to local expenditure incurred for salaries of Filipino employees and consumables and payments of local research and development organizations. \"(4) The additional deduction on the labor expense shall not include salaries, wages, benefits, and other personnel costs incurred for managerial, administrative, indirect labor, and support services. \"(5) The additional deduction on domestic input expense shall only apply to domestic input that are directly related to and actually used in the registered export project or activity of the registered business enterprise. \"(6) The additional deduction on power expense shall only apply to power utilized for the registered project or activity. \"(7) The deduction for reinvestment allowance to manufacturing industry shall be determined in the Strategic Investment Priority Plan. \"(C) The duty exemption shall only apply to the importation of capital equipment, raw materials, spare parts, or accessories directly and exclusively used in the registered project or activity by registered business enterprises: Provided, That the following conditions are complied with: \"(1) The capital equipment, raw materials, spare parts, or accessories are directly and reasonably needed and will be used exclusively in and as part of the direct cost of the registered project or activity of the registered business enterprise, and are not produced or manufactured domestically in sufficient quantity or of comparable quality and at reasonable prices. Prior approval of the Investment Promotion Agency may be secured for the part-time utilization of said capital equipment, raw materials, spare parts, or accessories in a non-registered project or activity to maximize usage thereof: Provided, That the proportionate taxes and duties are paid on a specific capital equipment, raw materials, spare parts, or accessories in proportion to the utilization for non-registered projects or activities. In the event that the capital equipment, raw materials, spare parts, or accessories shall be used for a non-registered project or activity of the registered business enterprise at any time within the first five (5) years from the date of importation, the registered business enterprise shall first seek prior approval of the concerned Investment Promotion Agency and pay the taxes and customs duties that were not paid upon the importation; and \"(2) The approval of the Investment Promotion Agency was obtained by the registered business enterprise prior to the importation of such capital equipment, raw materials, spare parts, or accessories. \"Within the first five (5) years from the date of importation, approval of the Investment Promotion Agency must be secured before the sale, transfer, or disposition of the capital equipment, raw materials, spare parts, or accessories, which were granted tax and customs duty exemption hereunder, and shall be allowed only under the following circumstances: \"(a) If made to another enterprise availing customs duty exemption on imported capital equipment, raw materials, spare parts, or accessories; \"(b) If made to another enterprise not availing of duty exemption on imported capital equipment, raw materials, spare parts, or accessories, upon payment of any taxes and duties due on t he net book value of the capital equipment, raw materials, spare parts, accessories to be sold; \"(c) Exportation of capital equipment, raw materials, spare parts, accessories, source documents, or those required for pollution abatement and control; \"(d) Proven technical obsolescence of the capital equipment, raw materials, spare parts, accessories; or \"(e) If donated to the TESDA, state universities and colleges (SUCs), or DepEd and CHED-accredited schools: Provided, That the donation shall be exempt from import duties and taxes, including donor's tax. \" Provided, That if the registered business enterprise sells, transfers, or dispose the aforementioned imported items without prior approval, the registered business enterprise and the vendee, transferee, or assignee shall be solidarily liable to pay twice the amount of the duty exemption that should have been paid during its importation: Provided, further, That the sale, transfer, or disposition of the capital equipment, raw materials, spare parts, or accessories made after five (5) years from date of importation shall require that prior notice to be given by the registered business enterprise to the Investment Promotion Agency: Provided, finally, That even if the sale, transfer, or disposition of the capital equipment, raw materials, spare parts or accessories was made after five (5) years from date of importation with notice to the Investment Promotion Agency, the registered business enterprise is still liable to pay the duties based on the net book value of the capital equipment, raw materials, spare parts, or accessories if it has violated any of its registration terms and conditions. \"(D) The VAT exemption on importation and VAT zero-rating on local purchases shall only apply to goods and services directly and exclusively used in the registered projects or activity by a registered business enterprise. \"Notwithstanding the provisions in the preceding paragraphs, sales receipts and other income derived from non-registered project or activity shall be subject to appropriate taxes imposed under this Code. \"(E) Notwithstanding any law to the contrary, the importation of COVID-19 vaccine shall be exempt from import duties, taxes and other fees, subject to the approval or licenses issued by the Department of Health or the Food and Drug Administration. \"(F) Persons who directly import petroleum products defined under Republic Act No. 8479, otherwise known as the 'Downstream Oil Industry Deregulation Act of 1998', for resale in the Philippine customs territory and/or in free zones as defined under Republic Act No. 10863, otherwise known as the Customs Modernization and Tariff Act, shall not be entitled to the foregoing tax and duty incentives, and shall be subject to appropriate taxes imposed under this Code. \"Any law to the contrary notwithstanding, the importation of petroleum products by any person, including registered business enterprises shall be subject to the payment of applicable duties and taxes as provided under Republic Act No. 10863, otherwise known as the Customs Modernization and Tariff Act, and this Code, respectively, upon importation into the Philippine customs territory and/or into free zones as defined under Republic Act No. 10863, otherwise known as the Customs Modernization and tariff Act: \" Provided, That the importer can file for claims for the refund of duties and taxes applicable under Republic Act No. 10863, otherwise known as the Customs Modernization and Tariff Act, and this Code, respectively, for direct or indirect export of petroleum products, and/or tax-exempt sales under the Customs Modernization and Tariff Act and other special laws within the period provided therein: \" Provided, further, That the importers who subsequently export fuel, subject to the appropriate rules of the fuel marking program, may apply for a refund of duties and taxes, as applicable under Republic Act No. 10863, otherwise known as the Customs Modernization and Tariff Act, and this Code. \"(G) Crude oil that is intended to be refined at a local refinery, including the volumes that are lost and not converted to petroleum products when the crude oil actually undergoes the refining process, shall be exempt from payment of applicable duties and taxes upon importation: \" Provided,"},"paragraphs":["Conditions of Availment.","- The tax incentives in the preceding Section shall be governed by the following rules: \"(A) The income tax holiday shall be followed by the Special Corporate Income Tax rate or Enhanced Deductions. \"(B) At the option of the export enterprise, the domestic market enterprise with a minimum investment capital of Five hundred million pesos (P500,000,000.00), and the domestic market enterprise engaged in activities that are classified as 'critical,' the Special Corporate Income Tax rate or enhanced deductions shall be granted:","Provided,","That in no case shall the enhanced deductions be granted simultaneously with the Special Corporate Income Tax. \"The following conditions for the availment of each enhanced deductions shall complied with: \"(1) The depreciation allowance of the assets acquired for the entity's production of goods and services (qualified capital expenditure) shall be allowed for assets that are directly related to the registered enterprise's production of goods and services other than administrative and other support services. \"(2) The additional deduction on the labor expense shall not include salaries, wages, benefits, and other personnel costs incurred for managerial, administrative, indirect, labor,, and support services. \"(3) The additional deduction on research and development expense shall only apply to research and development directly related to the registered project or activity of the entity and shall be limited to local expenditure incurred for salaries of Filipino employees and consumables and payments of local research and development organizations. \"(4) The additional deduction on the labor expense shall not include salaries, wages, benefits, and other personnel costs incurred for managerial, administrative, indirect labor, and support services. \"(5) The additional deduction on domestic input expense shall only apply to domestic input that are directly related to and actually used in the registered export project or activity of the registered business enterprise. \"(6) The additional deduction on power expense shall only apply to power utilized for the registered project or activity. \"(7) The deduction for reinvestment allowance to manufacturing industry shall be determined in the Strategic Investment Priority Plan. \"(C) The duty exemption shall only apply to the importation of capital equipment, raw materials, spare parts, or accessories directly and exclusively used in the registered project or activity by registered business enterprises:","Provided,","That the following conditions are complied with: \"(1) The capital equipment, raw materials, spare parts, or accessories are directly and reasonably needed and will be used exclusively in and as part of the direct cost of the registered project or activity of the registered business enterprise, and are not produced or manufactured domestically in sufficient quantity or of comparable quality and at reasonable prices. Prior approval of the Investment Promotion Agency may be secured for the part-time utilization of said capital equipment, raw materials, spare parts, or accessories in a non-registered project or activity to maximize usage thereof:","Provided,","That the proportionate taxes and duties are paid on a specific capital equipment, raw materials, spare parts, or accessories in proportion to the utilization for non-registered projects or activities. In the event that the capital equipment, raw materials, spare parts, or accessories shall be used for a non-registered project or activity of the registered business enterprise at any time within the first five (5) years from the date of importation, the registered business enterprise shall first seek prior approval of the concerned Investment Promotion Agency and pay the taxes and customs duties that were not paid upon the importation; and \"(2) The approval of the Investment Promotion Agency was obtained by the registered business enterprise prior to the importation of such capital equipment, raw materials, spare parts, or accessories. \"Within the first five (5) years from the date of importation, approval of the Investment Promotion Agency must be secured before the sale, transfer, or disposition of the capital equipment, raw materials, spare parts, or accessories, which were granted tax and customs duty exemption hereunder, and shall be allowed only under the following circumstances: \"(a) If made to another enterprise availing customs duty exemption on imported capital equipment, raw materials, spare parts, or accessories; \"(b) If made to another enterprise not availing of duty exemption on imported capital equipment, raw materials, spare parts, or accessories, upon payment of any taxes and duties due on t he net book value of the capital equipment, raw materials, spare parts, accessories to be sold; \"(c) Exportation of capital equipment, raw materials, spare parts, accessories, source documents, or those required for pollution abatement and control; \"(d) Proven technical obsolescence of the capital equipment, raw materials, spare parts, accessories; or \"(e) If donated to the TESDA, state universities and colleges (SUCs), or DepEd and CHED-accredited schools:","Provided,","That the donation shall be exempt from import duties and taxes, including donor's tax. \"","Provided,","That if the registered business enterprise sells, transfers, or dispose the aforementioned imported items without prior approval, the registered business enterprise and the vendee, transferee, or assignee shall be solidarily liable to pay twice the amount of the duty exemption that should have been paid during its importation:","Provided,","further, That the sale, transfer, or disposition of the capital equipment, raw materials, spare parts, or accessories made after five (5) years from date of importation shall require that prior notice to be given by the registered business enterprise to the Investment Promotion Agency:","Provided,","finally, That even if the sale, transfer, or disposition of the capital equipment, raw materials, spare parts or accessories was made after five (5) years from date of importation with notice to the Investment Promotion Agency, the registered business enterprise is still liable to pay the duties based on the net book value of the capital equipment, raw materials, spare parts, or accessories if it has violated any of its registration terms and conditions. \"(D) The VAT exemption on importation and VAT zero-rating on local purchases shall only apply to goods and services directly and exclusively used in the registered projects or activity by a registered business enterprise. \"Notwithstanding the provisions in the preceding paragraphs, sales receipts and other income derived from non-registered project or activity shall be subject to appropriate taxes imposed under this Code. \"(E) Notwithstanding any law to the contrary, the importation of COVID-19 vaccine shall be exempt from import duties, taxes and other fees, subject to the approval or licenses issued by the Department of Health or the Food and Drug Administration. \"(F) Persons who directly import petroleum products defined under Republic Act No. 8479, otherwise known as the 'Downstream Oil Industry Deregulation Act of 1998', for resale in the Philippine customs territory and/or in free zones as defined under Republic Act No. 10863, otherwise known as the Customs Modernization and Tariff Act, shall not be entitled to the foregoing tax and duty incentives, and shall be subject to appropriate taxes imposed under this Code. \"Any law to the contrary notwithstanding, the importation of petroleum products by any person, including registered business enterprises shall be subject to the payment of applicable duties and taxes as provided under Republic Act No. 10863, otherwise known as the Customs Modernization and Tariff Act, and this Code, respectively, upon importation into the Philippine customs territory and/or into free zones as defined under Republic Act No. 10863, otherwise known as the Customs Modernization and tariff Act: \"","Provided,","That the importer can file for claims for the refund of duties and taxes applicable under Republic Act No. 10863, otherwise known as the Customs Modernization and Tariff Act, and this Code, respectively, for direct or indirect export of petroleum products, and/or tax-exempt sales under the Customs Modernization and Tariff Act and other special laws within the period provided therein: \"","Provided,","further, That the importers who subsequently export fuel, subject to the appropriate rules of the fuel marking program, may apply for a refund of duties and taxes, as applicable under Republic Act No. 10863, otherwise known as the Customs Modernization and Tariff Act, and this Code. \"(G) Crude oil that is intended to be refined at a local refinery, including the volumes that are lost and not converted to petroleum products when the crude oil actually undergoes the refining process, shall be exempt from payment of applicable duties and taxes upon importation: \"","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A22","no":22,"noLabel":{"en":"SEC. 296."},"text":{"en":"SEC. 296. Period of Availment. - The period of availment of incentives by the registered business enterprise shall be as follows: \"(A) For export enterprise and for domestic market enterprise under the Strategic Investment Priority Plan engaged in activities that are classified as 'critical': income tax holiday of four (4) to seven (7) years, depending on location and industry policies as specified in this Section, and followed by special corporate income tax rate or enhanced deductions for ten (10) years. \"A qualified expansion or entirely new project or activity registered under this Act may qualify to avail of a new set of incentives and its period of availment, granted under Sections 294 and 296 of this Act, respectively, subject to the qualifications set forth in the Strategic Investment Priority Plan and performance review of the Fiscal Incentives Review Board: Provided, That existing registered projects or activities prior ti the effectivity of this Act may qualify to register and avail of the incentives granted under this Act for the prescribed period, subject to the criteria and conditions set forth in Strategic Investment Priority Plan; \"(B) For domestic market enterprise under the Strategic Investment Priority Plan not classified as critical, income tax holiday for four (4) to seven (7) years followed by special corporate income tax or enhanced deductions for five (5) years: \" Provided, That only domestic market enterprise, which has an investment capital of not less than Five hundred million pesos (P500,000,000.00), shall be eligible for the special corporate income tax rate. \"A qualified expansion or entirely new project or activity registered under this Act may qualify to avail of a new set of incentives and its period of availment granted under Section 294 and 296 of this Act, respectively, subject to the qualifications set forth in the Strategic Investment Priority Plan and performance review by the Fiscal Incentives Review Board: Provided, That existing registered projects or activities prior to the effectivity of this Act may qualify to register and avail of the incentives granted under this Act for the prescribed period, subject to the criteria and conditions set forth in the Strategic Investment Priority Plan. \"The period of availment of the foregoing incentives shall commence from the actual start of commercial operations with the registered business enterprise availing of the tax incentives within three (3) years from the date of registration, unless otherwise provided in the Strategic Investment Priority Plan and its corresponding guidelines: Provided, That after the expiration of the transitory period under Section 311(C), export enterprises registered prior to the effectivity of this Act shall have the option to reapply and avail of the incentives granted under Section 249(B) for the same period provided under this Section, and may still be extended for a certain period not exceeding ten (10) years at any one time, subject to the conditions and qualifications set forth in the Strategic Investment Priority Plan and performance review by the Fiscal Incentives Review Board. \"For the purpose of this Section, the determination of the category shall be based on both location and industry of the registered project or activity, and other relevant factors as may be defined in the Strategic Investment Priority Plan. \"The location of the registered project or activity shall be prioritized according to the level of development as follows: (1) National Capital Region; (2) metropolitan areas or areas contiguous and adjacent to the National Capital Region; and (3) all other areas. The metropolitan areas shall be determined by the National Economic and Development Authority. \"The industry of the registered project or activity shall be prioritized according to national industrial strategy specified in the Strategic Investment Priority Plan. The Strategic Investment Priority Plan shall define the coverage of the tiers and provide the conditions for qualifying the activities: \"(1) Tier I shall include activities that (i) have high potential for job creation; (ii) take place in sectors with market failures resulting in under provision of basic goods and services; (iii) generate value creation through innovation, upgrading or moving up the value chain; (iv) provide essential support for sectors that are critical to industrial development; or (v) are emerging owing to potential comparative advantage. \"These activities shall include agriculture, fishing, forestry, and agribusiness activities, including handicrafts intended for export, and energy; ecozone and freeport zone development; manufacturing of medical supplies, devices and equipment, and construction of healthcare facilities; facilities for environmentally-sustainable disposal of waste; infrastructure; manufacturing and service industries that are emerging resulting from innovation, upgrading or addressing gaps in the supply and value chain; mass housing, as well as infrastructure, transportation, utilities, logistics and support services; the provision of cyber security services; and planned developments that use technologies and digital solutions that are crucial to the country's development. \"(2) Tier II shall include activities that produce supplies, parts and components, and intermediate services that are not locally produced but are critical to industrial development and import-substituting activities, including crude oil refining. \"(3) Tier III activities shall include (i) research and development resulting in demonstrably significant value-added, higher productivity, improved efficiency, breakthroughs in science and health, and high-paying jobs; (ii) generation of new knowledge and intellectual property registered and/or licensed in the Philippines; (iii) commercialization of patents, industrial designs, copyrights and utlity models owned or co-owned by a registered business enterprise; (iv) highly yechnical manufacturing; or (v) are critical to the structural transformation of the economy and require substantial catch-up efforts. \"These activities shall include agriculture, fishing, forestry agribusiness, and other activities and services that indispensably require the employment of knowledge processing, modern science; data analytics; creative content; engineering; state of the art technologies; technologies that are available in other countries but are not yet available or widely used in the Philippines; and research and development in the process of production of goods and services, resulting in demonstrably significant value-added, productivity, efficiency, breakthroughs in science and health, and high-paying jobs; and manufacturing of FDA-approved investigational drugs, medicines and medical devices. \"The period of availment of incentives based on the combination of both location and industry priorities, as determined in the Strategic Investment Priority Plan, shall be as follows: Location/Industry Tiers Tier I Tier II Tier III National Capital Region 4 ITH + 10 ED/SCIT 5 ITH + 10 ED/SCIT 6 ITH + 10 ED/SCIT Metropolitan areas or areas contiguous and adjacent to the National Capital Region 5 ITH + 10 ED/SCIT 6 ITH + 10 ED/SCIT 7 ITH + 10 ED/SCIT All other areas 6 ITH + 10 ED/SCIT 7 ITH + 10 ED/SCIT 7 ITH + 10 ED/SCIT \"For domestic market activities: Location/Industry Tiers Tier I Tier II Tier III National Capital Region 4 ITH + 5 ED/SCIT 5 ITH + 5 ED/SCIT 6 ITH + 5 ED/SCIT Metropolitan areas or areas contiguous and adjacent to the National Capital Region 5 ITH + 5 ED/SCIT 6 ITH + 5 ED/SCIT 7 ITH + 5 ED/SCIT All other areas 6 ITH + 5 ED/SCIT 7 ITH + 5 ED/SCIT 7 ITH + 5 ED/SCIT \"In addition to the incentives provided in tiers above, projects or activities of registered enterprises located in areas recovering from armed conflict or a major disaster, as determined by the Office of the President, shall be entitled to two (2) additional years of income tax holiday. \"Projects or activities registered prior to the effectivity of this Act, or under the incentive system provided herein that shall, in the duration of their incentives, completely relocate from the National Capital Region,, shall be entitled to three (3) additional years of income tax holiday: Provided, That the additional incentive shall commence at the completion of the relocation of operations. \"The industry and locational prioritization specified herein shall be subject to review and revision every three (3) years in accordance with the Strategic Investment Priority Plan, subject to the standards in Section 300 hereof, or in exceptional circumstances, to attract substantial investment to respond to a situation or crisis or to target specific industries. \" FISCAL INCENTIVES REVIEW BOARD"},"paragraphs":["Period of Availment.","- The period of availment of incentives by the registered business enterprise shall be as follows: \"(A) For export enterprise and for domestic market enterprise under the Strategic Investment Priority Plan engaged in activities that are classified as 'critical': income tax holiday of four (4) to seven (7) years, depending on location and industry policies as specified in this Section, and followed by special corporate income tax rate or enhanced deductions for ten (10) years. \"A qualified expansion or entirely new project or activity registered under this Act may qualify to avail of a new set of incentives and its period of availment, granted under Sections 294 and 296 of this Act, respectively, subject to the qualifications set forth in the Strategic Investment Priority Plan and performance review of the Fiscal Incentives Review Board:","Provided,","That existing registered projects or activities prior ti the effectivity of this Act may qualify to register and avail of the incentives granted under this Act for the prescribed period, subject to the criteria and conditions set forth in Strategic Investment Priority Plan; \"(B) For domestic market enterprise under the Strategic Investment Priority Plan not classified as critical, income tax holiday for four (4) to seven (7) years followed by special corporate income tax or enhanced deductions for five (5) years: \"","Provided,","That only domestic market enterprise, which has an investment capital of not less than Five hundred million pesos (P500,000,000.00), shall be eligible for the special corporate income tax rate. \"A qualified expansion or entirely new project or activity registered under this Act may qualify to avail of a new set of incentives and its period of availment granted under Section 294 and 296 of this Act, respectively, subject to the qualifications set forth in the Strategic Investment Priority Plan and performance review by the Fiscal Incentives Review Board:","Provided,","That existing registered projects or activities prior to the effectivity of this Act may qualify to register and avail of the incentives granted under this Act for the prescribed period, subject to the criteria and conditions set forth in the Strategic Investment Priority Plan. \"The period of availment of the foregoing incentives shall commence from the actual start of commercial operations with the registered business enterprise availing of the tax incentives within three (3) years from the date of registration, unless otherwise provided in the Strategic Investment Priority Plan and its corresponding guidelines:","Provided,","That after the expiration of the transitory period under Section 311(C), export enterprises registered prior to the effectivity of this Act shall have the option to reapply and avail of the incentives granted under Section 249(B) for the same period provided under this Section, and may still be extended for a certain period not exceeding ten (10) years at any one time, subject to the conditions and qualifications set forth in the Strategic Investment Priority Plan and performance review by the Fiscal Incentives Review Board. \"For the purpose of this Section, the determination of the category shall be based on both location and industry of the registered project or activity, and other relevant factors as may be defined in the Strategic Investment Priority Plan. \"The location of the registered project or activity shall be prioritized according to the level of development as follows: (1) National Capital Region; (2) metropolitan areas or areas contiguous and adjacent to the National Capital Region; and (3) all other areas. The metropolitan areas shall be determined by the National Economic and Development Authority. \"The industry of the registered project or activity shall be prioritized according to national industrial strategy specified in the Strategic Investment Priority Plan. The Strategic Investment Priority Plan shall define the coverage of the tiers and provide the conditions for qualifying the activities: \"(1) Tier I shall include activities that (i) have high potential for job creation; (ii) take place in sectors with market failures resulting in under provision of basic goods and services; (iii) generate value creation through innovation, upgrading or moving up the value chain; (iv) provide essential support for sectors that are critical to industrial development; or (v) are emerging owing to potential comparative advantage. \"These activities shall include agriculture, fishing, forestry, and agribusiness activities, including handicrafts intended for export, and energy; ecozone and freeport zone development; manufacturing of medical supplies, devices and equipment, and construction of healthcare facilities; facilities for environmentally-sustainable disposal of waste; infrastructure; manufacturing and service industries that are emerging resulting from innovation, upgrading or addressing gaps in the supply and value chain; mass housing, as well as infrastructure, transportation, utilities, logistics and support services; the provision of cyber security services; and planned developments that use technologies and digital solutions that are crucial to the country's development. \"(2) Tier II shall include activities that produce supplies, parts and components, and intermediate services that are not locally produced but are critical to industrial development and import-substituting activities, including crude oil refining. \"(3) Tier III activities shall include (i) research and development resulting in demonstrably significant value-added, higher productivity, improved efficiency, breakthroughs in science and health, and high-paying jobs; (ii) generation of new knowledge and intellectual property registered and/or licensed in the Philippines; (iii) commercialization of patents, industrial designs, copyrights and utlity models owned or co-owned by a registered business enterprise; (iv) highly yechnical manufacturing; or (v) are critical to the structural transformation of the economy and require substantial catch-up efforts. \"These activities shall include agriculture, fishing, forestry agribusiness, and other activities and services that indispensably require the employment of knowledge processing, modern science; data analytics; creative content; engineering; state of the art technologies; technologies that are available in other countries but are not yet available or widely used in the Philippines; and research and development in the process of production of goods and services, resulting in demonstrably significant value-added, productivity, efficiency, breakthroughs in science and health, and high-paying jobs; and manufacturing of FDA-approved investigational drugs, medicines and medical devices. \"The period of availment of incentives based on the combination of both location and industry priorities, as determined in the Strategic Investment Priority Plan, shall be as follows: Location/Industry Tiers Tier I Tier II Tier III National Capital Region 4 ITH + 10 ED/SCIT 5 ITH + 10 ED/SCIT 6 ITH + 10 ED/SCIT Metropolitan areas or areas contiguous and adjacent to the National Capital Region 5 ITH + 10 ED/SCIT 6 ITH + 10 ED/SCIT 7 ITH + 10 ED/SCIT All other areas 6 ITH + 10 ED/SCIT 7 ITH + 10 ED/SCIT 7 ITH + 10 ED/SCIT \"For domestic market activities: Location/Industry Tiers Tier I Tier II Tier III National Capital Region 4 ITH + 5 ED/SCIT 5 ITH + 5 ED/SCIT 6 ITH + 5 ED/SCIT Metropolitan areas or areas contiguous and adjacent to the National Capital Region 5 ITH + 5 ED/SCIT 6 ITH + 5 ED/SCIT 7 ITH + 5 ED/SCIT All other areas 6 ITH + 5 ED/SCIT 7 ITH + 5 ED/SCIT 7 ITH + 5 ED/SCIT \"In addition to the incentives provided in tiers above, projects or activities of registered enterprises located in areas recovering from armed conflict or a major disaster, as determined by the Office of the President, shall be entitled to two (2) additional years of income tax holiday. \"Projects or activities registered prior to the effectivity of this Act, or under the incentive system provided herein that shall, in the duration of their incentives, completely relocate from the National Capital Region,, shall be entitled to three (3) additional years of income tax holiday:","Provided,","That the additional incentive shall commence at the completion of the relocation of operations. \"The industry and locational prioritization specified herein shall be subject to review and revision every three (3) years in accordance with the Strategic Investment Priority Plan, subject to the standards in Section 300 hereof, or in exceptional circumstances, to attract substantial investment to respond to a situation or crisis or to target specific industries. \"","FISCAL INCENTIVES REVIEW BOARD"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A23","no":23,"noLabel":{"en":"SEC. 297."},"chapter":{"en":"CHAPTER IIITHE FISCAL INCENTIVES REVIEW BOARD"},"text":{"en":"SEC. 297. Expanded Functions of the Fiscal Incentives Review Board. - The functions and powers of the Fiscal Incentives Review Board created under Presidential Decree No. 776, as amended, shall be expanded as follows: \"(A) To exercise policy making and oversight functions on the administration and grant of tax incentives by the Investment Promotion Agencies and other govenrment agencies administering tax incentives. In particular, the Fiscal Incentives Review Board shall: \"(1) Determine the target performance metrics as conditions to avail of tax incentives; \"(2) Review and audit the compliance of other government agencies administering tax incentives, with respect to the administration and grant of tax incentives and impose sanctions such as, but not limited to, withdrawal, suspension, or cancellation of their power to grant tax incentives; \"(3) Determine the minimum contiguous land area that vertical economic zones should comply with; \"(4) Conduct regular monitoring and evaluation of investment and non-investment tax incentives, such as using cost-benefit analysis (CBA) to determine their impact on the economy and whether agreed performance targets are met; and \"(5) Check and verify, as necessary, the compliance of registered business enterprises with the terms and conditions of their availment, in particular the agreed target performance metrics, rules and regulations of this Act, and other relevant laws or issuances; \"(B) To approved or disapprove, the grant of tax incentives to the extent of the registered project or activity upon the recommendation of the Investment Promotion Agency: Provided, That the application for tax incentives shall be duly accompanied by a cost-benefit analysis: Provided, further, That the Fiscal Incentives Review Board shall prescribe the data requirements for the application of incentives to allow for the calculation of costs and benefits upon application: Provided, further, That the grant of tax incentives with investment capital of One billion pesos (P1,000,000,000.00) and below shall be delegated by the Fiscal Incentives Review Board to the concerned Investment Promotion Agency to the extent of the registered project or activity: Provided, furthermore, That the Fiscal Incentives Review Board may increase the threshold amount of One billion pesos (P1,000,000,000.00): Provided, finally, That the application for tax incentives shall be deemed approved if not acted upon within twenty (20) days from the date of submission of the application and complete relevant supporting documents to the Fiscal Incentives Review Board or the Investment Promotion Agency, as the case may be; \"(C) To approve applications for tax subsidies to government-owned or controlled- corporations, government instrumentalities, government commissaries, and state universities and colleges. \"For this purpose, the other government agencies shall ensure complete submission of applications, documents, records, books, or other relevant data or material; \"(D) To formulate place-specific strategic investment plans during periods of recovery from calamities and post-conflict situations and where the Fiscal Incentives Review Board determines that there is a need to attract many classes, firms, that would accelerate the growth of a region's flagship industries, in accordance with the Medium-Term Development Plan. The Fiscal Incentives Review Board may formulate and approve place-specific strategic investment plans and recommend incentives to the President, following the same procedure in Section 297; \"(E) To cancel, suspend, or withdraw the enjoyment of fiscal incentives of concerned registered business enterprises on its own initiative or upon the recommendation of the Investment Promotion Agency for material violations of any of the conditions imposed in the grant of fiscal incentives, including, but not limited to, the non-compliance of the agreed performance commitments and endorse registered business enterprises whose incentives are cancelled, suspended, or withdrawn to the concerned revenue agencies for the assessment and collection of taxes and duties due commencing from the first year of availment; \"(F) To cancel, suspend, or withdraw the enjoyment of tax subsidy of concerned government-owned or controlled corporations, government commissaries, and state universities and colleges, and when necessary, endorse the same to the concerned revenue agencies for assessment and collection of taxes and duties due, including fines or penalties, if warranted, for violations of any of the conditions imposed in the grant of tax subsidy, or provisions of this Act, or applicable rules; \"(G) To require Investment Promotion Agencies and other government agencies administering tax incentives to submit, regularly or when requested, summaries of approved investment and incentives granted, and firm-or entity-level tax incentives and benefits data as input to the Fiscal Incentives Review Board's review and audit function, and evaluation of performance of recipients of tax incentives. For this purpose, the Fiscal Incentives Review Board shall maintain a masterlist of registered products and services for export or domestic consumption that are entitled to incentives: Provided,"},"paragraphs":["Expanded Functions of the Fiscal Incentives Review Board.","- The functions and powers of the Fiscal Incentives Review Board created under Presidential Decree No. 776, as amended, shall be expanded as follows: \"(A) To exercise policy making and oversight functions on the administration and grant of tax incentives by the Investment Promotion Agencies and other govenrment agencies administering tax incentives. In particular, the Fiscal Incentives Review Board shall: \"(1) Determine the target performance metrics as conditions to avail of tax incentives; \"(2) Review and audit the compliance of other government agencies administering tax incentives, with respect to the administration and grant of tax incentives and impose sanctions such as, but not limited to, withdrawal, suspension, or cancellation of their power to grant tax incentives; \"(3) Determine the minimum contiguous land area that vertical economic zones should comply with; \"(4) Conduct regular monitoring and evaluation of investment and non-investment tax incentives, such as using cost-benefit analysis (CBA) to determine their impact on the economy and whether agreed performance targets are met; and \"(5) Check and verify, as necessary, the compliance of registered business enterprises with the terms and conditions of their availment, in particular the agreed target performance metrics, rules and regulations of this Act, and other relevant laws or issuances; \"(B) To approved or disapprove, the grant of tax incentives to the extent of the registered project or activity upon the recommendation of the Investment Promotion Agency:","Provided,","That the application for tax incentives shall be duly accompanied by a cost-benefit analysis:","Provided,","further, That the Fiscal Incentives Review Board shall prescribe the data requirements for the application of incentives to allow for the calculation of costs and benefits upon application:","Provided,","further, That the grant of tax incentives with investment capital of One billion pesos (P1,000,000,000.00) and below shall be delegated by the Fiscal Incentives Review Board to the concerned Investment Promotion Agency to the extent of the registered project or activity:","Provided,","furthermore, That the Fiscal Incentives Review Board may increase the threshold amount of One billion pesos (P1,000,000,000.00):","Provided,","finally, That the application for tax incentives shall be deemed approved if not acted upon within twenty (20) days from the date of submission of the application and complete relevant supporting documents to the Fiscal Incentives Review Board or the Investment Promotion Agency, as the case may be; \"(C) To approve applications for tax subsidies to government-owned or controlled- corporations, government instrumentalities, government commissaries, and state universities and colleges. \"For this purpose, the other government agencies shall ensure complete submission of applications, documents, records, books, or other relevant data or material; \"(D) To formulate place-specific strategic investment plans during periods of recovery from calamities and post-conflict situations and where the Fiscal Incentives Review Board determines that there is a need to attract many classes, firms, that would accelerate the growth of a region's flagship industries, in accordance with the Medium-Term Development Plan. The Fiscal Incentives Review Board may formulate and approve place-specific strategic investment plans and recommend incentives to the President, following the same procedure in Section 297; \"(E) To cancel, suspend, or withdraw the enjoyment of fiscal incentives of concerned registered business enterprises on its own initiative or upon the recommendation of the Investment Promotion Agency for material violations of any of the conditions imposed in the grant of fiscal incentives, including, but not limited to, the non-compliance of the agreed performance commitments and endorse registered business enterprises whose incentives are cancelled, suspended, or withdrawn to the concerned revenue agencies for the assessment and collection of taxes and duties due commencing from the first year of availment; \"(F) To cancel, suspend, or withdraw the enjoyment of tax subsidy of concerned government-owned or controlled corporations, government commissaries, and state universities and colleges, and when necessary, endorse the same to the concerned revenue agencies for assessment and collection of taxes and duties due, including fines or penalties, if warranted, for violations of any of the conditions imposed in the grant of tax subsidy, or provisions of this Act, or applicable rules; \"(G) To require Investment Promotion Agencies and other government agencies administering tax incentives to submit, regularly or when requested, summaries of approved investment and incentives granted, and firm-or entity-level tax incentives and benefits data as input to the Fiscal Incentives Review Board's review and audit function, and evaluation of performance of recipients of tax incentives. For this purpose, the Fiscal Incentives Review Board shall maintain a masterlist of registered products and services for export or domestic consumption that are entitled to incentives:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A24","no":24,"noLabel":{"en":"SEC. 298."},"text":{"en":"SEC. 298. Composition of the Fiscal Incentives Review Board. - The Fiscal Incentives Review Board shall be reconstituted as follows: \"Chairperson - Secretary of Finance \"Co-Chairperson - Secretary of Trade and Industry \"Members - Executive Secretary of the Office of the President - Secretary of Budget and Management - Director General of the National Economic and Development Authority \"The Board shall have a technical committee, which shall serve as its main support unit and perform functions as may be assigned, and shall be composed of the following: \"Chairperson - Undersecretary of Finance \"Members - Undersecretary or Assistant Secretary of the Office of the Executive Secretary - Undersecretary of Trade and Industry and Board of Investments Managing Head or Assistance Secretary of Trade and Industry - Undersecretary or Assistant Secretary of Budget and Management - Deputy or Assistant Director General of the National Economic Development Authority - Commissioner or Deputy Commissioner of Internal Revenue - Commissioner of the Philippine Competition Commission - Director General or Chairperson or Administrator of the Investment Promotion Agencies: Provided,"},"paragraphs":["Composition of the Fiscal Incentives Review Board.","- The Fiscal Incentives Review Board shall be reconstituted as follows: \"Chairperson - Secretary of Finance \"Co-Chairperson - Secretary of Trade and Industry \"Members - Executive Secretary of the Office of the President - Secretary of Budget and Management - Director General of the National Economic and Development Authority \"The Board shall have a technical committee, which shall serve as its main support unit and perform functions as may be assigned, and shall be composed of the following: \"Chairperson - Undersecretary of Finance \"Members - Undersecretary or Assistant Secretary of the Office of the Executive Secretary - Undersecretary of Trade and Industry and Board of Investments Managing Head or Assistance Secretary of Trade and Industry - Undersecretary or Assistant Secretary of Budget and Management - Deputy or Assistant Director General of the National Economic Development Authority - Commissioner or Deputy Commissioner of Internal Revenue - Commissioner of the Philippine Competition Commission - Director General or Chairperson or Administrator of the Investment Promotion Agencies:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A25","no":25,"noLabel":{"en":"SEC. 299."},"text":{"en":"SEC. 299. Structure and Staffing Pattern. - To support the expanded functions of the Fiscal Incentives Review Board, the National Tax research Center, as secretariat thereof, shall create three (3) additional groups, namely, Fiscal Incentives Management Group, Monitoring and Evaluation Group, and Legal Group. Each group shall be composed of at least two (2) divisions, which will be headed by a deputy executive director. The existing administrative and financial branch of the National Tax Research Center shall be converted into a group to be headed by a deputy executive director and will be composed of four (4) divisions, namely, finance, human resource management and development, general services, and management and information systems. \" Provided, That the Fiscal Incentives Review Board secretariat is authorized to determine its organizational structure and staffing pattern, and create such services, divisions, and units, as it may be require or deem necessary in the future, subject to the approval by the Department of Budget and Management: Provided, finally, That nothing herein modifies the existing organizational structure and staffing pattern of the Investment Promotion Agencies or affects their power to maintain or determine their respective organizational structure and staffing pattern.\" \" PROJECTS OR ACTIVITIES FOR TAX INCENTIVES"},"paragraphs":["Structure and Staffing Pattern.","- To support the expanded functions of the Fiscal Incentives Review Board, the National Tax research Center, as secretariat thereof, shall create three (3) additional groups, namely, Fiscal Incentives Management Group, Monitoring and Evaluation Group, and Legal Group. Each group shall be composed of at least two (2) divisions, which will be headed by a deputy executive director. The existing administrative and financial branch of the National Tax Research Center shall be converted into a group to be headed by a deputy executive director and will be composed of four (4) divisions, namely, finance, human resource management and development, general services, and management and information systems. \"","Provided,","That the Fiscal Incentives Review Board secretariat is authorized to determine its organizational structure and staffing pattern, and create such services, divisions, and units, as it may be require or deem necessary in the future, subject to the approval by the Department of Budget and Management:","Provided,","finally, That nothing herein modifies the existing organizational structure and staffing pattern of the Investment Promotion Agencies or affects their power to maintain or determine their respective organizational structure and staffing pattern.\"","\"","PROJECTS OR ACTIVITIES FOR TAX INCENTIVES"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A26","no":26,"noLabel":{"en":"SEC. 300."},"chapter":{"en":"CHAPTER IVQUALIFIED PROJECTS OR ACTIVITIES FOR TAX INCENTIVES"},"text":{"en":"SEC. 300. Strategic Investment Priority Plan."},"paragraphs":["Strategic Investment Priority Plan."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A27","no":27,"noLabel":{"en":"SEC. 301."},"text":{"en":"SEC. 301. Power of the President to Grant Incentives. - Notwithstanding the provisions of Section 295 and 296, the President may, in the interest of national economic development and upon the recommendation of the Fiscal Incentives Review Board, modify the mix, period or manner of availment of incentives provided under this Code or craft the appropriate financial support package for a highly desirable project or a specific industrial activity based on defined development strategies for creating high-value jobs, building new industries to diversify economic activities, and attracting significant foreign and domestic capital or investment, and the fiscal requirements of the activity or projects, subject to maximum incentive levels recommended by the Fiscal Incentives Review Board: Provided, That the grant of income tax holiday shall not exceed eight (8) years and thereafter, a special corporate income tax rate of five percent (5%) may be granted: Provided, further, That the total period of incentive availment shall not exceed forty (40) years. \"The Fiscal Incentives Review Board shall determine whether the benefits that the Government may derive from such investment are clear and convincing and far outweigh the costs of incentives that will be granted in determining whether a project or activity is highly desirable. \"The exercise by the President of his powers under this Section shall be based on a positive recommendation from the Fiscal Incentives Review Board upon its determination that the following conditions are satisfied: \"(1) The project has a comprehensive sustainable development plan with clear inclusive business approaches, and high level of sophistication and innovation; and \"(2) Minimum investment capital of Fifty billion pesos (P50,000,000,000.00) or its equivalent in US dollars, or a minimum direct local employment generation of at least ten thousand (10,000) within three (3) years from the issuance of the certificate of entitlement. \" Provided, That the threshold shall be subject to a periodic review by the Fiscal Incentives Review Board every three (3) years, taking into consideration international standards or other economic indicators: Provided, further, That if the project fails to substantially meet the projected impact on the economy and agreed performance targets, the Fiscal Incentives Review Board shall recommend to the President the cancellation of the tax incentive or financial support package or the modified period or manner of availment of incentives, after due hearing and an adequate opportunity to substantially comply with the agreed performance targets and outputs. \"For this purpose, financial support includes utilization of government resources such as land use, water appropriation, power provision, and budgetary support provision under the annual General Appropriations Act. \"This power of the President, in as far as it commands additional public sector expenditures in support of investors, is suspended during fiscal years when, an unimaginable fiscal deficit is declared by the President on the advice of the Development Budget Coordination Committee with a consequence that even core budgetary obligations, such as, but not limited to, mandatory revenue allotments for local government units and budget for the National Economic and Development Authority's core public investments program, cannot be fully financed. \"The President may, upon request of an Investment Promotion Agency, exempt the latter from the coverage of the provisions of title XIII of this Code with respect to the review and approval of applications for incentives, or modify the policy on thresholds for Fiscal Incentives Review Board approvals, pursuant to Section 297, should any of the following conditions exist: \"(A) When incentives system provided herein cause a significant, demonstrable, and attributable damage to the performance of an Investment Promotion Agency; \"(B) When it is reasonably evident that the incentives granted are no longer adequate, necessary, or appropriate; \"(C) When there is need to modify incentive privileges in the light of technological economic, and social changes; or \"(D) When there is need to redesign the tax incentive schemes to obviate unemployment and avoid economic and social dislocation: \" Provided, That the abovementioned request is approved by a majority vote of its governing board: \" Provided, further, That such request is supported by a cost-benefit analysis reviewed by the Fiscal Incentives Review Board, and other quantitative and qualitative evidence demonstrating the Investment Promotion Agency's performance: \" Provided,"},"paragraphs":["Power of the President to Grant Incentives.","- Notwithstanding the provisions of Section 295 and 296, the President may, in the interest of national economic development and upon the recommendation of the Fiscal Incentives Review Board, modify the mix, period or manner of availment of incentives provided under this Code or craft the appropriate financial support package for a highly desirable project or a specific industrial activity based on defined development strategies for creating high-value jobs, building new industries to diversify economic activities, and attracting significant foreign and domestic capital or investment, and the fiscal requirements of the activity or projects, subject to maximum incentive levels recommended by the Fiscal Incentives Review Board:","Provided,","That the grant of income tax holiday shall not exceed eight (8) years and thereafter, a special corporate income tax rate of five percent (5%) may be granted:","Provided,","further, That the total period of incentive availment shall not exceed forty (40) years. \"The Fiscal Incentives Review Board shall determine whether the benefits that the Government may derive from such investment are clear and convincing and far outweigh the costs of incentives that will be granted in determining whether a project or activity is highly desirable. \"The exercise by the President of his powers under this Section shall be based on a positive recommendation from the Fiscal Incentives Review Board upon its determination that the following conditions are satisfied: \"(1) The project has a comprehensive sustainable development plan with clear inclusive business approaches, and high level of sophistication and innovation; and \"(2) Minimum investment capital of Fifty billion pesos (P50,000,000,000.00) or its equivalent in US dollars, or a minimum direct local employment generation of at least ten thousand (10,000) within three (3) years from the issuance of the certificate of entitlement. \"","Provided,","That the threshold shall be subject to a periodic review by the Fiscal Incentives Review Board every three (3) years, taking into consideration international standards or other economic indicators:","Provided,","further, That if the project fails to substantially meet the projected impact on the economy and agreed performance targets, the Fiscal Incentives Review Board shall recommend to the President the cancellation of the tax incentive or financial support package or the modified period or manner of availment of incentives, after due hearing and an adequate opportunity to substantially comply with the agreed performance targets and outputs. \"For this purpose, financial support includes utilization of government resources such as land use, water appropriation, power provision, and budgetary support provision under the annual General Appropriations Act. \"This power of the President, in as far as it commands additional public sector expenditures in support of investors, is suspended during fiscal years when, an unimaginable fiscal deficit is declared by the President on the advice of the Development Budget Coordination Committee with a consequence that even core budgetary obligations, such as, but not limited to, mandatory revenue allotments for local government units and budget for the National Economic and Development Authority's core public investments program, cannot be fully financed. \"The President may, upon request of an Investment Promotion Agency, exempt the latter from the coverage of the provisions of title XIII of this Code with respect to the review and approval of applications for incentives, or modify the policy on thresholds for Fiscal Incentives Review Board approvals, pursuant to Section 297, should any of the following conditions exist: \"(A) When incentives system provided herein cause a significant, demonstrable, and attributable damage to the performance of an Investment Promotion Agency; \"(B) When it is reasonably evident that the incentives granted are no longer adequate, necessary, or appropriate; \"(C) When there is need to modify incentive privileges in the light of technological economic, and social changes; or \"(D) When there is need to redesign the tax incentive schemes to obviate unemployment and avoid economic and social dislocation: \"","Provided,","That the abovementioned request is approved by a majority vote of its governing board: \"","Provided,","further, That such request is supported by a cost-benefit analysis reviewed by the Fiscal Incentives Review Board, and other quantitative and qualitative evidence demonstrating the Investment Promotion Agency's performance: \"","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A28","no":28,"noLabel":{"en":"SEC. 302."},"text":{"en":"SEC. 302. Amendments to the Strategic Investment Priority Plan."},"paragraphs":["Amendments to the Strategic Investment Priority Plan."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A29","no":29,"noLabel":{"en":"SEC. 303."},"text":{"en":"SEC. 303. Publication. - Upon approval of the Strategic Investment Priority Plan, in whole or in part, or upon approval of an amendment thereof, the Plan or the amendment, specifying and declaring the areas of investments shall be published in at least one (1) newspaper of general circulation or in the Official Gazette: Provided,"},"paragraphs":["Publication.","- Upon approval of the Strategic Investment Priority Plan, in whole or in part, or upon approval of an amendment thereof, the Plan or the amendment, specifying and declaring the areas of investments shall be published in at least one (1) newspaper of general circulation or in the Official Gazette:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A30","no":30,"noLabel":{"en":"SEC. 304."},"text":{"en":"SEC. 304. Qualifications of a Registered Business Enterprise for Tax Incentives. - In the review and grant of tax incentives, the registered business enterprise must: \"(A) Be engaged in a project or activity included in the Strategic Investment Priority Plan; \"(B) Meet the target performance metrics after the agreed time period; \"(C) Install an adequate accounting system that shall identify the investments, revenues, costs and profits or losses of each registered project or activity undertaken by the enterprise separately from the aggregate investments, revenues, costs and profits or losses of the whole enterprise; or establish a separate corporation for each registered project or activity if the Investment Promotion Agency should so require; \"(D) Comply with the e-receipting and e-sales requirements in accordance with Sections 237 and 237(a) of this Code; and \"(E) Submit annual reports of beneficial ownership of the organization and related parties.\" \" INCENTIVE MANAGEMENT AND TRANSPARENCY"},"paragraphs":["Qualifications of a Registered Business Enterprise for Tax Incentives.","- In the review and grant of tax incentives, the registered business enterprise must: \"(A) Be engaged in a project or activity included in the Strategic Investment Priority Plan; \"(B) Meet the target performance metrics after the agreed time period; \"(C) Install an adequate accounting system that shall identify the investments, revenues, costs and profits or losses of each registered project or activity undertaken by the enterprise separately from the aggregate investments, revenues, costs and profits or losses of the whole enterprise; or establish a separate corporation for each registered project or activity if the Investment Promotion Agency should so require; \"(D) Comply with the e-receipting and e-sales requirements in accordance with Sections 237 and 237(a) of this Code; and \"(E) Submit annual reports of beneficial ownership of the organization and related parties.\"","\"","INCENTIVE MANAGEMENT AND TRANSPARENCY"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A31","no":31,"noLabel":{"en":"SEC. 305."},"chapter":{"en":"CHAPTER VTAX INCENTIVE MANAGEMENT AND TRANSPARENCY"},"text":{"en":"SEC. 305. Filing of Tax Returns and Submission of Tax Incentives Reports. - All registered business enterprises and other registered entities whether taxable or exempt, are required to file their tax returns and pay their tax liabilities, on or before the deadlines as provided under the National Internal Revenue Code of 1997, as amended, using the electronic system for filing and payment of taxes with the Bureau of Internal Revenue: Provided, That for purposes of complying with their tax obligations, cooperatives and other registered entities, which do not have access to the electronic facilities, shall file with their respective revenue district offices. \"For registered business enterprises and other registered business enterprises and other registered enterprises availing of tax incentives administered by the Investment Promotion Agencies and other government agencies administering tax incentives, they shall file with their respective Investment Promotion Agencies or other government agencies administering tax incentives a complete annual tax incentives report of their income-based tax incentives, VAT exemptions and zero-rating, customs duty exemptions, deductions, credits or exclusions from the income base, and exemptions from local taxes, as provided under Section 294 of this Act and in the special laws of the concerned Investment Promotion Agency or other government agency administering tax incentives, and respective laws, and a complete annual benefits report which shall include data such as, but not limited to, the approved and actual amount of investments, approved and actual employment level and job creation including information on quality of jobs and hiring of foreign and local workers, approved and actual exports and imports, domestic purchases, profits and dividend payout, all taxes paid, withheld and foregone within thirty (30) calendar days from the statutory deadline for filing of tax returns and payment of taxes: Provided, That a copy of the report shall be simultaneously submitted to the Fiscal Incentives Review Board in electronic form. \"The Investment Promotion Agencies and other government agencies administering tax incentives shall, within sixty (60) calendar days from the end of the statutory deadline for filing of the relevant tax returns, submit to the Bureau of Internal Revenue, their respective annual tax incentives reports based on the list of the registered business enterprises and other registered enterprise, which have filed said tax incentives report: Provided,"},"paragraphs":["Filing of Tax Returns and Submission of Tax Incentives Reports.","- All registered business enterprises and other registered entities whether taxable or exempt, are required to file their tax returns and pay their tax liabilities, on or before the deadlines as provided under the National Internal Revenue Code of 1997, as amended, using the electronic system for filing and payment of taxes with the Bureau of Internal Revenue:","Provided,","That for purposes of complying with their tax obligations, cooperatives and other registered entities, which do not have access to the electronic facilities, shall file with their respective revenue district offices. \"For registered business enterprises and other registered business enterprises and other registered enterprises availing of tax incentives administered by the Investment Promotion Agencies and other government agencies administering tax incentives, they shall file with their respective Investment Promotion Agencies or other government agencies administering tax incentives a complete annual tax incentives report of their income-based tax incentives, VAT exemptions and zero-rating, customs duty exemptions, deductions, credits or exclusions from the income base, and exemptions from local taxes, as provided under Section 294 of this Act and in the special laws of the concerned Investment Promotion Agency or other government agency administering tax incentives, and respective laws, and a complete annual benefits report which shall include data such as, but not limited to, the approved and actual amount of investments, approved and actual employment level and job creation including information on quality of jobs and hiring of foreign and local workers, approved and actual exports and imports, domestic purchases, profits and dividend payout, all taxes paid, withheld and foregone within thirty (30) calendar days from the statutory deadline for filing of tax returns and payment of taxes:","Provided,","That a copy of the report shall be simultaneously submitted to the Fiscal Incentives Review Board in electronic form. \"The Investment Promotion Agencies and other government agencies administering tax incentives shall, within sixty (60) calendar days from the end of the statutory deadline for filing of the relevant tax returns, submit to the Bureau of Internal Revenue, their respective annual tax incentives reports based on the list of the registered business enterprises and other registered enterprise, which have filed said tax incentives report:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A32","no":32,"noLabel":{"en":"SEC. 306."},"text":{"en":"SEC. 306. Monitoring, Evaluation and Reporting of Tax Incentives. - Notwithstanding any law to the contrary, the Bureau of Internal Revenue and the Bureau of Customs shall submit to the Department of Finance: (a) all tax and duty incentives of registered business enterprises and other registered enterprises, as reflected in their filed tax returns and import entries; and (b) actual tax and duty incentives as evaluated and determined by the Bureau of Internal Revenue and the Bureau of Customs. \"The Department of Finance shall maintain a single database for monitoring and analysis of tax incentives granted.ℒ&alpha;w&rho;hi&#2551 \"The Fiscal Incentives Review Board is mandated to systematically collect and store all tax incentives and benefit data from the Department of Finance, Investment Promotion Agencies, other government agencies administering tax incentives, registered business enterprises, and other registered enterprises, as well as to evaluate and assess the process, outcomes and impact of incentives granted to firms to determine whether agreed performance targets and intended results and outcomes are met. The method of evaluation may include the conduct of cost-benefit analysis or other process and impact evaluation methods: Provided, That for purposes of this Act, the term cost-benefit analysis refers to the systematic evaluation of the total costs of granting tax incentives vis-a-vis the total benefits derived from the grant of tax incentives based on the annual tax incentive report, annual benefits report, and other related sources, to calculate the net benefit or cost associated with tax incentives. \"For purposes of monitoring and transparency, the Department of Finance shall submit to the Department of Budget and Management (DBM) a per firm and per registered project and activity data arranged on a sectoral and per industry basis: (1) the amount of tax incentives availed of by registered business enterprises and other registered enterprises; (2) the estimate claims of tax incentives immediately preceding the current year; (3) the programmed tax incentives for the current year; and (4) the projected tax incentives for the following year. \"The aforesaid data shall be reflected by the DBM in the annual Budget of Expenditures and Sources of Financing (BESF), which shall be known as the Tax Incentives Information (TII) Section: Provided, That the tax incentives information shall include a per firm data related to incentives availed of by registered business enterprises and other registered business enterprises based on the submission of the Department of Finance and the concerned Investment Promotion Agencies and other govenrment agencies administering tax incentives, categorized by sector, by Investment Promotion Agency or other government agency administering tax incentives, and by type of tax incentive: Provided,"},"paragraphs":["Monitoring, Evaluation and Reporting of Tax Incentives.","- Notwithstanding any law to the contrary, the Bureau of Internal Revenue and the Bureau of Customs shall submit to the Department of Finance: (a) all tax and duty incentives of registered business enterprises and other registered enterprises, as reflected in their filed tax returns and import entries; and (b) actual tax and duty incentives as evaluated and determined by the Bureau of Internal Revenue and the Bureau of Customs. \"The Department of Finance shall maintain a single database for monitoring and analysis of tax incentives granted.ℒ&alpha;w&rho;hi&#2551 \"The Fiscal Incentives Review Board is mandated to systematically collect and store all tax incentives and benefit data from the Department of Finance, Investment Promotion Agencies, other government agencies administering tax incentives, registered business enterprises, and other registered enterprises, as well as to evaluate and assess the process, outcomes and impact of incentives granted to firms to determine whether agreed performance targets and intended results and outcomes are met. The method of evaluation may include the conduct of cost-benefit analysis or other process and impact evaluation methods:","Provided,","That for purposes of this Act, the term cost-benefit analysis refers to the systematic evaluation of the total costs of granting tax incentives vis-a-vis the total benefits derived from the grant of tax incentives based on the annual tax incentive report, annual benefits report, and other related sources, to calculate the net benefit or cost associated with tax incentives. \"For purposes of monitoring and transparency, the Department of Finance shall submit to the Department of Budget and Management (DBM) a per firm and per registered project and activity data arranged on a sectoral and per industry basis: (1) the amount of tax incentives availed of by registered business enterprises and other registered enterprises; (2) the estimate claims of tax incentives immediately preceding the current year; (3) the programmed tax incentives for the current year; and (4) the projected tax incentives for the following year. \"The aforesaid data shall be reflected by the DBM in the annual Budget of Expenditures and Sources of Financing (BESF), which shall be known as the Tax Incentives Information (TII) Section:","Provided,","That the tax incentives information shall include a per firm data related to incentives availed of by registered business enterprises and other registered business enterprises based on the submission of the Department of Finance and the concerned Investment Promotion Agencies and other govenrment agencies administering tax incentives, categorized by sector, by Investment Promotion Agency or other government agency administering tax incentives, and by type of tax incentive:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A33","no":33,"noLabel":{"en":"SEC. 307."},"text":{"en":"SEC. 307. Conduct of Impact Evaluation on Tax Incentives. - The Fiscal Incentives Review Board is mandated to conduct impact evaluation such as cost-benefit analysis on the investment and non-investment incentives on the Philippines economy and on the relevant sector. \"For this purpose, the Department of Finance, all heads of the Investment Promotion Agencies and other government agencies administering tax incentives shall submit to the Fiscal Incentives Review Board per firm and per registered project or activity level in a machine readable format: \"(1) Data on tax incentives based on the submission of registered business enterprises and other registered enterprises; and \"(2) Other investment and non-investment related data. \"A third party government institutions may conduct on its own or upon request of the Fiscal Incentives Review Board a peer review of the impact evaluation on the investment and non-investment incentives to determine the impact of the tax incentives on the Philippine economy and on the relevant sector: Provided,"},"paragraphs":["Conduct of Impact Evaluation on Tax Incentives.","- The Fiscal Incentives Review Board is mandated to conduct impact evaluation such as cost-benefit analysis on the investment and non-investment incentives on the Philippines economy and on the relevant sector. \"For this purpose, the Department of Finance, all heads of the Investment Promotion Agencies and other government agencies administering tax incentives shall submit to the Fiscal Incentives Review Board per firm and per registered project or activity level in a machine readable format: \"(1) Data on tax incentives based on the submission of registered business enterprises and other registered enterprises; and \"(2) Other investment and non-investment related data. \"A third party government institutions may conduct on its own or upon request of the Fiscal Incentives Review Board a peer review of the impact evaluation on the investment and non-investment incentives to determine the impact of the tax incentives on the Philippine economy and on the relevant sector:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A34","no":34,"noLabel":{"en":"SEC. 308."},"text":{"en":"SEC. 308. Penalties for Noncompliance with Filing and Reportorial Requirements. - Any registered business enterprise or other registered enterprise, which fails to comply with the appropriate Investment Promotion Agencies or other government agencies administering tax incentives and/or, which fails to show proof of filing of tax returns using the electronic system for filing and payment of taxes of the Bureau of Internal Revenue under Section 305 hereof, shall be imposed the following penalties by the appropriate Investment Promotion Agency or other government agency administering tax incentives: \"(A) First (1st) Violation - Payment of a fine amounting to One hundred thousand pesos (P100,000.00); \"(B) Second (2nd) Violation - Payment of a fine amounting to Five hundred thousand pesos (P500,000.00); and \"(C) Third (3rd) Violation - Cancellation by the Fiscal Incentives Review Board of the registration of the registered business enterprise or registered entity with the Investment Promotion Agency or other government agency administering tax incentives. \" Provided, That if the failure to show such proof is not due to the fault of the registered business enterprises or other registered enterprises, the same shall not be a ground for the suspension of the Income Tax Holiday (ITH) and/or other tax incentives availment: Provided, further, That collections from the penalties shall accrue to the general fund. \"After due process, the Fiscal Incentives Review Board or the concerned Investment Promotion Agency, as the case may be, may cancel the registration, suspend the enjoyment of incentive benefits of any registered enterprise, and/or require refund of incentives and monetary penalties, for any material misrepesentation of information for the purpose of availing more incentives than what it is entitled to under this Code. \"Provided. That the Fiscal Incentives Review Board, with the recommendation of the Commissioner, may revoke or suspend incentives granted by an Investment Promotion Agency and/or order a business closure of a registered business enterprise that violates title VI (Excise Taxes on Certain Goods) and title X (Statutory Offenses and Penalties) of this Code and other related revenue regulations, orders, or issuances of the government: Provided, further, That such authority shall cover the acts of the registered business enterprise committed even in the first year of availment of incentives. Notwithstanding the provisions of this Section, the Department of Finance, the Bureau of Internal Revenue, and the Bureau of Customs shall retain their respective mandates, powers and functions as provided for under this Act and related laws. \"Any government official or employee who fails without justifiable reason to provide or furnish the required tax incentives report or other data or information as required under Sections 306 nd 307 of this Act shall be penalized, after due process, by a fine equivalent to the official's or employee's basic salary for a period of one (1) month to six (6) months or by suspension from government service for not more than one (1) year, or both, in addition to any criminal and administrative penalties imposable under existing laws.\" \" AND MISCELLANEOUS PROVISIONS"},"paragraphs":["Penalties for Noncompliance with Filing and Reportorial Requirements. - Any registered business enterprise or other registered enterprise, which fails to comply with the appropriate Investment Promotion Agencies or other government agencies administering tax incentives and/or, which fails to show proof of filing of tax returns using the electronic system for filing and payment of taxes of the Bureau of Internal Revenue under Section 305 hereof, shall be imposed the following penalties by the appropriate Investment Promotion Agency or other government agency administering tax incentives: \"(A) First (1st) Violation - Payment of a fine amounting to One hundred thousand pesos (P100,000.00); \"(B) Second (2nd) Violation - Payment of a fine amounting to Five hundred thousand pesos (P500,000.00); and \"(C) Third (3rd) Violation - Cancellation by the Fiscal Incentives Review Board of the registration of the registered business enterprise or registered entity with the Investment Promotion Agency or other government agency administering tax incentives. \"","Provided,","That if the failure to show such proof is not due to the fault of the registered business enterprises or other registered enterprises, the same shall not be a ground for the suspension of the Income Tax Holiday (ITH) and/or other tax incentives availment:","Provided,","further, That collections from the penalties shall accrue to the general fund. \"After due process, the Fiscal Incentives Review Board or the concerned Investment Promotion Agency, as the case may be, may cancel the registration, suspend the enjoyment of incentive benefits of any registered enterprise, and/or require refund of incentives and monetary penalties, for any material misrepesentation of information for the purpose of availing more incentives than what it is entitled to under this Code. \"Provided. That the Fiscal Incentives Review Board, with the recommendation of the Commissioner, may revoke or suspend incentives granted by an Investment Promotion Agency and/or order a business closure of a registered business enterprise that violates title VI (Excise Taxes on Certain Goods) and title X (Statutory Offenses and Penalties) of this Code and other related revenue regulations, orders, or issuances of the government:","Provided,","further, That such authority shall cover the acts of the registered business enterprise committed even in the first year of availment of incentives. Notwithstanding the provisions of this Section, the Department of Finance, the Bureau of Internal Revenue, and the Bureau of Customs shall retain their respective mandates, powers and functions as provided for under this Act and related laws. \"Any government official or employee who fails without justifiable reason to provide or furnish the required tax incentives report or other data or information as required under Sections 306 nd 307 of this Act shall be penalized, after due process, by a fine equivalent to the official's or employee's basic salary for a period of one (1) month to six (6) months or by suspension from government service for not more than one (1) year, or both, in addition to any criminal and administrative penalties imposable under existing laws.\"","\"","AND MISCELLANEOUS PROVISIONS"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A35","no":35,"noLabel":{"en":"SEC. 309."},"chapter":{"en":"CHAPTER VITRANSITORY AND MISCELLANEOUS PROVISIONS"},"text":{"en":"SEC. 309. Prohibition on Registered Activities. - A qualified registered project or activity under an Investment Promotion Agency administering an economic zone or freeport shall be exclusively conducted or operated within the geographical boundaries of the zone or freeport being administered by the Investment Promotion Agency in which the project or activity is registered: Provided, That a registered business enterprise may conduct or operate more than one qualified registered project or activity within the same zone or freeport under the same Investment Promotion Agency: Provided,"},"paragraphs":["Prohibition on Registered Activities.","- A qualified registered project or activity under an Investment Promotion Agency administering an economic zone or freeport shall be exclusively conducted or operated within the geographical boundaries of the zone or freeport being administered by the Investment Promotion Agency in which the project or activity is registered:","Provided,","That a registered business enterprise may conduct or operate more than one qualified registered project or activity within the same zone or freeport under the same Investment Promotion Agency:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A36","no":36,"noLabel":{"en":"SEC. 310."},"text":{"en":"SEC. 310. Establishment on One-Stop Action Center. - All Investment Promotion Agencies shall establish a one-stop shop or one-stop action center that will facilitate and expedite, to the extent possible, the setting up and conduct of registered projects or activities, including assistance in coordinating with the local government units and other government agencies to comply with Republic Act No. 11302, otherwise known as the Ease of Doing Business and Efficient Government Service Delivery Act of 2018: Provided,"},"paragraphs":["Establishment on One-Stop Action Center.","- All Investment Promotion Agencies shall establish a one-stop shop or one-stop action center that will facilitate and expedite, to the extent possible, the setting up and conduct of registered projects or activities, including assistance in coordinating with the local government units and other government agencies to comply with Republic Act No. 11302, otherwise known as the Ease of Doing Business and Efficient Government Service Delivery Act of 2018:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A37","no":37,"noLabel":{"en":"SEC. 311."},"text":{"en":"SEC. 311. Investments Prior to the Effectivity of This Act. - Registered business enterprises with incentives granted prior to the effectivity of this Act shall be subject to the following rules: \"(A) Registered business enterprises whose projects or activities were granted only an income tax holiday prior to the effectivity of this Act shall be allowed to continue with availment of the income tax holiday for the remaining period of the income tax holiday as specified in the terms and conditions of their registration: Provided, That for those that have been granted the income tax holiday but have not yet availed of the incentive upon the effectivity of this Act, they may use the income tax holiday for the period specified in the terms and conditions of their registration; \"(B) Registered business enterprises, whose projects or activities were granted an income tax holiday prior to the effectivity of this Act and that are entitled to the five percent (5%) tax on gross income earned incentive after the income tax holiday, shall be allowed to avail of the five percent (5%) tax on gross income earned incentive based on Subsection (C); and \"(C) Registered business enterprises currently availing of the five percent (5%) tax on gross income earned granted prior to the effectivity of this Act shall be allowed to continue availing the said tax incentive at the rate of five percent (5%) for ten (10) years."},"paragraphs":["Investments Prior to the Effectivity of This Act.","- Registered business enterprises with incentives granted prior to the effectivity of this Act shall be subject to the following rules: \"(A) Registered business enterprises whose projects or activities were granted only an income tax holiday prior to the effectivity of this Act shall be allowed to continue with availment of the income tax holiday for the remaining period of the income tax holiday as specified in the terms and conditions of their registration:","Provided,","That for those that have been granted the income tax holiday but have not yet availed of the incentive upon the effectivity of this Act, they may use the income tax holiday for the period specified in the terms and conditions of their registration; \"(B) Registered business enterprises, whose projects or activities were granted an income tax holiday prior to the effectivity of this Act and that are entitled to the five percent (5%) tax on gross income earned incentive after the income tax holiday, shall be allowed to avail of the five percent (5%) tax on gross income earned incentive based on Subsection (C); and \"(C) Registered business enterprises currently availing of the five percent (5%) tax on gross income earned granted prior to the effectivity of this Act shall be allowed to continue availing the said tax incentive at the rate of five percent (5%) for ten (10) years."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A38","no":38,"noLabel":{"en":"Section 17."},"text":{"en":"Section 17. Repealing Clause. - (a) To transfer to the Fiscal Incentives review Board the power of the Investment Promotion Agency Board to review, approve, or disapprove fiscal incentives and to mandate the Investment Promotion Agency Board to recommend to the Fiscal Incentives Review Board after a thorough review of the application, the approval or disapproval of the same, the following provisions are hereby repealed: (1) Article 7(14) of Executive Order No. 226, series of 1987, entitled: The Omnibus Investment s Code of 1987; (2) Section 1 (G) of Executive Order No. 458, series of 1991, entitled: \"Devolving the Powers and Functions of the Board of Investments Over Investments Within the Autonomous Region in Muslim Mindanao to the Autonomous Regional Government and for Other Purposes\"; (3) Section 8 of Republic Act No. 9400, entitled: \"An Act Amending Republic Act No. 7227, as Amended, Otherwise Known as the Bases Conversion and Development Act of 1992, and for Other Purposes\"; (4) Section 85(a) of Subchapter IV-B of Republic Act No. 9593, entitled: \"An Act Declaring a National Policy of Tourism as an Engine of Investment, Employment, Growth and National Development, and Strengthening the Department of Tourism and its Attached Agencies to Effectively and Efficiently Implement That Policy, and Appropriating Funds Therefor\", as amended by Republic Act No. 11262; and (5) Sections 7 and 8 of Republic Act no. 9490, entitled: \"An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 9490, Otherwise Known as the 'Aurora Special economic Zone Act of 2007\"; (b) The provisions of the following laws, including the tax incentives, that are inconsistent with this Act are hereby repealed: (1) Articles 39(A), (B), (C), (D), (H), (I), (J), (L) and (M); 40, 41, 42, 61, 62, 63, 64, 65, and 67 of Executive Order No. 226, series of 1987, entitled: The Omnibus Investments Code of 1987, as amended by Republic Act No. 7918, and further amended by Republic Act No. 8756; (2) Executive Order No. 85, series of 2019, entitled: \"Reducing the Rates of Duty on Capital Equipment, Spare Parts and Accessories Imported by Board of Investments - Registered New and Expanding Enterprises\"; (3) Presidential Decree No. 66, entitled: \"Creating the Export Processing Zone Authority and Revising Republic Act No. 5490\"; (4) Section 4(e) of Republic Act No. 7903, entitled: \"An Act Creating a Special Economic Zone and Free Port in the City of Zamboanga Creating for This Purpose the Zamboanga City Special Economic Zone Authority, Appropriating Funds Therefor, and for Other Purposes\"; (5) Section 7 of Republic Act 9400, entitled: \"An Act Amending Republic Act No. 7227, as amended, Otherwise Known as the Bases Conversion and Development Act of 1992, and for Other Purposes\"; (6) Section 4(b) of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone and Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (7) Sections 23 and 42 of Republic Act No. 7916, entitled: \"An Act Providing for the Legal Framework and Mechanisms for the Creation, Operation, Administration, and Coordination of Special Economic Zone in the Philippines, Creating for this Purpose, the Philippine Economic Zone Authority (PEZA), and for Other Purposes\" as amended by Republic Act No. 8748; (8) Sections 4(f), 5(a), (b), (d), (e), (f), (g), (h), (j), (l), and (m), and 9 of Republic Act No. 9490, entitled: \"An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No, 10083; (9) Sections 5, 9, and 10 of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataan, into the Freeport Area of Bataan (FAB), Creating for This Purpose the Authority of the Freeport Area of Bataan (AFAB), Appropriating Funds Therefor and for Other Purposes\"; (10) Section 16 of Republic Act No. 7844, entitled: \"An Act to Develop Exports as a Key Towards the Achievement of the National Goals Towards the Year 2000\"; (11) Sections 86(a), (c), (d), (e), (f), and 88 of Republic Act No. 9593, entitled: \"An Act Declaring a National Policy for Tourism as an Engine of Investment, Employment, Growth and National Development, and Strengthening the Department of Tourism and its Attached Agencies to Effectively and Efficiently Implement That Policy, and Appropriating Funds Therefor\"; and (12) Section 1(a) and (e) of Presidential Decree No. 1955, entitled: \"Withdrawing, Subject to Certain Conditions, the Duty and tax Privileges Granted to Private Business Enterprises and/or Persons Engaged in Any Economic Activity, and for Other Purposes\". (c) To expand the powers and functions of the Fiscal Incentives Review Board and enhance its membership, the provisions of the following laws that are inconsistent with this Act are hereby repealed: (1) Sections 1(6) and 2 of Presidential Decree No. 776, entitled: \"Modifying All Laws, Acts, Decrees, Orders and Ordinances, Granting Subsidies, Exemptions from Taxes, Duties, Fees, Imposts and Other Charges Under Certain Exceptions and Creating a Fiscal Incentives Board\"; (2) Section 2 of Presidential Decree No. 1931, series of 1984, entitled: \"Directing the Rationalization of Duty and tax Exemption Privileges Granted to Government-Owned or Controlled Corporations and All Other Units of Government\"; (3) Section 1(c) and (d) of Executive Order No. 93, series of 1986, entitled: \"Withdrawing All Tax and Duty Incentives, Subject to Certain Exceptions, Expanding the Powers of the Fiscal Incentives Review Board and for Other Purposes\"; and (4) Memorandum Order No. 23, series of 1986, entitled: \"Expanding the Membership of the Fiscal Incentives Review Board (FIRB)\". (d) The provisions of the following laws on the Investment Priorities Plan that are inconsistent with the provisions of this Act are hereby repealed: (1) Articles 7(1), 22, 26, 27, 28, 29, 30, 31 and 32 of Executive Order No. 226, series of 1987, entitled: The Omnibus Investments Code of 1987, as amended; and (2) Sections 2 and 3 of Executive Order No. 458, series of 1991, entitled: \"Devolving the Powers and Functions of the Board of Investments Over Investments Within the Autonomous Region in Muslim Mindanao to the Autonomous Regional Government and for Other Purposes\". (e) Sections 4, 5, 6 and 7 of Republic Act No. 10708, entitled: \"An Act Enhancing Transparency in the Management and Accounting of Tax Incentives Administered by Investment Promotion Agencies\", are also repealed for being inconsistent with this Act.ℒ&alpha;w&rho;hi&#2551 (f) Article 7(11) of Executive Order No. 226, series of 1987, entitled: The Omnibus Investment Code of 1987."},"paragraphs":["Repealing Clause.","- (a) To transfer to the Fiscal Incentives review Board the power of the Investment Promotion Agency Board to review, approve, or disapprove fiscal incentives and to mandate the Investment Promotion Agency Board to recommend to the Fiscal Incentives Review Board after a thorough review of the application, the approval or disapproval of the same, the following provisions are hereby repealed: (1) Article 7(14) of Executive Order No. 226, series of 1987, entitled: The Omnibus Investment s Code of 1987; (2) Section 1 (G) of Executive Order No. 458, series of 1991, entitled: \"Devolving the Powers and Functions of the Board of Investments Over Investments Within the Autonomous Region in Muslim Mindanao to the Autonomous Regional Government and for Other Purposes\"; (3) Section 8 of Republic Act No. 9400, entitled: \"An Act Amending Republic Act No. 7227, as Amended, Otherwise Known as the Bases Conversion and Development Act of 1992, and for Other Purposes\"; (4) Section 85(a) of Subchapter IV-B of Republic Act No. 9593, entitled: \"An Act Declaring a National Policy of Tourism as an Engine of Investment, Employment, Growth and National Development, and Strengthening the Department of Tourism and its Attached Agencies to Effectively and Efficiently Implement That Policy, and Appropriating Funds Therefor\", as amended by Republic Act No. 11262; and (5) Sections 7 and 8 of Republic Act no. 9490, entitled: \"An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 9490, Otherwise Known as the 'Aurora Special economic Zone Act of 2007\"; (b) The provisions of the following laws, including the tax incentives, that are inconsistent with this Act are hereby repealed: (1) Articles 39(A), (B), (C), (D), (H), (I), (J), (L) and (M); 40, 41, 42, 61, 62, 63, 64, 65, and 67 of Executive Order No. 226, series of 1987, entitled: The Omnibus Investments Code of 1987, as amended by Republic Act No. 7918, and further amended by Republic Act No. 8756; (2) Executive Order No. 85, series of 2019, entitled: \"Reducing the Rates of Duty on Capital Equipment, Spare Parts and Accessories Imported by Board of Investments - Registered New and Expanding Enterprises\"; (3) Presidential Decree No. 66, entitled: \"Creating the Export Processing Zone Authority and Revising Republic Act No. 5490\"; (4) Section 4(e) of Republic Act No. 7903, entitled: \"An Act Creating a Special Economic Zone and Free Port in the City of Zamboanga Creating for This Purpose the Zamboanga City Special Economic Zone Authority, Appropriating Funds Therefor, and for Other Purposes\"; (5) Section 7 of Republic Act 9400, entitled: \"An Act Amending Republic Act No. 7227, as amended, Otherwise Known as the Bases Conversion and Development Act of 1992, and for Other Purposes\"; (6) Section 4(b) of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone and Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (7) Sections 23 and 42 of Republic Act No. 7916, entitled: \"An Act Providing for the Legal Framework and Mechanisms for the Creation, Operation, Administration, and Coordination of Special Economic Zone in the Philippines, Creating for this Purpose, the Philippine Economic Zone Authority (PEZA), and for Other Purposes\" as amended by Republic Act No. 8748; (8) Sections 4(f), 5(a), (b), (d), (e), (f), (g), (h), (j), (l), and (m), and 9 of Republic Act No. 9490, entitled: \"An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No, 10083; (9) Sections 5, 9, and 10 of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataan, into the Freeport Area of Bataan (FAB), Creating for This Purpose the Authority of the Freeport Area of Bataan (AFAB), Appropriating Funds Therefor and for Other Purposes\"; (10) Section 16 of Republic Act No. 7844, entitled: \"An Act to Develop Exports as a Key Towards the Achievement of the National Goals Towards the Year 2000\"; (11) Sections 86(a), (c), (d), (e), (f), and 88 of Republic Act No. 9593, entitled: \"An Act Declaring a National Policy for Tourism as an Engine of Investment, Employment, Growth and National Development, and Strengthening the Department of Tourism and its Attached Agencies to Effectively and Efficiently Implement That Policy, and Appropriating Funds Therefor\"; and (12) Section 1(a) and (e) of Presidential Decree No. 1955, entitled: \"Withdrawing, Subject to Certain Conditions, the Duty and tax Privileges Granted to Private Business Enterprises and/or Persons Engaged in Any Economic Activity, and for Other Purposes\". (c) To expand the powers and functions of the Fiscal Incentives Review Board and enhance its membership, the provisions of the following laws that are inconsistent with this Act are hereby repealed: (1) Sections 1(6) and 2 of Presidential Decree No. 776, entitled: \"Modifying All Laws, Acts, Decrees, Orders and Ordinances, Granting Subsidies, Exemptions from Taxes, Duties, Fees, Imposts and Other Charges Under Certain Exceptions and Creating a Fiscal Incentives Board\"; (2) Section 2 of Presidential Decree No. 1931, series of 1984, entitled: \"Directing the Rationalization of Duty and tax Exemption Privileges Granted to Government-Owned or Controlled Corporations and All Other Units of Government\"; (3) Section 1(c) and (d) of Executive Order No. 93, series of 1986, entitled: \"Withdrawing All Tax and Duty Incentives, Subject to Certain Exceptions, Expanding the Powers of the Fiscal Incentives Review Board and for Other Purposes\"; and (4) Memorandum Order No. 23, series of 1986, entitled: \"Expanding the Membership of the Fiscal Incentives Review Board (FIRB)\". (d) The provisions of the following laws on the Investment Priorities Plan that are inconsistent with the provisions of this Act are hereby repealed: (1) Articles 7(1), 22, 26, 27, 28, 29, 30, 31 and 32 of Executive Order No. 226, series of 1987, entitled: The Omnibus Investments Code of 1987, as amended; and (2) Sections 2 and 3 of Executive Order No. 458, series of 1991, entitled: \"Devolving the Powers and Functions of the Board of Investments Over Investments Within the Autonomous Region in Muslim Mindanao to the Autonomous Regional Government and for Other Purposes\". (e) Sections 4, 5, 6 and 7 of Republic Act No. 10708, entitled: \"An Act Enhancing Transparency in the Management and Accounting of Tax Incentives Administered by Investment Promotion Agencies\", are also repealed for being inconsistent with this Act.ℒ&alpha;w&rho;hi&#2551 (f) Article 7(11) of Executive Order No. 226, series of 1987, entitled: The Omnibus Investment Code of 1987."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A39","no":39,"noLabel":{"en":"Section 18."},"text":{"en":"Section 18. Amendatory Clause. - (a) To transfer to the Fiscal Incentives Review Board the power of the Investment Promotion Agency Board to review, approve, or disapprove fiscal incentives and to mandate the Invetment Promotion Agency Board to recommend to the Fiscal Incentives Review Board after a thorough review of the application, the approval or disapproval of the same, the following provisions are hereby amended: (1) Articles 7(3) and (8), 34, 35, and 36 of Executive Order No. 226, series of 1987, entitled: The Omnibus Investments Code of 1987; (2) Section 1(A), (B), (D), and (E) of Executive Order No. 458, series of 1991, entitled: \"Devolving the Powers and Functions of the Board of Investments Over Investments Within the Autonomous Region in Muslim Mindanao to the Autonomous Regional Government and for Other Purposes\"; (3) Section 7(a) and (c) of Republic Act No. 7903, entitled: \"An Act Creating a Special Economic Zone and Free Port in the City of Zamboanga Creating for This Purpose the Zamboanga City Special Economic Zone Authority, Appropriating Funds Therefor, and for Other Purposes\"; (4) Sections 4(f), 8 and 13(c), (d), (r), (w) and (x) of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataan, into the Freeport Area of Bataan (FAB), Creating for this Purpose the Authority of the Freeport Area (AFAB), Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 11453; (5) Sections 5(1), 12(b), and 13(b)(11) of Republic Act No. 7227, entitled: \"AN Act Accelerating the Conversion of Military Reservations into Other Productive Uses, Creating the Bases Conversion and Development Authority for this Purpose, Providing Funds Therefor and for Other Purposes\", as amended by Republic Act No. 9400; (6) Section 69(n) of Subchapter IV-B of Republic Act No. 9593, entitled: \"An Act Declaring a National Policy for Tourism as an Engine of Investment, Employment Growth and National Development, and Strengthening the Department of Tourism and its Attached Agencies to Effectively and Efficiently Implement That Policy, and Appropriating Funds therefor\", as amended by Republic Act No. 11262; (7) Section 12(a), (b) and 9u) of Republic Act No. 9490, entitled: \"An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 10083, entitled: \"AN Act Amending Republic Act No. 9490, Otherwise Known as the 'Aurora Special Economic Zone Act of 2007\"; (8) Section 6(c) and (1) of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone and Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (9) Sections 4(a) and (q), and 6 of Presidential Decree No. 538, entitled: \"Creating and Establishing the PHIVIDEC Industrial Authority and Making it a Subsidiary Agency of the Philippine Veterans Investment Development Corporation, Defining its Powers, Functions and Responsibilities, and for Other Purposes\"; and (10) Sections 12(a) and (b) and 13(a), (b) and (i), and 15 of Republic Act No. 7916, entitled: \"An Act Providing for the Legal Framework and mechanisms for the Creation, Operation, Administration, and Coordination of Special Economic Zone in the Philippines, Creating for this Purpose, the Philippine Economic Zone Authority (PEZA), and for Other Purposes\", as amended by Republic Act No. 8748. (b) The provisions of the following laws, including the tax incentives, that are inconsistent with this Act are hereby amended: (1) Articles 69, 77, and 78 of Executive Order No. 226, series of 1987, entitled: The Omnibus Investments Code of 1987, as amended; (2) Sections 24 and 35 of Republic Act No. 7916, entitled: \"An Act Providing for the Legal Framework and Mechanisms for the Creation, Operation, Administration, and Coordination of Special Economic Zones in the Philippines, Creating for this Purpose, the Philippine Economic Zone Authority (PEZA), and for Other Purposes\", as amended by Republic Act No. 8748; (3) Sections 12(c), 15, 15-A, 15-B, 15-C of Republic Act No. 7227, entitled::An Act Accelerating the Conversion of Military Reservations into Other Productive Uses, Creating the Bases Conversion and Development Authority for this Purpose, Providing Funds Therefor and for Other Purposes\" as amended by Republic Act No. 9400, and further amended by Executive Order No. 619, series of 2007; (4) Section 6 of Republic Act No. 9400, entitled: \"An Act Amending Republic Act No. 9229, as amended, Otherwise Known as the Bases Conversion and Development Act of 1992, and for Other Purposes\"; (5) Section 5(c) of Republic Act No. 9490, entitled: \"AN Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 10083, entitled\" \"An Act Amending Republic Act No. 9490, Otherwise Known as the 'Aurora Special Economic Zone Act of 2007\"; (6) Section 4(f) of Republic Act No. 79-3, entitled: \"An Act Creating a Special Economic Zone and Free Port in the City of Zamboanga Creating for This Purpose the Zamboanga City Special Economic Zone Authority, Appropriating Funds Therefor, and for Other Purposes\"; (7) Section 4(c) of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone and Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (8) Section 6 of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataas, into the Freeport Area of Bataan (FAB), Creating for this Purpose the Authority of the Freeport Area of Bataan (AFAB), Appropriating Funds Therefor and for Other Purposes\"; (9) Sections 6(k), 14(e),, 39, 76, 85(c) and 86(b) of Republic Act No. 9593, entitled: \"An Act Declaring a National Policy for Tourism as an Engine of Investment, Employment, Growth and National Development, and Strengthening the Department of Tourism and its Attached Agencies to Effectively and Efficiently Implement That Policy, and Appropriating Funds Therefor\"; (10) Section 8 of Presidential Decree 588, entitled: \"Creating and Establishing the PHIVIDEC Industrial Authority and Making it a Subsidiary Agency of the Philippine Veterans Investment Development Corporation, Defining its Powers, Functions and Responsibilities, and for Other Purposes:, as amended by Presidential Decree No. 1491; and (11) Section 1(1.1) of Executive Order No. 97-A, series of 1993, entitled: \"further Clarifying the tax and Duty-Free Privilege Within the Subic Special Economic and Free Port Zone\". (c) To expand the powers and functions of the Fiscal Incentives Review Board, the provisions of the following laws that are inconsistent with this Act are hereby amended: (1) Section 13 of Republic Act No. 7903, entitled: \"An Act Creating a Special Economic Zone and Free Port in City of Zamboanga Creating for This Purpose the Zamboanga City Special Economic Zone Authority, Appropriating Funds Therefor, and for Other Purposes\"; (2) Section 10 of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone and Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (3) Section 17 of Republic Act No, 7227, entitled: \"An Act Accelerating the Conversion of Military Reservation into Other Productive uses, Creating the Bases Conversion and Development Authority for this Purpose, Providing Funds Therefor and for Other Purposes\"; (4) Section 20 of Republic Act No. 9490, entitled: An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds There for and for Other Purposes\"; and (5) Section 22 of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataas, into the Freeport Area of Bataan (FAB), Creating for this Purpose the Authority of the Freeport Area of Bataan (AFAB), Appropriating Funds Therefor and for Other Purposes\". (d) The provisions of the following laws on the Investment Priorities Plan, including all other laws, decrees, executive orders, rules and regulations, or parts thereof, which provide for the mandatory inclusion in the Investment Priorities Plan that are inconsistent with the provisions of this Act are hereby amended: (1) Sections 4(d) and 13(i) of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataan, into the Freeport Area of Bataan (FAB), Creating for this Purpose the Authority of the Freeport Area of Bataan (AFAB), Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 11458; (2) Section 12(f) of Republic Act No. 9490, as amended, entitled: \"An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority,v Appropriating Funds Therefor and for Other Purpose\"; (3) Section 6(f) of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone And Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (4) Section 21 of Republic Act No. 7916, as amended, entitled: \"An Act Providing for Legal Framework and Mechanisms for the Creation, operation, Administration, and Coordination of Special Economic Zones in the Philippines, Creating for this Purpose, the Philippine Economic Zone Authority (PEZA), and for Other Purposes\"; (5) Section 5 of Executive Order No. 80, series of 1993 entitled: \"Authorizing the Establishment of the Clark Development Corporation as the Implementing Arm of the Bases Conversion and Development Authority for the Clark Special Economic Zone, and Directing All Heads of Departments, Bureaus, Offices, Agencies and Instrumentalities of Government to Support the Program\"; (6) Section 4(b) and 13(b)(7) of Republic Act No. 7227, entitled: \"An Act Accelerating the Conversion of Military Reservations into Other Productive uses, Creating the Bases Conversion and Development Authority for this Purpose, Providing Funds Therefor and for Other Purposes\"; and (7) Section 1(F) of Executive Order No, 458, series of 1991, entitled: Devolving the Powers and Functions of the Board of Investments Over Investments Within the Autonomous Region in Muslim Mindanao to the Autonomous Regional Government and for Other Purposes\"."},"paragraphs":["Amendatory Clause.","- (a) To transfer to the Fiscal Incentives Review Board the power of the Investment Promotion Agency Board to review, approve, or disapprove fiscal incentives and to mandate the Invetment Promotion Agency Board to recommend to the Fiscal Incentives Review Board after a thorough review of the application, the approval or disapproval of the same, the following provisions are hereby amended: (1) Articles 7(3) and (8), 34, 35, and 36 of Executive Order No. 226, series of 1987, entitled: The Omnibus Investments Code of 1987; (2) Section 1(A), (B), (D), and (E) of Executive Order No. 458, series of 1991, entitled: \"Devolving the Powers and Functions of the Board of Investments Over Investments Within the Autonomous Region in Muslim Mindanao to the Autonomous Regional Government and for Other Purposes\"; (3) Section 7(a) and (c) of Republic Act No. 7903, entitled: \"An Act Creating a Special Economic Zone and Free Port in the City of Zamboanga Creating for This Purpose the Zamboanga City Special Economic Zone Authority, Appropriating Funds Therefor, and for Other Purposes\"; (4) Sections 4(f), 8 and 13(c), (d), (r), (w) and (x) of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataan, into the Freeport Area of Bataan (FAB), Creating for this Purpose the Authority of the Freeport Area (AFAB), Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 11453; (5) Sections 5(1), 12(b), and 13(b)(11) of Republic Act No. 7227, entitled: \"AN Act Accelerating the Conversion of Military Reservations into Other Productive Uses, Creating the Bases Conversion and Development Authority for this Purpose, Providing Funds Therefor and for Other Purposes\", as amended by Republic Act No. 9400; (6) Section 69(n) of Subchapter IV-B of Republic Act No. 9593, entitled: \"An Act Declaring a National Policy for Tourism as an Engine of Investment, Employment Growth and National Development, and Strengthening the Department of Tourism and its Attached Agencies to Effectively and Efficiently Implement That Policy, and Appropriating Funds therefor\", as amended by Republic Act No. 11262; (7) Section 12(a), (b) and 9u) of Republic Act No. 9490, entitled: \"An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 10083, entitled: \"AN Act Amending Republic Act No. 9490, Otherwise Known as the 'Aurora Special Economic Zone Act of 2007\"; (8) Section 6(c) and (1) of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone and Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (9) Sections 4(a) and (q), and 6 of Presidential Decree No. 538, entitled: \"Creating and Establishing the PHIVIDEC Industrial Authority and Making it a Subsidiary Agency of the Philippine Veterans Investment Development Corporation, Defining its Powers, Functions and Responsibilities, and for Other Purposes\"; and (10) Sections 12(a) and (b) and 13(a), (b) and (i), and 15 of Republic Act No. 7916, entitled: \"An Act Providing for the Legal Framework and mechanisms for the Creation, Operation, Administration, and Coordination of Special Economic Zone in the Philippines, Creating for this Purpose, the Philippine Economic Zone Authority (PEZA), and for Other Purposes\", as amended by Republic Act No. 8748. (b) The provisions of the following laws, including the tax incentives, that are inconsistent with this Act are hereby amended: (1) Articles 69, 77, and 78 of Executive Order No. 226, series of 1987, entitled: The Omnibus Investments Code of 1987, as amended; (2) Sections 24 and 35 of Republic Act No. 7916, entitled: \"An Act Providing for the Legal Framework and Mechanisms for the Creation, Operation, Administration, and Coordination of Special Economic Zones in the Philippines, Creating for this Purpose, the Philippine Economic Zone Authority (PEZA), and for Other Purposes\", as amended by Republic Act No. 8748; (3) Sections 12(c), 15, 15-A, 15-B, 15-C of Republic Act No. 7227, entitled::An Act Accelerating the Conversion of Military Reservations into Other Productive Uses, Creating the Bases Conversion and Development Authority for this Purpose, Providing Funds Therefor and for Other Purposes\" as amended by Republic Act No. 9400, and further amended by Executive Order No. 619, series of 2007; (4) Section 6 of Republic Act No. 9400, entitled: \"An Act Amending Republic Act No. 9229, as amended, Otherwise Known as the Bases Conversion and Development Act of 1992, and for Other Purposes\"; (5) Section 5(c) of Republic Act No. 9490, entitled: \"AN Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 10083, entitled\" \"An Act Amending Republic Act No. 9490, Otherwise Known as the 'Aurora Special Economic Zone Act of 2007\"; (6) Section 4(f) of Republic Act No. 79-3, entitled: \"An Act Creating a Special Economic Zone and Free Port in the City of Zamboanga Creating for This Purpose the Zamboanga City Special Economic Zone Authority, Appropriating Funds Therefor, and for Other Purposes\"; (7) Section 4(c) of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone and Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (8) Section 6 of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataas, into the Freeport Area of Bataan (FAB), Creating for this Purpose the Authority of the Freeport Area of Bataan (AFAB), Appropriating Funds Therefor and for Other Purposes\"; (9) Sections 6(k), 14(e),, 39, 76, 85(c) and 86(b) of Republic Act No. 9593, entitled: \"An Act Declaring a National Policy for Tourism as an Engine of Investment, Employment, Growth and National Development, and Strengthening the Department of Tourism and its Attached Agencies to Effectively and Efficiently Implement That Policy, and Appropriating Funds Therefor\"; (10) Section 8 of Presidential Decree 588, entitled: \"Creating and Establishing the PHIVIDEC Industrial Authority and Making it a Subsidiary Agency of the Philippine Veterans Investment Development Corporation, Defining its Powers, Functions and Responsibilities, and for Other Purposes:, as amended by Presidential Decree No. 1491; and (11) Section 1(1.1) of Executive Order No. 97-A, series of 1993, entitled: \"further Clarifying the tax and Duty-Free Privilege Within the Subic Special Economic and Free Port Zone\". (c) To expand the powers and functions of the Fiscal Incentives Review Board, the provisions of the following laws that are inconsistent with this Act are hereby amended: (1) Section 13 of Republic Act No. 7903, entitled: \"An Act Creating a Special Economic Zone and Free Port in City of Zamboanga Creating for This Purpose the Zamboanga City Special Economic Zone Authority, Appropriating Funds Therefor, and for Other Purposes\"; (2) Section 10 of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone and Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (3) Section 17 of Republic Act No, 7227, entitled: \"An Act Accelerating the Conversion of Military Reservation into Other Productive uses, Creating the Bases Conversion and Development Authority for this Purpose, Providing Funds Therefor and for Other Purposes\"; (4) Section 20 of Republic Act No. 9490, entitled: An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority, Appropriating Funds There for and for Other Purposes\"; and (5) Section 22 of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataas, into the Freeport Area of Bataan (FAB), Creating for this Purpose the Authority of the Freeport Area of Bataan (AFAB), Appropriating Funds Therefor and for Other Purposes\". (d) The provisions of the following laws on the Investment Priorities Plan, including all other laws, decrees, executive orders, rules and regulations, or parts thereof, which provide for the mandatory inclusion in the Investment Priorities Plan that are inconsistent with the provisions of this Act are hereby amended: (1) Sections 4(d) and 13(i) of Republic Act No. 9728, entitled: \"An Act Converting the Bataan Economic Zone Located in the Municipality of Mariveles, Province of Bataan, into the Freeport Area of Bataan (FAB), Creating for this Purpose the Authority of the Freeport Area of Bataan (AFAB), Appropriating Funds Therefor and for Other Purposes\", as amended by Republic Act No. 11458; (2) Section 12(f) of Republic Act No. 9490, as amended, entitled: \"An Act Establishing the Aurora Special Economic Zone in the Province of Aurora, Creating for the Purpose the Aurora Special Economic Zone Authority,v Appropriating Funds Therefor and for Other Purpose\"; (3) Section 6(f) of Republic Act No. 7922, entitled: \"An Act Establishing a Special Economic Zone And Free Port in the Municipality of Santa Ana and the Neighboring Islands in the Municipality of Aparri, Province of Cagayan, Providing Funds Therefor, and for Other Purposes\"; (4) Section 21 of Republic Act No. 7916, as amended, entitled: \"An Act Providing for Legal Framework and Mechanisms for the Creation, operation, Administration, and Coordination of Special Economic Zones in the Philippines, Creating for this Purpose, the Philippine Economic Zone Authority (PEZA), and for Other Purposes\"; (5) Section 5 of Executive Order No. 80, series of 1993 entitled: \"Authorizing the Establishment of the Clark Development Corporation as the Implementing Arm of the Bases Conversion and Development Authority for the Clark Special Economic Zone, and Directing All Heads of Departments, Bureaus, Offices, Agencies and Instrumentalities of Government to Support the Program\"; (6) Section 4(b) and 13(b)(7) of Republic Act No. 7227, entitled: \"An Act Accelerating the Conversion of Military Reservations into Other Productive uses, Creating the Bases Conversion and Development Authority for this Purpose, Providing Funds Therefor and for Other Purposes\"; and (7) Section 1(F) of Executive Order No, 458, series of 1991, entitled: Devolving the Powers and Functions of the Board of Investments Over Investments Within the Autonomous Region in Muslim Mindanao to the Autonomous Regional Government and for Other Purposes\"."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A40","no":40,"noLabel":{"en":"Section 19."},"text":{"en":"Section 19. Separability Clause. - If any provision or part of this Act is declared invalid or unconstitutional, such declaration shall be confined in its operation to the clause, sentence, paragraph, or part thereof directly involved in the case, whereas the parts or provisions not affected thereby shall remain in full force and effect."},"paragraphs":["Separability Clause.","- If any provision or part of this Act is declared invalid or unconstitutional, such declaration shall be confined in its operation to the clause, sentence, paragraph, or part thereof directly involved in the case, whereas the parts or provisions not affected thereby shall remain in full force and effect."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A41","no":41,"noLabel":{"en":"Section 20."},"text":{"en":"Section 20. Appropriation. - The National Tax Research Center, as the secretariat of the Fiscal Incentives Review Board, shall be provided with an initial appropriation of One hundred million pesos (P100,000,000.00) to be drawn from the available funds from the National Treasury not otherwise appropriated. Appropriations for the succeeding years shall be included in the annual General Appropriations Act."},"paragraphs":["Appropriation.","- The National Tax Research Center, as the secretariat of the Fiscal Incentives Review Board, shall be provided with an initial appropriation of One hundred million pesos (P100,000,000.00) to be drawn from the available funds from the National Treasury not otherwise appropriated. Appropriations for the succeeding years shall be included in the annual General Appropriations Act."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A42","no":42,"noLabel":{"en":"Section 21."},"text":{"en":"Section 21. Implementing Rules and Regulations. - Within ninety (90) days from the effectivity of this Act, the Secretary of Finance, upon the recommendation of the Commissioner of Internal Revenue, shall promulgate the necessary rules and regulations for its effective implementation: Provided, That for the provisions under title XIII, the Secretary of Finance and the Secretary of Trade and Industry shall jointly promulgate the necessary rules and regulations thereof within the same period, after due consultations with the Commissioner of Internal Revenue, the Board of Investments, and other Investment Promotion Agencies, for its effective implementation. Failure to promulgate the rules and regulations shall not prevent the implementation of this Act upon its effectivity."},"paragraphs":["Implementing Rules and Regulations.","- Within ninety (90) days from the effectivity of this Act, the Secretary of Finance, upon the recommendation of the Commissioner of Internal Revenue, shall promulgate the necessary rules and regulations for its effective implementation:","Provided,","That for the provisions under title XIII, the Secretary of Finance and the Secretary of Trade and Industry shall jointly promulgate the necessary rules and regulations thereof within the same period, after due consultations with the Commissioner of Internal Revenue, the Board of Investments, and other Investment Promotion Agencies, for its effective implementation. Failure to promulgate the rules and regulations shall not prevent the implementation of this Act upon its effectivity."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},{"id":"PH-CREATE-2021-A43","no":43,"noLabel":{"en":"Section 22."},"text":{"en":"Section 22. Effectivity. - This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in a newspaper of general circulation. Approved, (SGD.)"},"paragraphs":["Effectivity.","- This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in a newspaper of general circulation. Approved, (SGD.)"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"}],"pack":"ph-2","structure":[{"en":"TITLE XIII","zh":"TITLE XIII","articles":[1]},{"en":"CHAPTER IGENERAL PROVISIONS ON TAX INCENTIVES","zh":"CHAPTER IGENERAL PROVISIONS ON TAX INCENTIVES","articles":[17]},{"en":"CHAPTER IITAX AND DUTY INCENTIVES","zh":"CHAPTER IITAX AND DUTY INCENTIVES","articles":[20]},{"en":"CHAPTER IIITHE FISCAL INCENTIVES REVIEW BOARD","zh":"CHAPTER IIITHE FISCAL INCENTIVES REVIEW BOARD","articles":[23]},{"en":"CHAPTER IVQUALIFIED PROJECTS OR ACTIVITIES FOR TAX INCENTIVES","zh":"CHAPTER IVQUALIFIED PROJECTS OR ACTIVITIES FOR TAX INCENTIVES","articles":[26]},{"en":"CHAPTER VTAX INCENTIVE MANAGEMENT AND TRANSPARENCY","zh":"CHAPTER VTAX INCENTIVE MANAGEMENT AND TRANSPARENCY","articles":[31]},{"en":"CHAPTER VITRANSITORY AND MISCELLANEOUS PROVISIONS","zh":"CHAPTER VITRANSITORY AND MISCELLANEOUS PROVISIONS","articles":[35]}],"fulltextMeta":{"country":"PH","level":"law","status":"active","topics":["tax"],"title":{"zh":"企业复苏与税收优惠法案（CREATE）","en":"Corporate Recovery and Tax Incentives for Enterprises Act"},"docNumber":"Republic Act No. 11534","issuingBody":{"zh":"菲律宾国会","en":"Congress of the Philippines"},"promulgatedDate":"2021-03-26","effectiveDate":"2021-04-11","coverage":"full","source":{"name":"The Lawphil Project — Arellano Law Foundation","url":"https://lawphil.net/statutes/repacts/ra2021/ra_11534_2021.html"},"summary":{"zh":"下调企业所得税税率、重构税收优惠体系的法案（CREATE）。","en":"An act reforming the corporate income tax and incentives system."}},"summary":{"zh":"下调企业所得税税率、重构税收优惠体系的法案（CREATE）。","en":"An act reforming the corporate income tax and incentives system."}};
  FT["PH-EODB-2018"] = {"id":"PH-EODB-2018","coverage":"full","language":"en","sourceName":"The Lawphil Project — Arellano Law Foundation","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html","fetchedAt":"2026-10-02","articleCount":33,"title":{"zh":"营商便利与高效政府服务提供法","en":"Ease of Doing Business and Efficient Government Service Delivery Act of 2018","orig":"Ease of Doing Business and Efficient Government Service Delivery Act of 2018","vi":"Đạo luật về Thuận lợi Kinh doanh và Dịch vụ Chính phủ Hiệu quả","th":"พระราชบัญญัติอำนวยความสะดวกในการประกอบธุรกิจและการให้บริการภาครัฐที่มีประสิทธิภาพ","id":"Undang-Undang Kemudahan Berusaha dan Pelayanan Pemerintah yang Efisien","ms":"Akta Kemudahan Berniaga dan Perkhidmatan Kerajaan yang Cekap"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 11032","issuingBody":"菲律宾国会","promulgatedDate":"2018-05-28","effectiveDate":"2018-07-27","completenessNote":"官方页面所载为修订型法条：以 “Sec. 1–33” 逐条重述被修正法（R.A. 9485）条文，并夹有 “Section 1–18” 形式的分节标记；本库按官方条号全文收录 33 条（Sec. 1–33），并保留官方结构与条号写法，未增删文字。","country":"PH","countryName":"菲律宾","layer":"fulltext","articles":[{"id":"PH-EODB-2018-A1","no":1,"noLabel":{"en":"Sec. 1."},"text":{"en":"Sec. 1. Short Title. – This Act shall be known as the Ease of Doing Business and Efficient Government Service Delivery Act of 2018\""},"paragraphs":["Short Title.","– This Act shall be known as the Ease of Doing Business and Efficient Government Service Delivery Act of 2018\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A2","no":2,"noLabel":{"en":"Sec. 2."},"text":{"en":"Sec. 2. Declaration of Policy. – It is hereby declared the policy of the State to promote integrity, accountability, proper management of public affairs and public property as well as to establish effective practices, aimed at efficient turnaround of the delivery of government services and the prevention of graft and corruption in government. Towards this end, the State shall maintain honesty and responsibility among its public officials and employees, and shall take appropriate measures to promote transparency in each agency with regard to the manner of transacting with the public, which shall encompass a program for the adoption of simplified requirements and procedures that will reduce red tape and expedite business and nonbusiness related transactions in government.\" Section 3. Section 3 of the same Act is hereby amended to read as follows: \"Sec. 3. Coverage. – This Act shall apply to all government offices and agencies including local government units (LGUs), government-owned or controlled corporations and other government instrumentalities, whether located in the Philippines or abroad, that provide services covering business and nonbusiness related transactions as defined in this Act.\""},"paragraphs":["Declaration of Policy.","– It is hereby declared the policy of the State to promote integrity, accountability, proper management of public affairs and public property as well as to establish effective practices, aimed at efficient turnaround of the delivery of government services and the prevention of graft and corruption in government. Towards this end, the State shall maintain honesty and responsibility among its public officials and employees, and shall take appropriate measures to promote transparency in each agency with regard to the manner of transacting with the public, which shall encompass a program for the adoption of simplified requirements and procedures that will reduce red tape and expedite business and nonbusiness related transactions in government.\"","Section 3. Section 3 of the same Act is hereby amended to read as follows: \"Sec. 3. Coverage. – This Act shall apply to all government offices and agencies including local government units (LGUs), government-owned or controlled corporations and other government instrumentalities, whether located in the Philippines or abroad, that provide services covering business and nonbusiness related transactions as defined in this Act.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A3","no":3,"noLabel":{"en":"Sec. 4."},"text":{"en":"Sec. 4. Definition of Terms. – As used in this Act, the following terms are defined as follows: \"(a) Action refers to the written approval or disapproval made by a government office or agency on the application or request submitted by an applicant or requesting party for processing; \"(b) Business One Stop Shop (BOSS) – a single common site or location, or a single online website or portal designated for the Business Permit and Licensing System (BPLS) of an LGU to receive and process applications, receive payments, and issue approved licenses, clearances, permits, or authorizations; \"(c) Business-related transactions – a set of regulatory requirements that a business entity must comply with to engage, operate or continue to operate a business, such as, but not limited to, collection or preparation of a number of documents, submission to national and local government authorities, approval of application submitted, and receipt of a formal certificate or certificates, permits, licenses which include primary and secondary, clearances and such similar authorization or documents which confer eligibility to operate or continue to operate as a legitimate business; \"(d) Complex transactions – applications or requests submitted by applicants or requesting parties of a government office which necessitate evaluation in the resolution of complicated issues by an officer or employee of said government office, such transactions to be determined by the office concerned; \"(e) Fixer – any individual whether or not officially involved in the operation of a government office or agency who has access to people working therein, and whether or not in collusion with them, facilitates speedy completion of transactions for pecuniary gain or any other advantage or consideration; \"(f) Government service – the process or transaction between applicants or requesting parties and government offices or agencies involving applications for any privilege, right, reward, license, clearance, permit or authorization, concession, of for any modification, renewal or extension of the enumerated applications or requests which are acted upon in the ordinary course of business of the agency or office concerned; \"(g) Highly technical application – an application which requires the use of technical knowledge, specialized skills and/or training in the processing and/or evaluation thereof; \"(h) Nonbusiness transactions – all other government transactions not falling under Section 4 (c) of this Act; \"(i) Officer or employee – a person employed in a government office or agency required to perform specific duties and responsibilities related to the application or request submitted by an applicant or requesting party for processing; \"(j) Processing time – the time consumed by an LGU or national government agency (NGA) from the receipt of an application or request with complete requirements, accompanying documents and payment of fees to the issuance of certification or such similar documents approving or disapproving an application or request; \"(k) Red tape – any regulation, rule, or administrative procedure or system that is ineffective or detrimental in achieving its intended objectives and, as a result, produces slow, suboptimal, and undesirable social outcomes; \"(l) Regulation – any legal instrument that gives effect to a government policy intervention and includes licensing, imposing information obligation, compliance to standards or payment of any form of fee, levy, charge or any other statutory and regulatory requirements necessary to carry out activity; and \"(m) Simple transactions – applications or requests submitted by applicants or requesting parties of a government office or agency which only require ministerial actions on the part of the public officer or employee, or that which present only inconsequential issues for the resolution by an officer or employee of said government.\""},"paragraphs":["Definition of Terms. – As used in this Act, the following terms are defined as follows: \"(a)","Action","refers to the written approval or disapproval made by a government office or agency on the application or request submitted by an applicant or requesting party for processing; \"(b)","Business One Stop Shop (BOSS)","– a single common site or location, or a single online website or portal designated for the Business Permit and Licensing System (BPLS) of an LGU to receive and process applications, receive payments, and issue approved licenses, clearances, permits, or authorizations; \"(c)","Business-related transactions","– a set of regulatory requirements that a business entity must comply with to engage, operate or continue to operate a business, such as, but not limited to, collection or preparation of a number of documents, submission to national and local government authorities, approval of application submitted, and receipt of a formal certificate or certificates, permits, licenses which include primary and secondary, clearances and such similar authorization or documents which confer eligibility to operate or continue to operate as a legitimate business; \"(d)","Complex transactions","– applications or requests submitted by applicants or requesting parties of a government office which necessitate evaluation in the resolution of complicated issues by an officer or employee of said government office, such transactions to be determined by the office concerned; \"(e)","Fixer","– any individual whether or not officially involved in the operation of a government office or agency who has access to people working therein, and whether or not in collusion with them, facilitates speedy completion of transactions for pecuniary gain or any other advantage or consideration; \"(f)","Government service","– the process or transaction between applicants or requesting parties and government offices or agencies involving applications for any privilege, right, reward, license, clearance, permit or authorization, concession, of for any modification, renewal or extension of the enumerated applications or requests which are acted upon in the ordinary course of business of the agency or office concerned; \"(g)","Highly technical application","– an application which requires the use of technical knowledge, specialized skills and/or training in the processing and/or evaluation thereof; \"(h)","Nonbusiness transactions","– all other government transactions not falling under Section 4 (c) of this Act; \"(i)","Officer or employee","– a person employed in a government office or agency required to perform specific duties and responsibilities related to the application or request submitted by an applicant or requesting party for processing; \"(j)","Processing time","– the time consumed by an LGU or national government agency (NGA) from the receipt of an application or request with complete requirements, accompanying documents and payment of fees to the issuance of certification or such similar documents approving or disapproving an application or request; \"(k)","Red tape","– any regulation, rule, or administrative procedure or system that is ineffective or detrimental in achieving its intended objectives and, as a result, produces slow, suboptimal, and undesirable social outcomes; \"(l)","Regulation","– any legal instrument that gives effect to a government policy intervention and includes licensing, imposing information obligation, compliance to standards or payment of any form of fee, levy, charge or any other statutory and regulatory requirements necessary to carry out activity; and \"(m)","Simple transactions","– applications or requests submitted by applicants or requesting parties of a government office or agency which only require ministerial actions on the part of the public officer or employee, or that which present only inconsequential issues for the resolution by an officer or employee of said government.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A4","no":4,"noLabel":{"en":"Sec. 5."},"text":{"en":"Sec. 5. Reengineering of Systems and Procedures. – All offices and agencies which provide government services are hereby mandated to regularly undertake cost compliance analysis, time and motion studies, undergo evaluation and improvement of their transaction systems and procedures and reengineer the same if deemed necessary to reduce bureaucratic red tape and processing time. \"The Anti-Red Tape Authority, created in this Act, shall coordinate with all government offices covered under Section 3 of this Act in the review of existing laws, executive issuances and local ordinances, and recommend the repeal of the same if deemed outdated, redundant, and adds undue regulatory burden to the transacting public. \"All proposed regulations of government agencies under Section 3 of this Act shall undergo regulatory impact assessment to establish if the proposed regulation does not add undue regulatory burden and cost to these agencies and the applicants or requesting parties: Provided, That when necessary, any proposed regulation may undergo pilot implementation to assess regulatory impact. \"Upon effectivity of this Act, all LGUs and NGAs are directed to initiate review of existing policies and operations and commence with the reengineering of their systems and procedures in compliance with the provisions of this Act, pending the approval of the implementing rules and regulations (IRR) thereof.\""},"paragraphs":["Reengineering of Systems and Procedures.","– All offices and agencies which provide government services are hereby mandated to regularly undertake cost compliance analysis, time and motion studies, undergo evaluation and improvement of their transaction systems and procedures and reengineer the same if deemed necessary to reduce bureaucratic red tape and processing time. \"The Anti-Red Tape Authority, created in this Act, shall coordinate with all government offices covered under Section 3 of this Act in the review of existing laws, executive issuances and local ordinances, and recommend the repeal of the same if deemed outdated, redundant, and adds undue regulatory burden to the transacting public. \"All proposed regulations of government agencies under Section 3 of this Act shall undergo regulatory impact assessment to establish if the proposed regulation does not add undue regulatory burden and cost to these agencies and the applicants or requesting parties:","Provided,","That when necessary, any proposed regulation may undergo pilot implementation to assess regulatory impact. \"Upon effectivity of this Act, all LGUs and NGAs are directed to initiate review of existing policies and operations and commence with the reengineering of their systems and procedures in compliance with the provisions of this Act, pending the approval of the implementing rules and regulations (IRR) thereof.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A5","no":5,"noLabel":{"en":"Sec. 6."},"text":{"en":"Sec. 6. Citizen’s Charter. – All government agencies including departments, bureaus, offices, instrumentalities, or government-owned and/or –controlled corporations, or LGUs shall set up their respective most current and updated service standards to be known as the Citizen’s Charter in the form of information billboards which shall be posted at the main entrance of offices or at the most conspicuous place, in their respective websites and in the form of published materials written either in English, Filipino, or in the local dialect, that detail: \"(a) A comprehensive and uniform checklist of requirements for each type of application or request; \"(b) The procedure to obtain a particular service; \"(c) The person/s responsible for each step; \"(d) The maximum time to conclude the process; \"(e) The document/s to be presented by the applicant or requesting party, if necessary; \"(f) The amount of fees, if necessary; and \"(g) The procedure for filing complaints.\""},"paragraphs":["Citizen’s Charter.","– All government agencies including departments, bureaus, offices, instrumentalities, or government-owned and/or –controlled corporations, or LGUs shall set up their respective most current and updated service standards to be known as the Citizen’s Charter in the form of information billboards which shall be posted at the main entrance of offices or at the most conspicuous place, in their respective websites and in the form of published materials written either in English, Filipino, or in the local dialect, that detail: \"(a) A comprehensive and uniform checklist of requirements for each type of application or request; \"(b) The procedure to obtain a particular service; \"(c) The person/s responsible for each step; \"(d) The maximum time to conclude the process; \"(e) The document/s to be presented by the applicant or requesting party, if necessary; \"(f) The amount of fees, if necessary; and \"(g) The procedure for filing complaints.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A6","no":6,"noLabel":{"en":"Sec. 7."},"text":{"en":"Sec. 7. Zero-Contact Policy. – Except during the preliminary assessment of the request and evaluation of sufficiency of submitted requirements, no government officer or employee shall have any contact, in any manner, unless strictly necessary with any applicant or requesting party concerning an application or request. Once the Department of Information and Communications Technology (DICT) has completed a web-based software enabled business registration system that is acceptable to the public as mandated under Section 26 of this Act, all transactions shall be coursed through such system. All government agencies including LGUs shall adopt a zero-contact policy.\""},"paragraphs":["Zero-Contact Policy.","– Except during the preliminary assessment of the request and evaluation of sufficiency of submitted requirements, no government officer or employee shall have any contact, in any manner, unless strictly necessary with any applicant or requesting party concerning an application or request. Once the Department of Information and Communications Technology (DICT) has completed a web-based software enabled business registration system that is acceptable to the public as mandated under Section 26 of this Act, all transactions shall be coursed through such system. All government agencies including LGUs shall adopt a zero-contact policy.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A7","no":7,"noLabel":{"en":"Sec. 8."},"text":{"en":"Sec. 8. Accountability of Heads of Offices and Agencies. – The head of the office or agency shall be primarily responsible for the implementation of this Act and shall be held accountable to the public in rendering fast, efficient, convenient and reliable service. All transactions and processes are deemed to have been made with the permission or clearance from the highest authority having jurisdiction over the government office or agency concerned.\""},"paragraphs":["Accountability of Heads of Offices and Agencies.","– The head of the office or agency shall be primarily responsible for the implementation of this Act and shall be held accountable to the public in rendering fast, efficient, convenient and reliable service. All transactions and processes are deemed to have been made with the permission or clearance from the highest authority having jurisdiction over the government office or agency concerned.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A8","no":8,"noLabel":{"en":"Sec. 9."},"text":{"en":"Sec. 9. Accessing Government Services. – The following shall adopted by all government offices and agencies: \"(a) Acceptance of Applications or Requests. – \"(1) All officers or employees shall accept written applications, requests, and/or documents being submitted by applicants or requesting parties of the offices or agencies. \"(2) The receiving officer or employee shall perform a preliminary assessment of the application or request submitted with its supporting documents to ensure a more expeditious action on the application or request. The receiving officer or employee shall immediately inform the applicant or requesting party of any deficiency in the accompanying requirements, which shall be limited to those enumerated in the Citizen’s Charter. \"(3) The receiving officer or employee shall assign a unique identification number to an application or request, which shall be the identifying number for all subsequent transactions between the government and the applicant or requesting party regarding such specific application or request. \"(4) The receiving officer or employee shall issue an acknowledgement receipt containing the seal of the agency, the name of the responsible officer or employee, his/her unit and designation, and the date and time of receipt of such application or request. \"(b) Action of Offices. – \"(1) All applications or requests submitted shall be acted upon by the assigned officer or employee within the prescribed processing time stated in the Citizen’s Charter which shall not be longer than three (3) working days in the case of simple transactions and seven (7) working days in the case of complex transactions from the date the request and/or complete application or request was received. \"For applications or requests involving activities which pose danger to public health, public safety, public morals, public policy, and highly technical application, the prescribed processing time shall in no case be longer than twenty (20) working days or as determined by the government agency or instrumentality concerned, whichever is shorter. \"The maximum time prescribed above may be extended only once for the same number of days, which shall be indicated in the Citizen’s Charter. Prior to the lapse of the processing time, the office or agency concerned shall notify the applicant or requesting party in writing of the reason for the extension and final date of release of the government service/s requested. Such written notification shall be signed by the applicant or requesting party to serve as proof of notice. \"If the application or request for license, clearance permit, certification or authorization shall require the approval of the local Sangguniang Bayan , Sangguniang Panlungsod, or the Sangguniang Panlalawigan as the case may be, the Sanggunian concerned shall be given a period of forty-five (45) working days to act on the application or request, which can be extended for another twenty (20) working days. If the local Sanggunian concerned has denied the application or request, the reason for the denial, as well as the remedial measures that may be taken by the applicant shall be cited by the concerned Sanggunian. \"In cases where the cause of delay is due to force majeure or natural or man-made disasters, which result to damage or destruction of documents, and/or system failure of the computerized or automatic processing, the prescribed processing times mandated in this Act shall be suspended and appropriate adjustments shall be made. \"(2) No application or request shall be returned to the applicant or requesting party without appropriate action. In case an application or request is disapproved, the officer or employee who rendered the decision shall send a formal notice to the applicant or requesting party within the prescribed processing time, stating therein the reason for the disapproval. A finding by a competent authority of a violation of any or other laws by the applicant or requesting party shall constitute a valid ground for the disapproval of the application or request, without prejudice to other grounds provided in this Act or other pertinent laws. \"(c) Denial of Application or Request for Access to Government Service. – Any denial of application or request for access to government service shall be fully explained in writing, stating the name of the person making the denial and the grounds upon which such denial is based. Any denial of application or request is deemed to have been made with the permission or clearance from the highest authority having jurisdiction over the government office or agency concerned. \"(d) Limitation of Signatories – The number of signatories in any document shall be limited to a maximum of three (3) signatures which shall represent officers directly supervising the office or agency concerned: Provided, That in case the authorized signatory is on official business or official leave, an alternate shall be designated as signatory. Electronic signatures or pre-signed license, clearance, permit, certification or authorization with adequate security and control mechanism may be used. \"(e) Electronic Versions of Licenses, Clearances, Permits, Certifications or Authorizations. – All government agencies covered under Section 3 of this Act shall, when applicable, develop electronic versions of licenses, clearances, permits, certifications or authorizations with the same level of authority as that of the signed hard copy, which may be printed by the applicants or requesting parties in the convenience of their offices. \"(f) Adoption of Working Schedules to Serve Applicants or Requesting Parties. – Heads of offices and agencies which render government services shall adopt appropriate working schedules to ensure that all applicants or requesting parties who are within their premises prior to the end of official working hours are attended to and served even during lunch break and after regular working hours. \"(g) Identification Card. – All employees transacting with the public shall be provided with an official identification card which shall be visibly worn during office hours. \"(h) Establishment of Public Assistance/Complaints Desk. – Each office or agency shall establish a public assistance/complaints desk in all their offices.\""},"paragraphs":["Accessing Government Services.","– The following shall adopted by all government offices and agencies: \"(a) Acceptance of Applications or Requests. – \"(1) All officers or employees shall accept written applications, requests, and/or documents being submitted by applicants or requesting parties of the offices or agencies. \"(2) The receiving officer or employee shall perform a preliminary assessment of the application or request submitted with its supporting documents to ensure a more expeditious action on the application or request. The receiving officer or employee shall immediately inform the applicant or requesting party of any deficiency in the accompanying requirements, which shall be limited to those enumerated in the Citizen’s Charter. \"(3) The receiving officer or employee shall assign a unique identification number to an application or request, which shall be the identifying number for all subsequent transactions between the government and the applicant or requesting party regarding such specific application or request. \"(4) The receiving officer or employee shall issue an acknowledgement receipt containing the seal of the agency, the name of the responsible officer or employee, his/her unit and designation, and the date and time of receipt of such application or request. \"(b) Action of Offices. – \"(1) All applications or requests submitted shall be acted upon by the assigned officer or employee within the prescribed processing time stated in the Citizen’s Charter which shall not be longer than three (3) working days in the case of simple transactions and seven (7) working days in the case of complex transactions from the date the request and/or complete application or request was received. \"For applications or requests involving activities which pose danger to public health, public safety, public morals, public policy, and highly technical application, the prescribed processing time shall in no case be longer than twenty (20) working days or as determined by the government agency or instrumentality concerned, whichever is shorter. \"The maximum time prescribed above may be extended only once for the same number of days, which shall be indicated in the Citizen’s Charter. Prior to the lapse of the processing time, the office or agency concerned shall notify the applicant or requesting party in writing of the reason for the extension and final date of release of the government service/s requested. Such written notification shall be signed by the applicant or requesting party to serve as proof of notice. \"If the application or request for license, clearance permit, certification or authorization shall require the approval of the local","Sangguniang Bayan",",","Sangguniang Panlungsod,","or the","Sangguniang Panlalawigan","as the case may be, the","Sanggunian","concerned shall be given a period of forty-five (45) working days to act on the application or request, which can be extended for another twenty (20) working days. If the local","Sanggunian","concerned has denied the application or request, the reason for the denial, as well as the remedial measures that may be taken by the applicant shall be cited by the concerned","Sanggunian.","\"In cases where the cause of delay is due to force majeure or natural or man-made disasters, which result to damage or destruction of documents, and/or system failure of the computerized or automatic processing, the prescribed processing times mandated in this Act shall be suspended and appropriate adjustments shall be made. \"(2) No application or request shall be returned to the applicant or requesting party without appropriate action. In case an application or request is disapproved, the officer or employee who rendered the decision shall send a formal notice to the applicant or requesting party within the prescribed processing time, stating therein the reason for the disapproval. A finding by a competent authority of a violation of any or other laws by the applicant or requesting party shall constitute a valid ground for the disapproval of the application or request, without prejudice to other grounds provided in this Act or other pertinent laws. \"(c) Denial of Application or Request for Access to Government Service. – Any denial of application or request for access to government service shall be fully explained in writing, stating the name of the person making the denial and the grounds upon which such denial is based. Any denial of application or request is deemed to have been made with the permission or clearance from the highest authority having jurisdiction over the government office or agency concerned. \"(d) Limitation of Signatories – The number of signatories in any document shall be limited to a maximum of three (3) signatures which shall represent officers directly supervising the office or agency concerned:","Provided,","That in case the authorized signatory is on official business or official leave, an alternate shall be designated as signatory. Electronic signatures or pre-signed license, clearance, permit, certification or authorization with adequate security and control mechanism may be used. \"(e) Electronic Versions of Licenses, Clearances, Permits, Certifications or Authorizations. – All government agencies covered under Section 3 of this Act shall, when applicable, develop electronic versions of licenses, clearances, permits, certifications or authorizations with the same level of authority as that of the signed hard copy, which may be printed by the applicants or requesting parties in the convenience of their offices. \"(f) Adoption of Working Schedules to Serve Applicants or Requesting Parties. – Heads of offices and agencies which render government services shall adopt appropriate working schedules to ensure that all applicants or requesting parties who are within their premises prior to the end of official working hours are attended to and served even during lunch break and after regular working hours. \"(g) Identification Card. – All employees transacting with the public shall be provided with an official identification card which shall be visibly worn during office hours. \"(h) Establishment of Public Assistance/Complaints Desk. – Each office or agency shall establish a public assistance/complaints desk in all their offices.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A9","no":9,"noLabel":{"en":"Sec. 10."},"text":{"en":"Sec. 10. Automatic Approval or Automatic Extension of License, Clearance, Permit, Certification or Authorization. – If a government office or agency fails to approve or disapprove an original application or request for issuance of license, clearance, permit, certification or authorization within the prescribed processing time, said application or request shall be deemed approved: Provided, That all required documents have been submitted and all required fees and charges have been paid. The acknowledgment receipt together with the official receipt for payment of all required fees issued to the applicant or requesting party shall be enough proof or has the same force and effect of a license, clearance, permit, certification or authorization under this automatic approval mechanism. \"if a government office or agency fails to act on an application or request for renewal of a license, clearance, permit, certification or authorization subject for renewal within the prescribed processing time, said license, clearance, permit, certification or authorization shall automatically be extended: Provided, That the Authority, in coordination with the Civil Service Commission (CSC), Department of Trade and Industry (DTI), Securities and Exchange Commission (SEC), Department of the Interior and Local Government (DILG) and other agencies which shall formulate the IRR of this Act, shall provide a listing of simple, complex, highly technical applications, and activities which pose danger to public health, public safety, public morals or to public policy.\""},"paragraphs":["Automatic Approval or Automatic Extension of License, Clearance, Permit, Certification or Authorization.","– If a government office or agency fails to approve or disapprove an original application or request for issuance of license, clearance, permit, certification or authorization within the prescribed processing time, said application or request shall be deemed approved:","Provided,","That all required documents have been submitted and all required fees and charges have been paid. The acknowledgment receipt together with the official receipt for payment of all required fees issued to the applicant or requesting party shall be enough proof or has the same force and effect of a license, clearance, permit, certification or authorization under this automatic approval mechanism. \"if a government office or agency fails to act on an application or request for renewal of a license, clearance, permit, certification or authorization subject for renewal within the prescribed processing time, said license, clearance, permit, certification or authorization shall automatically be extended:","Provided,","That the Authority, in coordination with the Civil Service Commission (CSC), Department of Trade and Industry (DTI), Securities and Exchange Commission (SEC), Department of the Interior and Local Government (DILG) and other agencies which shall formulate the IRR of this Act, shall provide a listing of simple, complex, highly technical applications, and activities which pose danger to public health, public safety, public morals or to public policy.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A10","no":10,"noLabel":{"en":"Sec. 11."},"text":{"en":"Sec. 11. Streamlined Procedures for the Issuance of Local Business Licenses, Clearances, Permits, Certifications or Authorizations. – The LGUs are mandated to implement the following revised guidelines in the issuance of business licenses, clearances, permits, certifications or authorizations: \"(a) A single or unified business application form shall be used in processing new applications for business permits and business renewals which consolidates all the information of the applicant or requesting party by various local government departments, such as, but not limited to, the local taxes and clearances, building clearance, sanitary permit, zoning clearance, and other specific LGU requirements, as the case may be, including the fire clearance from the Bureau of Fire Protection (BFP). The unified form shall be made available online using technology-neutral platforms such as, but not limited to, the central business portal or the city/municipality’s website and various channels for dissemination. Hard copies of the unified forms shall likewise be made available at all times in designated areas of the concerned office and/or agency. \"(b) A one-stop business facilitation service, hereinafter referred to as the business one stop shop, (BOSS) for the city/municipality’s business permitting and licensing system to receive and process manual and/or electronic submission of application for license, clearance, permit, certification or authorization shall be established within the cities/municipalities’ Negosyo Center as provided for under Republic Act No. 10644, otherwise known as the \"Go Negosyo Act.\" There shall be a queuing mechanism in the BOSS to better manage the flow of applications among the LGUs’ departments receiving and processing applications. LGUs shall implement collocation of the offices of the treasury, business permits and licensing office, zoning office, including the BFP, and other relevant city/municipality offices/departments, among others, engaged in starting a business, dealing with construction permits. \"(c) Cities/Municipalities are mandated to automate their business permitting and licensing system or set up an electronic BOSS within a period of three (3) years upon the effectivity of this Act for a more efficient business registration processes. Cities/Municipalities with electronic BOSS shall develop electronic versions of licenses, clearances, permits, certifications or authorizations with the same level of authority, which may be printed by businesses in the convenience of their offices. The DICT shall make available to LGUs the software for the computerization of the business permit and licensing system. The DICT, DTI, and DILG, shall provide technical assistance in the planning and implementation of a computerized or software-enabled business permitting and licensing system. \"(d) To lessen the transaction requirements, other local clearances such as, but not limited to, sanitary permits, environmental and agricultural clearances shall be issued together with the business permit. \"(e) Business permits shall be valid for a period of one (1) year. The city/municipality may have the option to renew business permits within the first month of the year or on the anniversary date of the issuance of the business permit. \"(f) Barangay clearances and permits related to doing business shall be applied, issued, and collected at the city/municipality in accordance with the prescribed processing time of this Act: Provided,"},"paragraphs":["Streamlined Procedures for the Issuance of Local Business Licenses, Clearances, Permits, Certifications or Authorizations.","– The LGUs are mandated to implement the following revised guidelines in the issuance of business licenses, clearances, permits, certifications or authorizations: \"(a) A single or unified business application form shall be used in processing new applications for business permits and business renewals which consolidates all the information of the applicant or requesting party by various local government departments, such as, but not limited to, the local taxes and clearances, building clearance, sanitary permit, zoning clearance, and other specific LGU requirements, as the case may be, including the fire clearance from the Bureau of Fire Protection (BFP). The unified form shall be made available online using technology-neutral platforms such as, but not limited to, the central business portal or the city/municipality’s website and various channels for dissemination. Hard copies of the unified forms shall likewise be made available at all times in designated areas of the concerned office and/or agency. \"(b) A one-stop business facilitation service, hereinafter referred to as the business one stop shop, (BOSS) for the city/municipality’s business permitting and licensing system to receive and process manual and/or electronic submission of application for license, clearance, permit, certification or authorization shall be established within the cities/municipalities’","Negosyo Center","as provided for under Republic Act No. 10644, otherwise known as the \"Go Negosyo Act.\" There shall be a queuing mechanism in the BOSS to better manage the flow of applications among the LGUs’ departments receiving and processing applications. LGUs shall implement collocation of the offices of the treasury, business permits and licensing office, zoning office, including the BFP, and other relevant city/municipality offices/departments, among others, engaged in starting a business, dealing with construction permits. \"(c) Cities/Municipalities are mandated to automate their business permitting and licensing system or set up an electronic BOSS within a period of three (3) years upon the effectivity of this Act for a more efficient business registration processes. Cities/Municipalities with electronic BOSS shall develop electronic versions of licenses, clearances, permits, certifications or authorizations with the same level of authority, which may be printed by businesses in the convenience of their offices. The DICT shall make available to LGUs the software for the computerization of the business permit and licensing system. The DICT, DTI, and DILG, shall provide technical assistance in the planning and implementation of a computerized or software-enabled business permitting and licensing system. \"(d) To lessen the transaction requirements, other local clearances such as, but not limited to, sanitary permits, environmental and agricultural clearances shall be issued together with the business permit. \"(e) Business permits shall be valid for a period of one (1) year. The city/municipality may have the option to renew business permits within the first month of the year or on the anniversary date of the issuance of the business permit. \"(f) Barangay clearances and permits related to doing business shall be applied, issued, and collected at the city/municipality in accordance with the prescribed processing time of this Act:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A11","no":11,"noLabel":{"en":"Sec. 12."},"text":{"en":"Sec. 12. Sreamlined Procedures for Securing Fire Safety Evaluation Clearance (FSEC), Fire Safety Inspection Certificate (FSIC), and Certification of Fire Incidents for Fire Insurance. - For the issuance of FSEC, FSIC, and certification of fire incidents, the following shall be adopted to make business permitting more efficient: \"(a) Issuance of FSEC and FSIC shall in no case be longer than seven (7) working days; \"(b) For new business permit application, the FSIC already issued during the occupancy permit stage shall be sufficient as basis for the issuance of the FSIC for a business entity as a requirement for the business permit; \"(c) For renewal of business permit, the BFP shall, within three (3) working days from application, present the FSIC to the city/municipality, either thru the copy of the FSIC or the negative/positive list: Provided,"},"paragraphs":["Sreamlined Procedures for Securing Fire Safety Evaluation Clearance (FSEC), Fire Safety Inspection Certificate (FSIC), and Certification of Fire Incidents for Fire Insurance.","- For the issuance of FSEC, FSIC, and certification of fire incidents, the following shall be adopted to make business permitting more efficient: \"(a) Issuance of FSEC and FSIC shall in no case be longer than seven (7) working days; \"(b) For new business permit application, the FSIC already issued during the occupancy permit stage shall be sufficient as basis for the issuance of the FSIC for a business entity as a requirement for the business permit; \"(c) For renewal of business permit, the BFP shall, within three (3) working days from application, present the FSIC to the city/municipality, either thru the copy of the FSIC or the negative/positive list:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A12","no":12,"noLabel":{"en":"Sec. 13."},"text":{"en":"Sec. 13. Central Business Portal (CBP). – To eliminate bureaucratic red tape, avert graft and corrupt practices and to promote transparency and sustain ease of doing business, the DICT shall be primarily responsible in establishing, operating and maintaining a CBP or other similar technology, as the DICT may prescribe. \"The CBP shall serve as a central system to receive applications and capture application data involving business-related transactions, including primary and secondary licenses, and business clearances, permits, certifications, or authorizations issued by the LGUs: Provided,"},"paragraphs":["Central Business Portal (CBP).","– To eliminate bureaucratic red tape, avert graft and corrupt practices and to promote transparency and sustain ease of doing business, the DICT shall be primarily responsible in establishing, operating and maintaining a CBP or other similar technology, as the DICT may prescribe. \"The CBP shall serve as a central system to receive applications and capture application data involving business-related transactions, including primary and secondary licenses, and business clearances, permits, certifications, or authorizations issued by the LGUs:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A13","no":13,"noLabel":{"en":"Sec. 14."},"text":{"en":"Sec. 14. Philippine Business Databank (PBD)."},"paragraphs":["Philippine Business Databank (PBD)."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A14","no":14,"noLabel":{"en":"Sec. 15."},"text":{"en":"Sec. 15. Interconnectivity Infrastructure Development. – In order to expedite the processing of licenses, clearances, permits, certifications or authorizations, the Authority, together with the DICT, shall develop a fast and reliable interconnectivity infrastructure. In relation to this, the processing and approval or licenses, clearances, permits, certifications or authorizations for the installation and operation of telecommunication, broadcast towers, facilities, equipment and service shall be: \"(a) a total of seven (7) working days for those issued by the barangay; \"(b) a total of seven (7) working days for those issued by LGUs; and \"(c) seven (7) working days for those issued by NGAs. \"If the granting authority fails to approve or disapprove an application for a license, clearance, permit, certification or authorization within the prescribed processing time, said application shall be deemed approved: Provided, That when the approval of the appropriate local legislative body is necessary, a nonextendible period of twenty (20) working days is hereby prescribed. \"For homeowners and other community clearances, the officers of the homeowners association shall be given ten (10) working days to refer the application to the members of the association pursuant to Section 10(k) of Republic Act No. 9904, otherwise known as the \"Magna Carta for Homeowners and Homeowners Associations\": Provided, That a nonextendible period of thirty (30) working days is granted the homeowners association to give its consent or disapproval: Provided, further,"},"paragraphs":["Interconnectivity Infrastructure Development.","– In order to expedite the processing of licenses, clearances, permits, certifications or authorizations, the Authority, together with the DICT, shall develop a fast and reliable interconnectivity infrastructure. In relation to this, the processing and approval or licenses, clearances, permits, certifications or authorizations for the installation and operation of telecommunication, broadcast towers, facilities, equipment and service shall be: \"(a) a total of seven (7) working days for those issued by the barangay; \"(b) a total of seven (7) working days for those issued by LGUs; and \"(c) seven (7) working days for those issued by NGAs. \"If the granting authority fails to approve or disapprove an application for a license, clearance, permit, certification or authorization within the prescribed processing time, said application shall be deemed approved:","Provided,","That when the approval of the appropriate local legislative body is necessary, a nonextendible period of twenty (20) working days is hereby prescribed. \"For homeowners and other community clearances, the officers of the homeowners association shall be given ten (10) working days to refer the application to the members of the association pursuant to Section 10(k) of Republic Act No. 9904, otherwise known as the \"Magna Carta for Homeowners and Homeowners Associations\":","Provided,","That a nonextendible period of thirty (30) working days is granted the homeowners association to give its consent or disapproval:","Provided, further,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A15","no":15,"noLabel":{"en":"Sec. 16."},"text":{"en":"Sec. 16. Anti-Red Tape Unit in the Civil Service Commission (CSC)."},"paragraphs":["Anti-Red Tape Unit in the Civil Service Commission (CSC)."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A16","no":16,"noLabel":{"en":"Sec. 17."},"text":{"en":"Sec. 17. Anti-Red Tape Authority. – To ensure the attainment of the objectives of this Act, there is hereby created the Anti-Red Tape Authority, herein referred to as the Authority, which shall be organized within six (6) months after the effectivity of this Act. The authority shall be attached to the Office of the President. \"The Authority shall have the following powers and functions: \"(a) Implement and oversee a national policy on anti-red tape and ease of doing business; \"(b) Implement various ease of doing business and anti-red tape reform initiatives aimed at improving the ranking of the Philippines; \"(c) Monitor and evaluate the compliance of agencies covered under Section 3 of this Act, and issue notice of warning to erring and/or noncomplying government employees or officials; \"(d) Initiate investigation, motu proprio"},"paragraphs":["Anti-Red Tape Authority.","– To ensure the attainment of the objectives of this Act, there is hereby created the Anti-Red Tape Authority, herein referred to as the Authority, which shall be organized within six (6) months after the effectivity of this Act. The authority shall be attached to the Office of the President. \"The Authority shall have the following powers and functions: \"(a) Implement and oversee a national policy on anti-red tape and ease of doing business; \"(b) Implement various ease of doing business and anti-red tape reform initiatives aimed at improving the ranking of the Philippines; \"(c) Monitor and evaluate the compliance of agencies covered under Section 3 of this Act, and issue notice of warning to erring and/or noncomplying government employees or officials; \"(d) Initiate investigation,","motu proprio"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A17","no":17,"noLabel":{"en":"Sec. 18."},"text":{"en":"Sec. 18. Composition of the Authority. - The Authority shall be headed by a Director General to be appointed by the"},"paragraphs":["Composition of the Authority.","- The Authority shall be headed by a Director General to be appointed by the President of the Philippines upon effectivity of this Act, and such appointment shall be coterminous with the tenure of the President of the Philippines. The Director General shall enjoy the benefits, privileges, and emoluments equivalent to the rank of Secretary. \"The Director General shall oversee the day-to-day operations of the Authority. He/She shall be assisted by three (3) Deputy Directors General each for legal, operations, and administration and finance:","Provided,","That they are career officials as defined in existing laws, rules and regulations. The Deputy Directors General shall enjoy the benefits, privileges, and emoluments equivalent to the rank of Undersecretary and shall likewise be appointed by the President of the Philippines. \"The Director General of the Authority, in consultation with the CSC, DTI and the Department of Budget and Management (DBM), shall determine the organizational structures including regional or field offices, qualification standards, staffing pattern and compensation of the newly created Authority in accordance with existing laws, rules and regulations:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A18","no":18,"noLabel":{"en":"Sec. 19."},"text":{"en":"Sec. 19. Ease of Doing Business and Anti-Red Tape Advisory Council.- There is hereby created an Ease of Doing Business and Anti-Red Tape Advisory Council, herein referred to as the Council. It shall be composed of the Secretary of the DTI as Chairperson, the Director General of the Authority as Vice-Chairperson, the Secretaries of the DICT, DILG and Department of Finance (DOF), and two (2) representatives from the private sector as the members. The department secretaries may designate their representatives, who shall sit in a permanent capacity, with no less than Undersecretary in rank, and their acts shall be considered the acts of their principals. The private sector representatives shall be appointed by the"},"paragraphs":["Ease of Doing Business and Anti-Red Tape Advisory Council.-","There is hereby created an Ease of Doing Business and Anti-Red Tape Advisory Council, herein referred to as the Council. It shall be composed of the Secretary of the DTI as Chairperson, the Director General of the Authority as Vice-Chairperson, the Secretaries of the DICT, DILG and Department of Finance (DOF), and two (2) representatives from the private sector as the members. The department secretaries may designate their representatives, who shall sit in a permanent capacity, with no less than Undersecretary in rank, and their acts shall be considered the acts of their principals. The private sector representatives shall be appointed by the President of the Philippines for a term of three (3) years, and may be reappointed only once, from the nominees submitted by reputable business groups or associations. \"The Council shall be the policy and advisory body to the Authority. The Council shall formulate policies and programs that will continuously enhance and improve the country’s competitiveness and ease of doing business. Towards this end, the Council shall have the following powers and functions: \"(a) Plan, draft and propose a national policy on ease of doing business and anti-red tape; \"(b) Recommend policies, processes and systems to improve regulatory management to increase the productivity, efficiency, and effectiveness of permitting and licensing agencies; \"(c) Design and identify systems that will continuously enhance and improve the delivery of services in government and ease of doing business in the country; \"(d) Authorize the creation or appointment of specific working groups or task forces in aid of the implementation of this Act; \"(e) Propose legislation, amendments or modifications to Philippine laws related to anti-red tape and ease of doing business; \"(f) Periodically review and assess the country’s competitiveness performance, challenges, and issues; \"(g) Provide technical assistance and advisory opinions in the review of proposed national or local legislation, regulations, or procedures; \"(h) Recommend to the Authority the issuance of the appropriate measures to promote transparency and efficiency in business practices and delivery of services in government; and \"(i) Perform such other functions as may be necessary or as may be directed by the President of the Philippines for the successful implementation to attain the objectives of this Act. \"The Authority shall serve as Secretariat to the Council to be headed by its Deputy Director General for operations. \"The National Competitiveness Council (NCC), created under Executive Order No. 44, Series of 2011, shall be renamed and reorganized as the Council. The pertinent provisions under the following presidential orders: Executive Order No. 571, Executive Order No. 44, and Administrative Order No. 38 are hereby repealed accordingly.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A19","no":19,"noLabel":{"en":"Sec. 20."},"text":{"en":"Sec. 20. Report Card Survey. – All offices and agencies providing government services shall be subjected to a Report Card Survey to be initiated by the Authority, in coordination with the CSC, and the Philippine Statistics Authority (PSA), which shall be used to obtain feedback on how provisions of this Act are being followed and how the agency is performing. \"The Report Card Survey shall also be used to obtain information and/or estimates of hidden costs incurred by applicants or requesting parties to access governments services which may include, but is not limited to, bribes and payment to fixers. The result of the survey shall also become basis for the grant of awards, recognition and/or incentives for excellent delivery of services in all government agencies. \"A feedback mechanism shall be established in all agencies covered by this Act and the results thereof shall be incorporated in their annual report.\""},"paragraphs":["Report Card Survey.","– All offices and agencies providing government services shall be subjected to a Report Card Survey to be initiated by the Authority, in coordination with the CSC, and the Philippine Statistics Authority (PSA), which shall be used to obtain feedback on how provisions of this Act are being followed and how the agency is performing. \"The Report Card Survey shall also be used to obtain information and/or estimates of hidden costs incurred by applicants or requesting parties to access governments services which may include, but is not limited to, bribes and payment to fixers. The result of the survey shall also become basis for the grant of awards, recognition and/or incentives for excellent delivery of services in all government agencies. \"A feedback mechanism shall be established in all agencies covered by this Act and the results thereof shall be incorporated in their annual report.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A20","no":20,"noLabel":{"en":"Sec. 21."},"text":{"en":"Sec. 21. Violations and Persons Liable."},"paragraphs":["Violations and Persons Liable."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A21","no":21,"noLabel":{"en":"Sec. 22."},"text":{"en":"Sec. 22. Penalties and Liabilities. – Any violations of the preceding actions will warrant the following penalties and liabilities.1âwphi1 \"(a) First Offense: Administrative liability with six (6) months suspension: Provided, however, That in the case of fixing and/or collusion with fixers under Section 21(h), the penalty and liability under Section 22(b) of this Act shall apply. \"(b) Second Offense: Administrative liability and criminal liability of dismissal from the service, perpetual disqualification from holding public office and forfeiture of retirement benefits and imprisonment of one (1) year to six (6) years with a fine of not less than Five hundred thousand pesos (P500,000.00), but not more than Two million pesos (P2,000,000.00). \"Criminal liability shall also be incurred through the commission of bribery, extortion, or when the violation was done deliberately and maliciously to solicit favor in cash or in kind. In such cases, the pertinent provisions of the Revised Penal Code and other special laws shall apply.\""},"paragraphs":["Penalties and Liabilities.","– Any violations of the preceding actions will warrant the following penalties and liabilities.1âwphi1 \"(a) First Offense: Administrative liability with six (6) months suspension:","Provided, however,","That in the case of fixing and/or collusion with fixers under Section 21(h), the penalty and liability under Section 22(b) of this Act shall apply. \"(b) Second Offense: Administrative liability and criminal liability of dismissal from the service, perpetual disqualification from holding public office and forfeiture of retirement benefits and imprisonment of one (1) year to six (6) years with a fine of not less than Five hundred thousand pesos (P500,000.00), but not more than Two million pesos (P2,000,000.00). \"Criminal liability shall also be incurred through the commission of bribery, extortion, or when the violation was done deliberately and maliciously to solicit favor in cash or in kind. In such cases, the pertinent provisions of the Revised Penal Code and other special laws shall apply.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A22","no":22,"noLabel":{"en":"Sec. 23."},"text":{"en":"Sec. 23. Civil and Criminal Liability, Not Barred. - The finding of administrative liability under this Act shall not be a bar to the filing of criminal, civil or other related charges under existing laws arising from the same act or omission as herein enumerated.\""},"paragraphs":["Civil and Criminal Liability, Not Barred.","- The finding of administrative liability under this Act shall not be a bar to the filing of criminal, civil or other related charges under existing laws arising from the same act or omission as herein enumerated.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A23","no":23,"noLabel":{"en":"Sec. 24."},"text":{"en":"Sec. 24. Administrative Jurisdiction. – The administrative jurisdiction on any violation of the provisions of this Act shall be vested in either the CSC, or the Office of the Ombudsman as determined by appropriate laws and issuances.\""},"paragraphs":["Administrative Jurisdiction.","– The administrative jurisdiction on any violation of the provisions of this Act shall be vested in either the CSC, or the Office of the Ombudsman as determined by appropriate laws and issuances.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A24","no":24,"noLabel":{"en":"Sec. 25."},"text":{"en":"Sec. 25. Immunity, Discharge of Co-Respondent/Accused to be a Witness. – Any public official or employee or any person having been charged with another offense under this Act and who voluntarily gives information pertaining to an investigation or who willingly testifies therefore, shall be exempt from prosecution in the case/s where his/her information and testimony are given. The discharge may be granted and directed by the investigating body or court upon the application or petition of any of the respondent/accused-informant and before the termination of the investigation: Provided, That: \"(a) There is absolute necessity for the testimony of the respondent/accused-informant whose discharge is requested; \"(b) There is no other direct evidence available for the proper prosecution of the offense committed, except the testimony of said respondent/accused-informant; \"(c) The testimony of said respondent can be substantially corroborated in its material points; \"(d) The respondent/accused-informant has not been previously convicted of a crime involving moral turpitude; and \"(e) Said respondent/accused-informant does not appear to be the most guilty. \"Evidence adduced in support of the discharge shall automatically form part of the records of the investigation. Should the investigating body or court deny the motion or request for discharge as a witness, his/her sworn statement shall be inadmissible as evidence.\""},"paragraphs":["Immunity, Discharge of Co-Respondent/Accused to be a Witness.","– Any public official or employee or any person having been charged with another offense under this Act and who voluntarily gives information pertaining to an investigation or who willingly testifies therefore, shall be exempt from prosecution in the case/s where his/her information and testimony are given. The discharge may be granted and directed by the investigating body or court upon the application or petition of any of the respondent/accused-informant and before the termination of the investigation:","Provided,","That: \"(a) There is absolute necessity for the testimony of the respondent/accused-informant whose discharge is requested; \"(b) There is no other direct evidence available for the proper prosecution of the offense committed, except the testimony of said respondent/accused-informant; \"(c) The testimony of said respondent can be substantially corroborated in its material points; \"(d) The respondent/accused-informant has not been previously convicted of a crime involving moral turpitude; and \"(e) Said respondent/accused-informant does not appear to be the most guilty. \"Evidence adduced in support of the discharge shall automatically form part of the records of the investigation. Should the investigating body or court deny the motion or request for discharge as a witness, his/her sworn statement shall be inadmissible as evidence.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A25","no":25,"noLabel":{"en":"Sec. 26."},"text":{"en":"Sec. 26. Transition from Manual to Software-Enabled Business-Related Transactions."},"paragraphs":["Transition from Manual to Software-Enabled Business-Related Transactions."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A26","no":26,"noLabel":{"en":"Sec. 27."},"text":{"en":"Sec. 27. Transitory Provisions. – \"(a) The Director General of the Authority, in consultation with the DTI, shall determine the organizational structure and personnel complement of the Authority.1âwphi1 To ensure continued implementation of ease of doing business and anti-red tape reforms, the teams or units involved in regulatory improvement and/or ease of doing business-related programs of the DTI-Competitiveness Bureau shall serve as temporary secretariat of the Authority until such time that its organizational structure and personnel complement have been determined and filled up: Provided,"},"paragraphs":["Transitory Provisions.","– \"(a) The Director General of the Authority, in consultation with the DTI, shall determine the organizational structure and personnel complement of the Authority.1âwphi1 To ensure continued implementation of ease of doing business and anti-red tape reforms, the teams or units involved in regulatory improvement and/or ease of doing business-related programs of the DTI-Competitiveness Bureau shall serve as temporary secretariat of the Authority until such time that its organizational structure and personnel complement have been determined and filled up:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A27","no":27,"noLabel":{"en":"Sec. 28."},"text":{"en":"Sec. 28. Congressional Oversight Committee. – To monitor the implementation of this Act, there shall be created a Congressional Oversight Committee on Ease of Doing Business (COC-EODB), to be composed of five (5) members from the Senate, which shall include the Chairpersons of the Senate Committees on Trade and Commerce and Entrepreneurship, Civil Service, Government Reorganization and Professional Regulation, and Economic Affairs; and five (5) members from the House of Representatives which shall include the Chairpersons of the House Committees on Trade and Industry, Civil Service and Professional Regulation, Government Reorganization, and Economic Affairs. The COC-EODB shall be jointly chaired by the Chairpersons of the Senate Committee on Trade and Commerce and Entrepreneurship and the House of Representatives Committee on Trade and Industry: Provided,"},"paragraphs":["Congressional Oversight Committee.","– To monitor the implementation of this Act, there shall be created a Congressional Oversight Committee on Ease of Doing Business (COC-EODB), to be composed of five (5) members from the Senate, which shall include the Chairpersons of the Senate Committees on Trade and Commerce and Entrepreneurship, Civil Service, Government Reorganization and Professional Regulation, and Economic Affairs; and five (5) members from the House of Representatives which shall include the Chairpersons of the House Committees on Trade and Industry, Civil Service and Professional Regulation, Government Reorganization, and Economic Affairs. The COC-EODB shall be jointly chaired by the Chairpersons of the Senate Committee on Trade and Commerce and Entrepreneurship and the House of Representatives Committee on Trade and Industry:","Provided,"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A28","no":28,"noLabel":{"en":"Sec. 29."},"text":{"en":"Sec. 29. Appropriations."},"paragraphs":["Appropriations."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A29","no":29,"noLabel":{"en":"Sec. 30."},"text":{"en":"Sec. 30. Implementing Rules and Regulations."},"paragraphs":["Implementing Rules and Regulations."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A30","no":30,"noLabel":{"en":"Sec. 31."},"text":{"en":"Sec. 31. Separability Clause."},"paragraphs":["Separability Clause."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A31","no":31,"noLabel":{"en":"Sec. 32."},"text":{"en":"Sec. 32. Repealing Clause."},"paragraphs":["Repealing Clause."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A32","no":32,"noLabel":{"en":"Sec. 33."},"text":{"en":"Sec. 33. Effectivity. – This Act shall take effect within fifteen (15) days following its publication in the Official Gazette or in two (2) national newspapers of general circulation.\""},"paragraphs":["Effectivity.","– This Act shall take effect within fifteen (15) days following its publication in the","Official Gazette","or in two (2) national newspapers of general circulation.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},{"id":"PH-EODB-2018-A33","no":33,"noLabel":{"en":"Section 18."},"text":{"en":"Section 18. Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in two (2) newspapers of general circulation."},"paragraphs":["Effectivity.","– This Act shall take effect fifteen (15) days after its publication in the","Official Gazette","or in two (2) newspapers of general circulation. Approved,","PANTALEON D. ALVAREZ","Speaker of the Houseof Representatives","AQUILINO \"KOKO\" PIMENTEL III","President of the Senate This Act which is a consolidation of Senate Bill No. 1311 and House Bill No. 6579 was finally passed by the Senate and the House of Representatives on February 21, 2018 and February 27, 2018, respectively.","CESAR STRAIT PAREJA","Secretary GeneralHouse of Representatives","LUTGARDO B. BARBO","Secretary of the Senate Approved: May 28, 2018","RODRIGO ROA DUTERTE","President of the Philippines The Lawphil Project - Arellano Law Foundation"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"}],"pack":"ph-2","fulltextMeta":{"country":"PH","level":"law","status":"active","topics":["investment"],"title":{"zh":"营商便利与高效政府服务提供法","en":"Ease of Doing Business and Efficient Government Service Delivery Act of 2018"},"docNumber":"Republic Act No. 11032","issuingBody":{"zh":"菲律宾国会","en":"Congress of the Philippines"},"promulgatedDate":"2018-05-28","effectiveDate":"2018-07-27","coverage":"full","source":{"name":"The Lawphil Project — Arellano Law Foundation","url":"https://lawphil.net/statutes/repacts/ra2018/ra_11032_2018.html"},"summary":{"zh":"修订反繁文缛节法（R.A. 9485），规定“营商便利”与政府服务时限、反红线窗口等制度。","en":"An act promoting ease of doing business and efficient delivery of government services."}},"summary":{"zh":"修订反繁文缛节法（R.A. 9485），规定“营商便利”与政府服务时限、反红线窗口等制度。","en":"An act promoting ease of doing business and efficient delivery of government services."}};
  FT["PH-MSME-2008"] = {"id":"PH-MSME-2008","coverage":"full","language":"en","sourceName":"The Lawphil Project — Arellano Law Foundation","sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html","fetchedAt":"2026-10-02","articleCount":24,"title":{"zh":"中小企业大宪章（经修订）","en":"Magna Carta for Micro, Small and Medium Enterprises","orig":"Magna Carta for Micro, Small and Medium Enterprises","vi":"Đại hiến chương về Doanh nghiệp Siêu nhỏ, Nhỏ và Vừa","th":"มหากฎบัตรเพื่อวิสาหกิจขนาดย่อม ขนาดเล็ก และขนาดกลาง","id":"Piagam Magna untuk Usaha Mikro, Kecil, dan Menengah","ms":"Piagam Magna untuk Perusahaan Mikro, Kecil dan Sederhana"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 9501","issuingBody":"菲律宾国会","promulgatedDate":"2008-05-23","effectiveDate":"2008-06-07","completenessNote":"官方页面所载为修订型法条（R.A. 9501 全文），以 “SECTION 1–24” 或 “SEC. 1–24” 逐条列出；本库照官方条号全文收录 24 条，条内引述的被修正法条文照录，未增删。","country":"PH","countryName":"菲律宾","layer":"fulltext","articles":[{"id":"PH-MSME-2008-A1","no":1,"noLabel":{"en":"SECTION 1."},"text":{"en":"SECTION 1. Title. - This Act shall be known as the \" Magna Carta for Micro, Small and Medium Enterprises (MSMEs) \"."},"paragraphs":["Title.","- This Act shall be known as the \"","Magna Carta for Micro, Small and Medium Enterprises (MSMEs)","\"."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A2","no":2,"noLabel":{"en":"SEC. 2."},"text":{"en":"SEC. 2. Declaration of Policy. - Recognizing that MSMEs have the potential for more employment generation and economic growth and therefore can help provide a self-sufficient industrial foundation for the country, it is hereby declared the policy of the State to promote, support,, strengthen and encourage the growth and development of MSMEs in all productive sectors of the economy particularly rural/agri-based enterprises. To this end, the State shall recognize the specific needs of the MSMEs and shall recognize the specific needs of the MSMEs and shall undertake to promote entrepreneurship, support entrepreneurs, encourage the establishments of MSMEs and ensure their continuing viability and growth and thereby attain countryside industrialization by: \"a) intersifying and expanding programs for training in entrepreneurship and for skills development for labor; \"b) facilitating their access to sources of funds; \"c) assuring to them access to a fair share of governments contracts and related incentives and preferences; \"d) complementing and supplementing financing programs for MSMEs and doing away with stringent and burdensome collateral requirements that small entrepreneurs invariably find extreme difficulty complying with; \"e) instituting safeguards for the protection and stability of the credit delivery system; \"f) raising government efficiency and effectiveness in providing assistance to MSMEs throughout the country, at the least cost; \"g) promoting linkages between large and small enterprises, and by encouraging the establishments of common service facilities; \"h) making the private sector a partner in the task of building up MSMEs through the promotion and participation of private voluntary organizations viable industry associations, and cooperatives; and \"i) assuring a balance and sustainable development through the establishment of a feedback and evaluation mechanism that will monitor the economic contributions as well as bottlenecks and environmental effects of the development of MSMEs.\""},"paragraphs":["Declaration of Policy.","- Recognizing that MSMEs have the potential for more employment generation and economic growth and therefore can help provide a self-sufficient industrial foundation for the country, it is hereby declared the policy of the State to promote, support,, strengthen and encourage the growth and development of MSMEs in all productive sectors of the economy particularly rural/agri-based enterprises. To this end, the State shall recognize the specific needs of the MSMEs and shall recognize the specific needs of the MSMEs and shall undertake to promote entrepreneurship, support entrepreneurs, encourage the establishments of MSMEs and ensure their continuing viability and growth and thereby attain countryside industrialization by: \"a) intersifying and expanding programs for training in entrepreneurship and for skills development for labor; \"b) facilitating their access to sources of funds; \"c) assuring to them access to a fair share of governments contracts and related incentives and preferences; \"d) complementing and supplementing financing programs for MSMEs and doing away with stringent and burdensome collateral requirements that small entrepreneurs invariably find extreme difficulty complying with; \"e) instituting safeguards for the protection and stability of the credit delivery system; \"f) raising government efficiency and effectiveness in providing assistance to MSMEs throughout the country, at the least cost; \"g) promoting linkages between large and small enterprises, and by encouraging the establishments of common service facilities; \"h) making the private sector a partner in the task of building up MSMEs through the promotion and participation of private voluntary organizations viable industry associations, and cooperatives; and \"i) assuring a balance and sustainable development through the establishment of a feedback and evaluation mechanism that will monitor the economic contributions as well as bottlenecks and environmental effects of the development of MSMEs.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A3","no":3,"noLabel":{"en":"SEC. 3."},"text":{"en":"SEC. 3. Micro, Small and Medium Enterprises (MSMEs) as Beneficiaries."},"paragraphs":["Micro, Small and Medium Enterprises (MSMEs) as Beneficiaries."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A4","no":4,"noLabel":{"en":"SEC. 4."},"text":{"en":"SEC. 4. Eligibility for Government Assistance. - To qualify for assistance, counseling, incentives and promotion under this Act, businesses falling under the above definition must be: \"a) duly registered with the appropriate agencies as presently provided by law: Provided, That in the case of micro enterprises as defined herein, registration with the office of the municipal or city treasurer shall be deemed sufficient compliance with this requirement; \"b) one hundred percent (100%) owned, capitalized by Filipino citizens, whether single proprietorship or partnership. If the enterprise is a juridical entity, at least sixty percent (60%) of its capital or outstanding stock must be owned by Filipino citizens; \"c) a business activity within the major sectors of the economy, namely; industry, trade, services, including the practice of one's profession, the operation of tourism-related establishments, and agri-business, which for purposes of this Act refers to any business activity involving the manufacturing, processing, and/or production of agricultural produce; and \"d) it must not be a branch, subsidiary or division of a large scale enterprise. \"However, this requirement shall not preclude MSMEs from accepting subcontracts and entering into franchise partnership with large enterprises or from joining in cooperative activities with other MSMEs. \"Program of the Small Business Corporation (SB Corporation) as provided in subsequent provisions of this Act shall be exclusively delivered and directed to bonafide MSMEs. \"Any MSME, its directors, officers or agents, found to have committed fraud or misrepresentation for the purpose of availing the benefits under this Act shall be immediately disqualified as a beneficiary, without prejudice to any administrative, criminal or civil liability under existing laws. \"Eligible MSMEs shall be entitled to a share of at least ten percent (10%) of total procurement value of goods and services supplied to the Government, its bureaus, offices and agencies annually. \"The Department of Budget and Management shall monitor the compliance of government agencies on the required procurement for MSMEs and submit its report to the MSMED Council on a semestral basis and to the Congress of the Philippines, through its appropriate committees on a yearly basis.\""},"paragraphs":["Eligibility for Government Assistance.","- To qualify for assistance, counseling, incentives and promotion under this Act, businesses falling under the above definition must be: \"a) duly registered with the appropriate agencies as presently provided by law: Provided, That in the case of micro enterprises as defined herein, registration with the office of the municipal or city treasurer shall be deemed sufficient compliance with this requirement; \"b) one hundred percent (100%) owned, capitalized by Filipino citizens, whether single proprietorship or partnership. If the enterprise is a juridical entity, at least sixty percent (60%) of its capital or outstanding stock must be owned by Filipino citizens; \"c) a business activity within the major sectors of the economy, namely; industry, trade, services, including the practice of one's profession, the operation of tourism-related establishments, and agri-business, which for purposes of this Act refers to any business activity involving the manufacturing, processing, and/or production of agricultural produce; and \"d) it must not be a branch, subsidiary or division of a large scale enterprise. \"However, this requirement shall not preclude MSMEs from accepting subcontracts and entering into franchise partnership with large enterprises or from joining in cooperative activities with other MSMEs. \"Program of the Small Business Corporation (SB Corporation) as provided in subsequent provisions of this Act shall be exclusively delivered and directed to bonafide MSMEs. \"Any MSME, its directors, officers or agents, found to have committed fraud or misrepresentation for the purpose of availing the benefits under this Act shall be immediately disqualified as a beneficiary, without prejudice to any administrative, criminal or civil liability under existing laws. \"Eligible MSMEs shall be entitled to a share of at least ten percent (10%) of total procurement value of goods and services supplied to the Government, its bureaus, offices and agencies annually. \"The Department of Budget and Management shall monitor the compliance of government agencies on the required procurement for MSMEs and submit its report to the MSMED Council on a semestral basis and to the Congress of the Philippines, through its appropriate committees on a yearly basis.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A5","no":5,"noLabel":{"en":"SEC. 5."},"text":{"en":"SEC. 5. Guiding Principles. - To set the pace for MSME development, the State shall be guided by the following principles: \"x x x \"c) Coordination of government efforts. Government efforts shall be coordinated to achieve coherence in objectives. All appropriate offices, particularly those under the Departments of Trade and Industry, Finance, Budget and Management, Agriculture, Agrarian Reform, Environment and Natural Resources, Labor and Employment, Transportation and Communications, Public Works and Highways, Science and Technology, Interior and Local Government and Tourism as well as the National Economic and Development Authority, Philippine Information Agency and the Bangko Sentral ng Pilipinas, through their national, regional and provincial offices shall, to the best of their efforts and in coordination with local government units, provide the necessary support and assistance to MSMEs. x x x.\""},"paragraphs":["Guiding Principles.","- To set the pace for MSME development, the State shall be guided by the following principles: \"x x x \"c) Coordination of government efforts. Government efforts shall be coordinated to achieve coherence in objectives. All appropriate offices, particularly those under the Departments of Trade and Industry, Finance, Budget and Management, Agriculture, Agrarian Reform, Environment and Natural Resources, Labor and Employment, Transportation and Communications, Public Works and Highways, Science and Technology, Interior and Local Government and Tourism as well as the National Economic and Development Authority, Philippine Information Agency and the Bangko Sentral ng Pilipinas, through their national, regional and provincial offices shall, to the best of their efforts and in coordination with local government units, provide the necessary support and assistance to MSMEs. x x x.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A6","no":6,"noLabel":{"en":"SEC. 6."},"text":{"en":"SEC. 6. Micro, Small and Medium Enterprises Development Plan (MSMEDP). - The President shall approve a six-year micro, small and medium enterprises development plan prepared by the Department of Trade and Industry (DTI) which shall form part of the Medium Term Philippine Development Plan (MTPDP). It shall be formulated in consultation with the private sector, validated and updated semestrally. Such plan shall include a component on a micro credit financing scheme.\""},"paragraphs":["Micro, Small and Medium Enterprises Development Plan (MSMEDP).","- The President shall approve a six-year micro, small and medium enterprises development plan prepared by the Department of Trade and Industry (DTI) which shall form part of the Medium Term Philippine Development Plan (MTPDP). It shall be formulated in consultation with the private sector, validated and updated semestrally. Such plan shall include a component on a micro credit financing scheme.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A7","no":7,"noLabel":{"en":"SEC. 7."},"text":{"en":"SEC. 7. Micro, Small and Medium Enterprise Development (MSMED) Council. - The existing Small and Medium Enterprise Development Council, which was created by Republic Act No. 6977, as amended by Republic Act No. 6977, as amended by Republic Act No. 8289, shall be strengthened to effectively spur the growth and development of MSMEs throughout the country, and to carry out the policy declared in this Act and shall now be known as the Micro, Small and Medium Enterprise development (MSMED) Council. The Council shall be attached to the Department of Trade and Industry and shall be constituted within sixty (60) days after the approval of this Act.\" \"x x x.\""},"paragraphs":["Micro, Small and Medium Enterprise Development (MSMED) Council.","- The existing Small and Medium Enterprise Development Council, which was created by Republic Act No. 6977, as amended by Republic Act No. 6977, as amended by Republic Act No. 8289, shall be strengthened to effectively spur the growth and development of MSMEs throughout the country, and to carry out the policy declared in this Act and shall now be known as the Micro, Small and Medium Enterprise development (MSMED) Council. The Council shall be attached to the Department of Trade and Industry and shall be constituted within sixty (60) days after the approval of this Act.\" \"x x x.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A8","no":8,"noLabel":{"en":"SEC. 7-A."},"text":{"en":"SEC. 7-A. Composition. - The Council shall be headed by the Secretary of Trade and Industry as Chairman, and may elect from among themselves a Vice-chairman to preside over the Council meetings in the absence of the Chairman. The members shall be the following: \"a) Secretary of Agriculture; \"b) Secretary of the Interior and Local Government; \"c) Secretary of Science and Technology; \"d) Secretary of Tourism; \"e) Chairman of Small Business Corporation; \"f) Three (3) representatives from the MSME sector to represent Luzon, Visayas and Mindanao; \"g) One representative from the labor sector, to be nominated by accredited labor groups; and \"h) A representative from the private banking sector; to serve alternately among the Chamber of Thrift Banks; the Rural Bankers' Association of the Philippines (RBAP); and the Bankers&acirc;€™ Association of the Philippines (BAP). \"All members of the Council so appointed, except from the ex officio members, shall serve for a term of three (3) years. The person so appointed to replace a member who has resigned, died, or been removed for cause shall serve only for the unexpired portion of the term. \"The private sector members of the Council shall receive per diem of Two thousand pesos (P2,000) per meeting, for a maximum of twenty-four (24) meetings per year, which per diem may be adjusted by the MSMED Council as appropriate. \"The Council may call upon the participation of any national or local government agency, association of local government officials or private sector organization in its deliberations especially when such agency or private sector or organization in its deliberations especially when such agency or private sector organizations directly or indirectly concerned with and/or affecting the growth and development of MSMEs in any particular area or manner. \"The Council may create an Executive Committee of five (5) members elected by the Council from among themselves or their designated permanent representatives, with at least two (2) members representing the private sector, and with authority to act for and on behalf of the Council during intervals of council meetings, and within the specific authority granted by the Council.\""},"paragraphs":["Composition.","- The Council shall be headed by the Secretary of Trade and Industry as Chairman, and may elect from among themselves a Vice-chairman to preside over the Council meetings in the absence of the Chairman. The members shall be the following: \"a) Secretary of Agriculture; \"b) Secretary of the Interior and Local Government; \"c) Secretary of Science and Technology; \"d) Secretary of Tourism; \"e) Chairman of Small Business Corporation; \"f) Three (3) representatives from the MSME sector to represent Luzon, Visayas and Mindanao; \"g) One representative from the labor sector, to be nominated by accredited labor groups; and \"h) A representative from the private banking sector; to serve alternately among the Chamber of Thrift Banks; the Rural Bankers' Association of the Philippines (RBAP); and the Bankers&acirc;€™ Association of the Philippines (BAP). \"All members of the Council so appointed, except from the ex officio members, shall serve for a term of three (3) years. The person so appointed to replace a member who has resigned, died, or been removed for cause shall serve only for the unexpired portion of the term. \"The private sector members of the Council shall receive per diem of Two thousand pesos (P2,000) per meeting, for a maximum of twenty-four (24) meetings per year, which per diem may be adjusted by the MSMED Council as appropriate. \"The Council may call upon the participation of any national or local government agency, association of local government officials or private sector organization in its deliberations especially when such agency or private sector or organization in its deliberations especially when such agency or private sector organizations directly or indirectly concerned with and/or affecting the growth and development of MSMEs in any particular area or manner. \"The Council may create an Executive Committee of five (5) members elected by the Council from among themselves or their designated permanent representatives, with at least two (2) members representing the private sector, and with authority to act for and on behalf of the Council during intervals of council meetings, and within the specific authority granted by the Council.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A9","no":9,"noLabel":{"en":"SEC. 9."},"text":{"en":"SEC. 9. Section 8 of the same Act, as amended, is hereby renumbered as Section 7-B and further amended to read as follows: \"SEC. 7-B Power and Functions. - The MSMED Council shall have the following powers, duties and functions: \"a) To help establish the needed environment and opportunities conducive to the growth and development of the MSME sector; \"b) To recommend to the President and the Congress all policy matters affecting MSMEs; \"c) To coordinate and integrate various government and private sector activities relating to MSME development; \"d) To review existing policies of government agencies that would affect the growth and development of MSMEs and recommend changes to the President and Congress through the Committee on Economic Affairs of the Senate and the Committee on Small Business and Entrepreneurship Development of the House of Representatives. whenever deemed necessary. This shall include efforts to simplify rules and regulations, as well as review of the applicability in the registration, financing, and other activities relevant to MSMEs the result shall be included in the annual report to be submitted to Congress; \"e) To monitor and determine the progress of various agencies geared towards the development of the sector. This shall include overseeing, in coordination with local government units and the Department of Interior and Local Government as well as private sector groups/association, the development among MSMEs; \"g) To provide the appropriate policy and coordinative framework in assisting relevant government agencies, in coordination with the NEDA and the Coordinating Council for the Philippine Assistance Program, as may be necessary, in the tapping of local and foreign fund's for MSME development; \"h) To promote the productivity and viability of MSMEs by way of directing and/or assisting relevant government agencies and institutional at the national, regional and provincial level towards the: \"1) Provision of business training courses, technical training for technicians and skilled laborers and continuing skills upgrading programs; \"2) Provision of labor-management guidance, assistance and improvement of the working conditions of employees in MSMEs; \"3) Provision of guidance and assistance regarding product quality/product development and product diversification; \"4) Provision of guidance and assistance for the adoption of improved production technique and commercialization of appropriate technologies for the product development and for increased utilization of indigenous raw materials; \"5) Provision of assistance in marketing and distribution of products of MSMEs through local supply-demand information, industry and provincial profiles, overseas marketing promotion, domestic market linkaging and the establishment of common service facilities such as common and/or cooperative bonded warehouse, grains storage, agro-processing and drying facilities, ice plants, refrigerated storage, cooperative trucking facilities, etc; \"6) Intensification of assistance and guidance to enable greater access to credit through a simplified multi-agency financing program; to encourage development of other modes of financing such as leasing and venture capital activities; to provide effective credit guarantee systems, and encourage the formation of credit guarantee associations, including setting up credit records and information systems and to decentralize loan approval mechanism; \"7) Provision of concessional interest rates, lower financing fees, which may include incentives for prompt credit payments, arrangements tying amortizations to business cash flows, effective substitution of government guarantee cover on loans for the borrower's lack of collateral; \"8) Provision of bankruptcy preventive measures through the setting up of a mutual relief system for distressed enterprises, and the establishment of measures such as insurance against extraordinary disasters; \"9) Intensification of information dissemination campaigns and entrepreneurship education activities; \"10) Availment of and easier access to tax credits and other tax and duty incentives as provided by the Omnibus Investment Code and other laws; \"11) Provision of support for product experimentation and research and development activities as well as access to information on commercialized technologies; and \"12) Through appropriate government agencies: \"a) Provide more infrastracture facilities and public utilities to support operations of MSMEs; \"b) Establish, operate, and administer a small business incubation program in coordination with academic institutions, Department of Science and Technology and other appropriate government entities that will provide space for start-up and expanding firms, shared use of equipment and work areas, daily management support services essential to high-quality commercial operations, technical assistance and other services to develop innovative and deserving MSMEs; \"d) Provide local and international network and linkages for MSME development; \"e) Compile and integrate statistical databank on Philippine MSMEs; \"f) Sept-up new MSME centers and revitalize already established MSME centers to provide MSMEs in the regions easier access to services such as, but not limited to, the following: \"i. Accept and act on all registration application of MSMEs; \"ii. Streamline registration process and facilitate speedy registration for the establishment of business enterprises in the country; \"iii. Provide all information and referral services it shall deem necessary or essential to the development and promotion of MSMEs; \"iv. Conduct other programs and development programs, training, advice, consultation on business conceptualization and feasibility, financing, management, capacity building, human resources, marketing, and such other services to support the needs of MSMEs; \"v. Provide courses and development programs, training, advice, consultation on business conceptualization and feasibility, financing, management, and such other services to support the needs of MSMEs; \"g) To submit to the President and the Congress through the OVERSIGHT Committee as defined under this Act, a yearly report on the status of MSMEs in the country, including the progress and impact of all relevant government policies, programs and legislation as well as private sector activities; \"h) To coordinate, monitor and assess the implementation of the MSMEDP, and when necessary, institute appropriate adjustments thereon in the light of changing conditions in both domestic and international environment; and \"i) Generally, to exercise all powers and functions necessary for the objectives and purposes of this Act.\""},"paragraphs":["Section 8 of the same Act, as amended, is hereby renumbered as Section 7-B and further amended to read as follows: \"SEC. 7-B","Power and Functions.","- The MSMED Council shall have the following powers, duties and functions: \"a) To help establish the needed environment and opportunities conducive to the growth and development of the MSME sector; \"b) To recommend to the President and the Congress all policy matters affecting MSMEs; \"c) To coordinate and integrate various government and private sector activities relating to MSME development; \"d) To review existing policies of government agencies that would affect the growth and development of MSMEs and recommend changes to the President and Congress through the Committee on Economic Affairs of the Senate and the Committee on Small Business and Entrepreneurship Development of the House of Representatives. whenever deemed necessary. This shall include efforts to simplify rules and regulations, as well as review of the applicability in the registration, financing, and other activities relevant to MSMEs the result shall be included in the annual report to be submitted to Congress; \"e) To monitor and determine the progress of various agencies geared towards the development of the sector. This shall include overseeing, in coordination with local government units and the Department of Interior and Local Government as well as private sector groups/association, the development among MSMEs; \"g) To provide the appropriate policy and coordinative framework in assisting relevant government agencies, in coordination with the NEDA and the Coordinating Council for the Philippine Assistance Program, as may be necessary, in the tapping of local and foreign fund's for MSME development; \"h) To promote the productivity and viability of MSMEs by way of directing and/or assisting relevant government agencies and institutional at the national, regional and provincial level towards the: \"1) Provision of business training courses, technical training for technicians and skilled laborers and continuing skills upgrading programs; \"2) Provision of labor-management guidance, assistance and improvement of the working conditions of employees in MSMEs; \"3) Provision of guidance and assistance regarding product quality/product development and product diversification; \"4) Provision of guidance and assistance for the adoption of improved production technique and commercialization of appropriate technologies for the product development and for increased utilization of indigenous raw materials; \"5) Provision of assistance in marketing and distribution of products of MSMEs through local supply-demand information, industry and provincial profiles, overseas marketing promotion, domestic market linkaging and the establishment of common service facilities such as common and/or cooperative bonded warehouse, grains storage, agro-processing and drying facilities, ice plants, refrigerated storage, cooperative trucking facilities, etc; \"6) Intensification of assistance and guidance to enable greater access to credit through a simplified multi-agency financing program; to encourage development of other modes of financing such as leasing and venture capital activities; to provide effective credit guarantee systems, and encourage the formation of credit guarantee associations, including setting up credit records and information systems and to decentralize loan approval mechanism; \"7) Provision of concessional interest rates, lower financing fees, which may include incentives for prompt credit payments, arrangements tying amortizations to business cash flows, effective substitution of government guarantee cover on loans for the borrower's lack of collateral; \"8) Provision of bankruptcy preventive measures through the setting up of a mutual relief system for distressed enterprises, and the establishment of measures such as insurance against extraordinary disasters; \"9) Intensification of information dissemination campaigns and entrepreneurship education activities; \"10) Availment of and easier access to tax credits and other tax and duty incentives as provided by the Omnibus Investment Code and other laws; \"11) Provision of support for product experimentation and research and development activities as well as access to information on commercialized technologies; and \"12) Through appropriate government agencies: \"a) Provide more infrastracture facilities and public utilities to support operations of MSMEs; \"b) Establish, operate, and administer a small business incubation program in coordination with academic institutions, Department of Science and Technology and other appropriate government entities that will provide space for start-up and expanding firms, shared use of equipment and work areas, daily management support services essential to high-quality commercial operations, technical assistance and other services to develop innovative and deserving MSMEs; \"d) Provide local and international network and linkages for MSME development; \"e) Compile and integrate statistical databank on Philippine MSMEs; \"f) Sept-up new MSME centers and revitalize already established MSME centers to provide MSMEs in the regions easier access to services such as, but not limited to, the following: \"i. Accept and act on all registration application of MSMEs; \"ii. Streamline registration process and facilitate speedy registration for the establishment of business enterprises in the country; \"iii. Provide all information and referral services it shall deem necessary or essential to the development and promotion of MSMEs; \"iv. Conduct other programs and development programs, training, advice, consultation on business conceptualization and feasibility, financing, management, capacity building, human resources, marketing, and such other services to support the needs of MSMEs; \"v. Provide courses and development programs, training, advice, consultation on business conceptualization and feasibility, financing, management, and such other services to support the needs of MSMEs; \"g) To submit to the President and the Congress through the OVERSIGHT Committee as defined under this Act, a yearly report on the status of MSMEs in the country, including the progress and impact of all relevant government policies, programs and legislation as well as private sector activities; \"h) To coordinate, monitor and assess the implementation of the MSMEDP, and when necessary, institute appropriate adjustments thereon in the light of changing conditions in both domestic and international environment; and \"i) Generally, to exercise all powers and functions necessary for the objectives and purposes of this Act.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A10","no":10,"noLabel":{"en":"SEC. 8."},"text":{"en":"SEC. 8. Designation of the Bureau of Micro, Small and Medium Enterprise Development as Council Secretariat. - The Bureau of Small and Medium Business Development (BSMBD) hereinafter referred to as the Bureau of Micro, Small and Medium Enterprise Development (BMSMED) is hereby designated to act as the Council Secretariat and shall have the following duties and functions: \"x x x\""},"paragraphs":["Designation of the Bureau of Micro, Small and Medium Enterprise Development as Council Secretariat.","- The Bureau of Small and Medium Business Development (BSMBD) hereinafter referred to as the Bureau of Micro, Small and Medium Enterprise Development (BMSMED) is hereby designated to act as the Council Secretariat and shall have the following duties and functions: \"x x x\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A11","no":11,"noLabel":{"en":"SEC. 9."},"text":{"en":"SEC. 9. Appropriations. - to finance its activities and operational expenses, the Council shall have a separate annual appropriation approved by the Department of Trade and Industry (DTI) which shall be provided in the General Appropriation Act starting in the fiscal year immediately following the approval of this Act. The Council may also accept contributions from the private sector.\""},"paragraphs":["Appropriations.","- to finance its activities and operational expenses, the Council shall have a separate annual appropriation approved by the Department of Trade and Industry (DTI) which shall be provided in the General Appropriation Act starting in the fiscal year immediately following the approval of this Act. The Council may also accept contributions from the private sector.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A12","no":12,"noLabel":{"en":"SEC. 10."},"text":{"en":"SEC. 10. Rationalization of Existing MSME Programs and Agencies. - The MSMED Council shall conduct continuing review of government programs for MSMEs and submit to Congress and the President a report thereon together with its policy recommendation.\""},"paragraphs":["Rationalization of Existing MSME Programs and Agencies.","- The MSMED Council shall conduct continuing review of government programs for MSMEs and submit to Congress and the President a report thereon together with its policy recommendation.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A13","no":13,"noLabel":{"en":"SEC. 11."},"text":{"en":"SEC. 11. Creation of Small Business Guarantee and Finance Corporation. - There is hereby created a body corporate to be known as the Small Business Guarantee and Finance Corporation, hereinafter referred to as the Small Business Corporation (SB Corporation), which shall be charged with the primary responsibility of implementing comprehensive policies and programs to assist MSMEs in all areas, including but not limited to finance and information services, training and marketing.\" SEC. 11. Composition of the Board of Directors and its Powers. - The SB Corporation corporate powers shall be vested on a Board of Directors composed of eleven (11) members which shall include the following: \"a) The Secretary of Trade and Industry; \"b) The Secretary of Finance; \"c) A private sector representative to be appointed by the President upon the recommendation of the MSMED Council; \"d) Seven (7) representatives of the SB Corporation common stock shareholders who shall be elected based on proportional distribution, in accordance with Section 24 of the Corporation Code; and \"e) The president of the SB Corporation as ex-officio member and to serve as vice chairman of the Board. \"The President shall appoint the chairman of the Board from among its members. \"All members of the Board so appointed, except for the ex-officio members, shall serve for a term of three (3) without reappointment. The person so appointed to replace a member who has resigned, died, or been removed for cause shall serve only for the unexpired portion of the term. \"The Board of Directors shall have, among others, the following specific powers and authorities: \"a) Formulate policies necessary to carry out effectively the provisions of this charter and to prescribe, amend and repeal by-laws, rules and regulations for the effective operations of the small business corporation; \"b) Establish such branches, agencies and subsidiaries as may be deemed necessary and convenient; \"c) Compromise or release, in whole or in part, any claim or liability whatsoever for or against the SB Corporation, including interest, penalties, fees and/or charges in accordance to its own by-laws and Bangko Sentral ng Pilipinas rules; \"d) Fix the features on non-voting preferred shares which shall be printed on the stock certificates evidencing the same; \"e) Exercise all such other powers as may be necessary or incidental to carry out the SB Corporation's purposes; and \"f) Notwithstanding the provisions of Republic Act No. 6758 and Compensation Circular No, 10, Series of 1989 issued by the Department of Budget and Management, the Board shall have the authority to provide for the organizational structure and staffing pattern of SB Corporation and to extend to the employees and personal thereof salaries, allowances and fringe benefits similar to those extended to and currently enjoyed by employees and personal of other financial institutions.\""},"paragraphs":["Creation of Small Business Guarantee and Finance Corporation.","- There is hereby created a body corporate to be known as the Small Business Guarantee and Finance Corporation, hereinafter referred to as the Small Business Corporation (SB Corporation), which shall be charged with the primary responsibility of implementing comprehensive policies and programs to assist MSMEs in all areas, including but not limited to finance and information services, training and marketing.\"","SEC. 11. Composition of the Board of Directors and its Powers. - The SB Corporation corporate powers shall be vested on a Board of Directors composed of eleven (11) members which shall include the following: \"a) The Secretary of Trade and Industry; \"b) The Secretary of Finance; \"c) A private sector representative to be appointed by the President upon the recommendation of the MSMED Council; \"d) Seven (7) representatives of the SB Corporation common stock shareholders who shall be elected based on proportional distribution, in accordance with Section 24 of the Corporation Code; and \"e) The president of the SB Corporation as ex-officio member and to serve as vice chairman of the Board. \"The President shall appoint the chairman of the Board from among its members. \"All members of the Board so appointed, except for the ex-officio members, shall serve for a term of three (3) without reappointment. The person so appointed to replace a member who has resigned, died, or been removed for cause shall serve only for the unexpired portion of the term. \"The Board of Directors shall have, among others, the following specific powers and authorities: \"a) Formulate policies necessary to carry out effectively the provisions of this charter and to prescribe, amend and repeal by-laws, rules and regulations for the effective operations of the small business corporation; \"b) Establish such branches, agencies and subsidiaries as may be deemed necessary and convenient; \"c) Compromise or release, in whole or in part, any claim or liability whatsoever for or against the SB Corporation, including interest, penalties, fees and/or charges in accordance to its own by-laws and Bangko Sentral ng Pilipinas rules; \"d) Fix the features on non-voting preferred shares which shall be printed on the stock certificates evidencing the same; \"e) Exercise all such other powers as may be necessary or incidental to carry out the SB Corporation's purposes; and \"f) Notwithstanding the provisions of Republic Act No. 6758 and Compensation Circular No, 10, Series of 1989 issued by the Department of Budget and Management, the Board shall have the authority to provide for the organizational structure and staffing pattern of SB Corporation and to extend to the employees and personal thereof salaries, allowances and fringe benefits similar to those extended to and currently enjoyed by employees and personal of other financial institutions.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A14","no":14,"noLabel":{"en":"SEC. 15."},"text":{"en":"SEC. 15. A new sub-section is hereby inserted after Section 11 of the same Act, as amended, to read as follows: \"SEC. 11-B Corporate Structure and Powers. - The SB Corporation shall: \"a) be administratively attached to the Department of Trade and Industry and shall be under the policy and program supervision of the MSMED Council; \"b) have its principal offices in Metro Manila and whenever necessary, establish branch office in the provinces; and \"c) exercise all the general powers expressly conferred by law upon corporations under the Corporation Code, including those powers that are incidental or necessary to the attainment of the objective of this Act. \"For this purpose, the SB Corporation subject to compliance with the rules and regulations to be issued by the Bangko Sentral ng Pilipinas (BSP) and the Securities and Exchange Commission, shall have the following functions and duties: \"a) Source and adopt development initiatives for globally competitive MSMEs in finance and business technologies; \"b) To extend all forms of financial assistance to eligible MSMEs. SB Corporation may also engage in wholesale lending. The SB Corporation shall be given two (2) years from the effectivity of this Act to comply with this requirement; \"c) Guarantee loans obtained by qualified MSMEs under such terms and conditions adopted by the SB Corporation Board of Directors; \"d) Hold, purchase, lease or otherwise acquire and own real and personal property, introduce necessary improvements thereon and to sell, mortgage, encumber or otherwise dispose of the same as may be necessary in the normal course of business; \"e) Formulate means and methods of accepting alternative collaterals and implementing alternative loan evaluation models; \"f) Apply for, receive and accept grants and donations from sources within and outside the country; and \"g) Hold, own, purchase, acquire, sell, mortgage, dispose or otherwise invest or re-invest in stocks, bonds, treasury bills, debentures, securities and similar forms of indebtedness of the government, its agencies and instrumentalities or any government financial institution.\""},"paragraphs":["A new sub-section is hereby inserted after Section 11 of the same Act, as amended, to read as follows: \"SEC. 11-B","Corporate Structure and Powers.","- The SB Corporation shall: \"a) be administratively attached to the Department of Trade and Industry and shall be under the policy and program supervision of the MSMED Council; \"b) have its principal offices in Metro Manila and whenever necessary, establish branch office in the provinces; and \"c) exercise all the general powers expressly conferred by law upon corporations under the Corporation Code, including those powers that are incidental or necessary to the attainment of the objective of this Act. \"For this purpose, the SB Corporation subject to compliance with the rules and regulations to be issued by the Bangko Sentral ng Pilipinas (BSP) and the Securities and Exchange Commission, shall have the following functions and duties: \"a) Source and adopt development initiatives for globally competitive MSMEs in finance and business technologies; \"b) To extend all forms of financial assistance to eligible MSMEs. SB Corporation may also engage in wholesale lending. The SB Corporation shall be given two (2) years from the effectivity of this Act to comply with this requirement; \"c) Guarantee loans obtained by qualified MSMEs under such terms and conditions adopted by the SB Corporation Board of Directors; \"d) Hold, purchase, lease or otherwise acquire and own real and personal property, introduce necessary improvements thereon and to sell, mortgage, encumber or otherwise dispose of the same as may be necessary in the normal course of business; \"e) Formulate means and methods of accepting alternative collaterals and implementing alternative loan evaluation models; \"f) Apply for, receive and accept grants and donations from sources within and outside the country; and \"g) Hold, own, purchase, acquire, sell, mortgage, dispose or otherwise invest or re-invest in stocks, bonds, treasury bills, debentures, securities and similar forms of indebtedness of the government, its agencies and instrumentalities or any government financial institution.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A15","no":15,"noLabel":{"en":"SEC. 12."},"text":{"en":"SEC. 12. Capitalization and Funding of the SB Corporation. - The SB Corporation shall have an authorized capital stock of Ten billion pesos (P10,000,000,000.00). The initial capital of One billion pesos (10,000,000,000.00) shall be established from a pool of funds to be contributed in the form of equity investment in common stock by the Land Bank of the Philippines (LBP), the Development Bank of the Philippines (DBP), in the amount of Two hundred million pesos (P200,000,000.00) each. the Social Security System (SSS) and the Government Service Insurance System (GSIS) shall also set aside Two hundred million pesos (P200,000,000.00) each for the SB Corporation. Authorized capital stock of the small business corporation shall be divided into 80,000,000 common shares and 20,000,000 preferred shares with a par value of One hundred pesos (P100.00) per share: Provided, That common shares, which have been issued, including those issued against assets of the KKK Guaranty Fund consolidated under the small business corporation by virtue of Executive Order No. 233, Series of 2000 and Executive Order No. 19, Series of 2001 and including those already subscribed, shall form part of the capitalization of the corporation: Provided, further, That holders of preferred shares issued under Republic Act No. 6977, as amended, shall have the option to convert the same into common shares. Additional equity shall come from trust placements of excess and unused funds of existing government agencies, bilateral and multilateral official development assistance funds, subscriptions from government owned or controlled corporations, and investments of private financial institutions and corporations: Provided, finally, That any investment from the private sector shall only be in the form of preferred shares. \"To allow for capital build-up, SB Corporation shall be given a five (5) year grace period on dividend commitments beginning on the date of effectivity of this amendment. Thereafter, it may only declare as dividend not more than thirty percent (30%) of its net income and the rest withheld as retained earnings.\""},"paragraphs":["Capitalization and Funding of the SB Corporation.","- The SB Corporation shall have an authorized capital stock of Ten billion pesos (P10,000,000,000.00). The initial capital of One billion pesos (10,000,000,000.00) shall be established from a pool of funds to be contributed in the form of equity investment in common stock by the Land Bank of the Philippines (LBP), the Development Bank of the Philippines (DBP), in the amount of Two hundred million pesos (P200,000,000.00) each. the Social Security System (SSS) and the Government Service Insurance System (GSIS) shall also set aside Two hundred million pesos (P200,000,000.00) each for the SB Corporation. Authorized capital stock of the small business corporation shall be divided into 80,000,000 common shares and 20,000,000 preferred shares with a par value of One hundred pesos (P100.00) per share: Provided, That common shares, which have been issued, including those issued against assets of the KKK Guaranty Fund consolidated under the small business corporation by virtue of Executive Order No. 233, Series of 2000 and Executive Order No. 19, Series of 2001 and including those already subscribed, shall form part of the capitalization of the corporation: Provided, further, That holders of preferred shares issued under Republic Act No. 6977, as amended, shall have the option to convert the same into common shares. Additional equity shall come from trust placements of excess and unused funds of existing government agencies, bilateral and multilateral official development assistance funds, subscriptions from government owned or controlled corporations, and investments of private financial institutions and corporations: Provided, finally, That any investment from the private sector shall only be in the form of preferred shares. \"To allow for capital build-up, SB Corporation shall be given a five (5) year grace period on dividend commitments beginning on the date of effectivity of this amendment. Thereafter, it may only declare as dividend not more than thirty percent (30%) of its net income and the rest withheld as retained earnings.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A16","no":16,"noLabel":{"en":"SEC. 14."},"text":{"en":"SEC. 14. Venture Capitial and Micro Finance Trust Fund. - The SB Corporation may set aside an amount of money to encourage the setting up of a venture capital and micro finance trust fund for the purpose of promoting business opportunities available of MSME sector. The Venture Capital Fund shall be used mainly for venture capital finance especially in technology-oriented industries. The micro finance trust fund shall be used to provide collateral-free fixed and working capital loans to micro and small enterprises run by those emerging out of poverty.\""},"paragraphs":["Venture Capitial and Micro Finance Trust Fund.","- The SB Corporation may set aside an amount of money to encourage the setting up of a venture capital and micro finance trust fund for the purpose of promoting business opportunities available of MSME sector. The Venture Capital Fund shall be used mainly for venture capital finance especially in technology-oriented industries. The micro finance trust fund shall be used to provide collateral-free fixed and working capital loans to micro and small enterprises run by those emerging out of poverty.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A17","no":17,"noLabel":{"en":"SEC. 15."},"text":{"en":"SEC. 15. Mandatory Allocation of Credit Resources to Micro Small and Meduim Enterprises. - For the period of ten (10) years from the date of the effectivity of this amendatory Act, all lending institutions as defined under Bangko Sentral ng Pilipinas rules, whether public or private, shall set aside at least eight percent (8%) for micro and small enterprises of their total loan portfolio based on their balance sheet as of the end of the previous quarter, and make it available for MSME credit as herein contemplated. \"Compliance of this provision shall be: \"a) actual extension of loans to eligible MSMEs; or \"b) actual subscription of preferred shares of shares of stock of the SB Corporation; or \"c) wholesale lending to Participating Financial Institutions (PFIS) for on-lending to MSMEs; or \"d) purchase/discount of MSMEs receivables; or \"e) loans granted to export, import, and domestic traders subject to compliance with Section 3 of this Act; or \"f) subscribed/purchase of liability instruments as may be offered by the SB Corporation. \"The Bangko Sentral ng Pilipinas shall formulate rules for the effective implementation of this provision: Provided, That the purchase of government notes, securities and other negotiable instruments shall not be deemed compliance with the foregoing provisions: Provided, further, That the Bangko Sentral ng Pilipinas shall establish an incentive program to encourage lending to micro, small and medium industries beyond the mandatory credit allocation to said enterprises, such as possible reduction in bank's reserve requirement. \"The MSMED Council shall set up the appropriate systems to monitor all loan applications of MSMSEs in order to account for the absorptive capacity of the MSME sector. \"The Bangko Sentral ng Pilipinas shall furnish to the MSMED Council on a quarterly basis comprehensive reports on the banks' compliance, noncompliance and penalties of the above provisions on the mandatory credit allocation for MSMEs. \"Lending institutions which are not qualified to acquire or hold lands of the public domain in the Philippines shall be permitted to bid and take part in sales of mortgaged real property in case of judicial r extra-judicial foreclosure, as well as avail of receivership, enforcement and other proceedings, solely upon default of a borrower, and for a period not exceeding five (5) years from actual possession: Provided, That in no event shall title to the property be transferred to such lending institution. If the lending institution is the winning bidder, it may, during said five (5) year period, transfer its rights to a qualified Philippine national, without prejudice to a borrower's right under applicable laws.\""},"paragraphs":["Mandatory Allocation of Credit Resources to Micro Small and Meduim Enterprises. - For the period of ten (10) years from the date of the effectivity of this amendatory Act, all lending institutions as defined under Bangko Sentral ng Pilipinas rules, whether public or private, shall set aside at least eight percent (8%) for micro and small enterprises of their total loan portfolio based on their balance sheet as of the end of the previous quarter, and make it available for MSME credit as herein contemplated. \"Compliance of this provision shall be: \"a) actual extension of loans to eligible MSMEs; or \"b) actual subscription of preferred shares of shares of stock of the SB Corporation; or \"c) wholesale lending to Participating Financial Institutions (PFIS) for on-lending to MSMEs; or \"d) purchase/discount of MSMEs receivables; or \"e) loans granted to export, import, and domestic traders subject to compliance with Section 3 of this Act; or \"f) subscribed/purchase of liability instruments as may be offered by the SB Corporation. \"The Bangko Sentral ng Pilipinas shall formulate rules for the effective implementation of this provision: Provided, That the purchase of government notes, securities and other negotiable instruments shall not be deemed compliance with the foregoing provisions: Provided, further, That the Bangko Sentral ng Pilipinas shall establish an incentive program to encourage lending to micro, small and medium industries beyond the mandatory credit allocation to said enterprises, such as possible reduction in bank's reserve requirement. \"The MSMED Council shall set up the appropriate systems to monitor all loan applications of MSMSEs in order to account for the absorptive capacity of the MSME sector. \"The Bangko Sentral ng Pilipinas shall furnish to the MSMED Council on a quarterly basis comprehensive reports on the banks' compliance, noncompliance and penalties of the above provisions on the mandatory credit allocation for MSMEs. \"Lending institutions which are not qualified to acquire or hold lands of the public domain in the Philippines shall be permitted to bid and take part in sales of mortgaged real property in case of judicial r extra-judicial foreclosure, as well as avail of receivership, enforcement and other proceedings, solely upon default of a borrower, and for a period not exceeding five (5) years from actual possession: Provided, That in no event shall title to the property be transferred to such lending institution. If the lending institution is the winning bidder, it may, during said five (5) year period, transfer its rights to a qualified Philippine national, without prejudice to a borrower's right under applicable laws.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A18","no":18,"noLabel":{"en":"SEC. 16."},"text":{"en":"SEC. 16. Micro, Small, and Medium Enterprise Week."},"paragraphs":["Micro, Small, and Medium Enterprise Week."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A19","no":19,"noLabel":{"en":"SEC. 17."},"text":{"en":"SEC. 17. Presidential Awards for Outstanding MSME."},"paragraphs":["Presidential Awards for Outstanding MSME."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A20","no":20,"noLabel":{"en":"SEC. 18."},"text":{"en":"SEC. 18. Congressional Oversight Committee. - To monitor and oversee the implementation of this Act, there shall be a Congressional Oversight Committee on Micro, Small and Medium Enterprise Development (COC-MSMED) composed of the chairpersons of the Senate Committee on Economic Affairs and the House Committee on Small Business and Entrepreneurship Development as chairperson and co-chairperson, respectively; five (5) members of each of the Senate and House of Representatives to include the chairpersons of the Senate committees on Trade and Commerce; and Banks, Financial Institutions and Currencies; and the chairpersons of the House of committees on Trade and Industry, Banks and Financial Intermediaries, and Appropriations: Provided, That two (2) of the five Senators and two (2) of the five House members shall be nominated by the respective minority leaders of the Senate and the House of Representatives. \"The COC-MSMED shall set the guidelines and overall framework for the monitoring of the implementation of this Act and shall adopt its internal rules of procedure. The Secretariat of the COC-MSMED shall be drawn from the existing personnel of the Senate and House of Representatives committees compromising the COC-MSMED.\""},"paragraphs":["Congressional Oversight Committee.","- To monitor and oversee the implementation of this Act, there shall be a Congressional Oversight Committee on Micro, Small and Medium Enterprise Development (COC-MSMED) composed of the chairpersons of the Senate Committee on Economic Affairs and the House Committee on Small Business and Entrepreneurship Development as chairperson and co-chairperson, respectively; five (5) members of each of the Senate and House of Representatives to include the chairpersons of the Senate committees on Trade and Commerce; and Banks, Financial Institutions and Currencies; and the chairpersons of the House of committees on Trade and Industry, Banks and Financial Intermediaries, and Appropriations: Provided, That two (2) of the five Senators and two (2) of the five House members shall be nominated by the respective minority leaders of the Senate and the House of Representatives. \"The COC-MSMED shall set the guidelines and overall framework for the monitoring of the implementation of this Act and shall adopt its internal rules of procedure. The Secretariat of the COC-MSMED shall be drawn from the existing personnel of the Senate and House of Representatives committees compromising the COC-MSMED.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A21","no":21,"noLabel":{"en":"SEC. 20."},"text":{"en":"SEC. 20. Section 14 of the same Act, as amended, on Penal Clause is hereby renumbered as Section 19, and further amended, to read as follows: \"x x x\" \"Penalties on noncompliance shall be directed to the development of the MSME sector. Ninety percent (90%) of the penalties collected should go to the MSMED Council Fund, while the remaining ten percent (10%) should be given to the BSP to cover for administrative expenses.\" SEC. 20. Implementing Rules and Regulations. - The Department of Trade and Industry, through the Bureau of Micro, Small and Medium Business Development in consultation with other concerned government agencies, nongovernment organizations and private sector involved in the promotion of MSMEs, shall formulate the implementing Rules and Regulations (IRR) necessary to implement the provisions of this Act within ninety (90) days from the approval of this Act. The IRR issued pursuant to this Section shall take effect thirty (30) days after publication in a national newspaper of general circulation.\""},"paragraphs":["Section 14 of the same Act, as amended, on Penal Clause is hereby renumbered as Section 19, and further amended, to read as follows: \"x x x\" \"Penalties on noncompliance shall be directed to the development of the MSME sector. Ninety percent (90%) of the penalties collected should go to the MSMED Council Fund, while the remaining ten percent (10%) should be given to the BSP to cover for administrative expenses.\"","SEC. 20. Implementing Rules and Regulations. - The Department of Trade and Industry, through the Bureau of Micro, Small and Medium Business Development in consultation with other concerned government agencies, nongovernment organizations and private sector involved in the promotion of MSMEs, shall formulate the implementing Rules and Regulations (IRR) necessary to implement the provisions of this Act within ninety (90) days from the approval of this Act. The IRR issued pursuant to this Section shall take effect thirty (30) days after publication in a national newspaper of general circulation.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A22","no":22,"noLabel":{"en":"SEC. 22."},"text":{"en":"SEC. 22. Separability Clause. - The provisions of the Act are hereby declared to be separable. If any provision of this Act shall be held unconstitutional, the remainder of the Act not otherwise affected shall remain in full force and effect."},"paragraphs":["Separability Clause.","- The provisions of the Act are hereby declared to be separable. If any provision of this Act shall be held unconstitutional, the remainder of the Act not otherwise affected shall remain in full force and effect."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A23","no":23,"noLabel":{"en":"SEC. 23."},"text":{"en":"SEC. 23. Repealing Clause. - All laws, executive orders, rules and regulations, or parts thereof, inconsistent herewith are hereby repealed or modified accordingly."},"paragraphs":["Repealing Clause.","- All laws, executive orders, rules and regulations, or parts thereof, inconsistent herewith are hereby repealed or modified accordingly."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},{"id":"PH-MSME-2008-A24","no":24,"noLabel":{"en":"SEC. 24."},"text":{"en":"SEC. 24. Effectivity Clause. - This Act shall take effect within fifteen (15) days from its publication in at least two (2) national newspaper of general circulation."},"paragraphs":["Effectivity Clause.","- This Act shall take effect within fifteen (15) days from its publication in at least two (2) national newspaper of general circulation. Approved, (Sgd.)","PROSPERO C. NOGRALES","Speaker of the House of Representatives (Sgd.)","MANNY VILLAR","President of the Senate This Act which is a consolidation of Senate Bill No. 1646 and House Bill No. 1754 was finally passed by the Senate and the House of Representatives on March 3, 2008 and February 27, 2008, respectively. (Sgd.)","MARILYN B. BARUA-YAP","Secretary GeneralHouse of Represenatives (Sgd.)","EMMA LIRIO-REYES","Secretary of Senate Approved:","May 23, 2008","(Sgd.)"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"}],"pack":"ph-2","fulltextMeta":{"country":"PH","level":"law","status":"active","topics":["investment"],"title":{"zh":"中小企业大宪章（经修订）","en":"Magna Carta for Micro, Small and Medium Enterprises"},"docNumber":"Republic Act No. 9501","issuingBody":{"zh":"菲律宾国会","en":"Congress of the Philippines"},"promulgatedDate":"2008-05-23","effectiveDate":"2008-06-07","coverage":"full","source":{"name":"The Lawphil Project — Arellano Law Foundation","url":"https://lawphil.net/statutes/repacts/ra2008/ra_9501_2008.html"},"summary":{"zh":"修订 R.A. 6977（中小企业大宪章），强化对微、小、中型企业的扶持与发展机制。","en":"An act to promote entrepreneurship by strengthening development and assistance programs to micro, small and medium scale enterprises."}},"summary":{"zh":"修订 R.A. 6977（中小企业大宪章），强化对微、小、中型企业的扶持与发展机制。","en":"An act to promote entrepreneurship by strengthening development and assistance programs to micro, small and medium scale enterprises."}};
  FT["PH-PSA-2022"] = {"id":"PH-PSA-2022","coverage":"full","language":"en","sourceName":"The Lawphil Project — Arellano Law Foundation","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html","fetchedAt":"2026-10-02","articleCount":46,"title":{"zh":"公共服务法修正案","en":"An Act Amending the Public Service Act","orig":"An Act Amending the Public Service Act","vi":"Đạo luật sửa đổi Đạo luật Dịch vụ Công ích","th":"พระราชบัญญัติแก้ไขพระราชบัญญัติบริการสาธารณะ","id":"Undang-Undang Perubahan atas Undang-Undang Pelayanan Publik","ms":"Akta Pindaan kepada Akta Perkhidmatan Awam"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 11659","issuingBody":"菲律宾国会","promulgatedDate":"2022-03-21","effectiveDate":"2022-04-04","completenessNote":"官方页面所载为修订型法条：以其自身 Section 1–35 逐条修订，并在同一条内全文引述被修正的 Commonwealth Act No. 146 相应条文（引文自带旧条号）；本库按官方条号全文照录，保留引文及其旧条号，未增删。","country":"PH","countryName":"菲律宾","layer":"fulltext","articles":[{"id":"PH-PSA-2022-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 1. Declaration of Policy. - The State recognize the role of the private sector as one of the main engines for national growth and development. It is hereby declared the policy of the State to encourage private enterprise and expand the base of investment in the country, with the goal of providing efficient, reliable and affordable basic services to all. These policies are fulfilled by: (a) ensuring effective regulation of public services; (b) providing reasonable rate of return to public services; (c) rationalizing foreign equity restrictions by clearly defining the term \"public utilities\"; and (d) instituting processes for the protection of national security."},"paragraphs":["Declaration of Policy.","- The State recognize the role of the private sector as one of the main engines for national growth and development. It is hereby declared the policy of the State to encourage private enterprise and expand the base of investment in the country, with the goal of providing efficient, reliable and affordable basic services to all. These policies are fulfilled by: (a) ensuring effective regulation of public services; (b) providing reasonable rate of return to public services; (c) rationalizing foreign equity restrictions by clearly defining the term \"public utilities\"; and (d) instituting processes for the protection of national security."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 2. Definition of Terms. - For the purposes of this Act, the terms below shall be defined as follows: (a) Administrative Agency or Administrative Agencies, as the case may be, refers to relevant govenrment agencies, to which the powers and duties of the Public Service Commission were transferred pursuant to existing laws. All mention of the word \"Commission\" in this Act shall now refer to this term; (b) Certificates refer to any franchise, certificate of public convenience, certificate of public convenience and necessity, concession, or any other appropriate form of authorization for the operation of a public service, including a public utility, as may be applicable; (c) Concession refers to a contract granting a private concessionaire the privilege to, among others, finance, construct, manage, operate and/or maintain concession assets; (d) Concessionaire refers to a person, corporation, firm or association awarded a concession; (e) Critical Infrastructure refers to any public service which owns, uses, or operates systems and assets, whether physical or virtual, so vital to the Republic of the Philippines that the incapacity or destruction of such systems or assets would have a detrimental impact on national security, including telecommunications and other such vital services as may be declared by the"},"paragraphs":["Definition of Terms.","- For the purposes of this Act, the terms below shall be defined as follows: (a) Administrative Agency or Administrative Agencies, as the case may be, refers to relevant govenrment agencies, to which the powers and duties of the Public Service Commission were transferred pursuant to existing laws. All mention of the word \"Commission\" in this Act shall now refer to this term; (b) Certificates refer to any franchise, certificate of public convenience, certificate of public convenience and necessity, concession, or any other appropriate form of authorization for the operation of a public service, including a public utility, as may be applicable; (c) Concession refers to a contract granting a private concessionaire the privilege to, among others, finance, construct, manage, operate and/or maintain concession assets; (d) Concessionaire refers to a person, corporation, firm or association awarded a concession; (e) Critical Infrastructure refers to any public service which owns, uses, or operates systems and assets, whether physical or virtual, so vital to the Republic of the Philippines that the incapacity or destruction of such systems or assets would have a detrimental impact on national security, including telecommunications and other such vital services as may be declared by the President of the Philippines; (f) Distribution of Electricity refers to the conveyance of electric power by a distribution utility through its distribution system as defined by Section 4(n) of Republic Act No. 9136, otherwise known as the \"Electric Power Industry Reform Act of 2001\", as amended; (g) Foreign State-owned Enterprise refers to an entity in which a foreign State: (i) directly or indirectly owns more than fifty-percent (50%) of the capital taking into account both the voting rights and beneficial ownership; (ii) control, through ownership interests, the exercise of more than fifty percent (50%) of the voting rights; or (iii) holds the power to appoint a majority of members of the board of directors or any other equivalent management body; (h) National Security refers to the requirements and conditions necessary to ensure the territorial integrity of the country and the safety, security, and well-being of Filipino citizens; (i) Petroleum and petroleum Product Pipeline Transmission Systems refer to the operation and maintenance of pipeline transmission systems to ensure an uninterrupted and adequate supply and transmission of petroleum and petroleum products to the public; and excludes petroleum pipeline systems operated exclusively for private or own use, or incidental to the operations of a distinct business; (j) Philippine National refers to citizens, partnerships, associations, and corporations defined by Section 3(a) of Republic Act No. 7042, otherwise known as the \"Foreign Investments Act of 1991\", as amended; (k) Public Utility Vehicles (PUVs) refer to internal combustion engine vehicles that carry passengers and/or domestic cargo for a fee, offering services to the public, namely trucks-for-hire, UV express service, public utility buses (PUBs), public utility jeepneys (PUJs), tricycles, filcabs, and taxis:","Provided,","That transport vehicles accredited with and operating through transport network corporations shall not be considered as public utility vehicles; (l) Seaport refers to a place where ships may anchor or tie up for the purpose of shelter, repair, loading or discharge of passengers or cargo, or for other such activities connected with water-borne commerce, and including all the land and water areas and the structures, equipment and facilities related to these functions, as defined by the charters of relevant authorities or agencies, such as the Philippine Ports Authority, Subic Bay Metropolitan Authority, PHIVIDEC Industrial Estate Authority, Cebu Port Authority, local government units, and other similar agencies or government bodies; (m) Telecommunications refers to any process which enables a telecommunications entity to relay and receive voice, data, electronic messages, written or printed matter, fixed or moving pictures, words, music or visible or audible signals or any control signals of any design and for any purpose by wire, radio or other electromagnetic, spectral, optical or technological means, as defined by Section 3(a) of Republic Act No. 7925, otherwise known as the \"Public Telecommunications Policy Act of the Philippines\", as amended, except passive telecommunications tower infrastructure and components, such as, but not limited to, poles, fiber ducts, dark fiber cables, and passive telecommunications tower infrastructure, as defined by the Department of Information and Communications Technology (DICT), and value-added services, as defined in Section 3(h) of Republic Act No. 7925, as amended; (n) Transmission of Electricity refers to the conveyance of electricity through the high voltage backbone system, as defined by Section 4(cc) of Republic Act No. 9136, as amended; (o) Water Pipeline Distribution Systems and Wastewater Pipeline Systems refer to the operation and maintenance of water pipeline distribution systems to ensure an uninterrupted and adequate supply and distribution of potable water for domestic and other purposes and the operation and maintenance of wastewater pipeline systems, except desludging companies and septic tanks, to ensure public health and safety, as regulated by Republic Act No. 6234, entitled \"An Act Creating the Metropolitan Waterworks and Sewerage System and Dissolving the National Waterworks and Sewerage Authority; and for Other Purposes\", as amended, and Presidential Decree No. 198, otherwise known as the \"Provincial Water Utilities Act of 1973\", as amended; and (p) Sewerage Pipeline Systems refers to the operation and maintenance of sewerage pipeline systems to ensure public health and safety, as regulated by Republic Act No. 6234, as amended, and Presidential Decree No. 198, as amended."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 3. Recognition of Transfer of Jurisdiction to Various Administrative Agencies. - All references to the Public Service Commission in Commonwealth Act No. 146, as amended, shall pertain to any Administrative Agency to which the powers and duties of the Public Service Commission were transferred by subsequent laws, such as but not limited to: (a) Civil Aeronautics Board (CAB); (b) Civil Aviation Authority of the Philippines (CAAP); (c) Department of Energy (DOE); (d) Department of Environment and Natural Resources (DENR); (e) DICT; (f) Department of Transportation (DOTr); (g) Energy Regulatory Commission (ERC); (h) Land Transportation Franchising and Regulatory Board (LTFRB); (i) Land Transportation Office (LTO); (j) Local Water Utilities Administration (LWUA); (k) Maritime Industry Authority (MARINA); (l) Metropolitan Waterworks and Sewerage System (MWSS); (m) National Telecommunication Commission (NTC); (n) National Water Resources Board (NWRB); (o) Philippine National Railways (PNR); (p) Philippine Ports Authority (PPA); and (q) Toll Regulatory Board (TRB)."},"paragraphs":["Recognition of Transfer of Jurisdiction to Various Administrative Agencies.","- All references to the Public Service Commission in Commonwealth Act No. 146, as amended, shall pertain to any Administrative Agency to which the powers and duties of the Public Service Commission were transferred by subsequent laws, such as but not limited to: (a) Civil Aeronautics Board (CAB); (b) Civil Aviation Authority of the Philippines (CAAP); (c) Department of Energy (DOE); (d) Department of Environment and Natural Resources (DENR); (e) DICT; (f) Department of Transportation (DOTr); (g) Energy Regulatory Commission (ERC); (h) Land Transportation Franchising and Regulatory Board (LTFRB); (i) Land Transportation Office (LTO); (j) Local Water Utilities Administration (LWUA); (k) Maritime Industry Authority (MARINA); (l) Metropolitan Waterworks and Sewerage System (MWSS); (m) National Telecommunication Commission (NTC); (n) National Water Resources Board (NWRB); (o) Philippine National Railways (PNR); (p) Philippine Ports Authority (PPA); and (q) Toll Regulatory Board (TRB)."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 4. Section 13 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 13 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A5","no":5,"noLabel":{"en":"Section 13."},"text":{"en":"Section 13. (a) The Commission shall have jurisdiction and supervision over all public services, including public utilities, and their franchises, equipment, and other properties, and in the exercise of its authority, it shall have the necessary powers and the aid of public force: Provided, That public services, including public utilities, owned or operated by government entities shall be regulated by the Commission in the same way as privately-owned public services. \"Nothing in this Act shall be interpreted to diminish, limit, or restrict the authority of Congress from granting franchises to public services, as may be provided by law. Any franchise or certificate necessary for the operation of a public service shall be granted by Congress unless otherwise previously delegated by law to the relevant Administrative Agencies. \"x x x \"(d) Public Utility. - Public Utility refers to a public service that operates, manages or controls for public use any of the following: \"(1) Distribution of Electricity; \"(2) Transmission of Electricity; \"(3) Petroleum and Petroleum Products Pipeline Transmission Systems; \"(4) Water Pipeline Distribution Systems and Wastewater Pipeline Systems, including sewerage pipeline systems; \"(5) Seaports; and \"(6) Public Utility Vehicles. \"All concessionaires, joint ventures and other similar entities that wholly operate, manage or control for public use the sectors above are public utilities. \"Nothing in this Act shall be interpreted as a requirement for legislative franchise where the law does not require any. No other person shall be deemed a public utility unless otherwise subsequently provided by law. \"(e) Upon the recommendation of the National Economic and Development Authority (NEDA), the President may recommend to Congress the classification of a public service as a public utility on the basis of the following criteria: \"(1) The person or juridical entity regularly supplies and transmits and distributes to the public through a network a commodity or service of public consequence; \"(2) The commodity or service is a natural monopoly that needs to be regulated when the common good so requires. For this purpose, natural monopoly exists when the market demand for a commodity or service can be supplied by a single entity at a lower cost that by two or more entities; \"(3) The commodity or service is necessary for the maintenance of life and occupation of the public; and \"(4) The commodity or service is obligated to provide adequate service to the public on demand. \"All public services, including those classified as public utilities under this Act, shall continue to be regulated and supervised by the relevant Administrative Agencies under existing laws. \"A public service which is not classified as a public utility under this Act shall be considered a business affected with public interest for purposes of Sections 17 and 18 of Article XII of the Constitution. \"Notwithstanding any law to the contrary, nationality requirements shall not be imposed by the relevant Administrative Agencies on any public service not classified as a public utility. \"The NEDA shall provide periodic advice to Administrative Agencies on the proper application of the constitutional and other legal restrictions to local and foreign-owned subcontractors, without putting operational resiliency at risk.\""},"paragraphs":["(a) The Commission shall have jurisdiction and supervision over all public services, including public utilities, and their franchises, equipment, and other properties, and in the exercise of its authority, it shall have the necessary powers and the aid of public force:","Provided,","That public services, including public utilities, owned or operated by government entities shall be regulated by the Commission in the same way as privately-owned public services. \"Nothing in this Act shall be interpreted to diminish, limit, or restrict the authority of Congress from granting franchises to public services, as may be provided by law. Any franchise or certificate necessary for the operation of a public service shall be granted by Congress unless otherwise previously delegated by law to the relevant Administrative Agencies. \"x x x \"(d) Public Utility. - Public Utility refers to a public service that operates, manages or controls for public use any of the following: \"(1) Distribution of Electricity; \"(2) Transmission of Electricity; \"(3) Petroleum and Petroleum Products Pipeline Transmission Systems; \"(4) Water Pipeline Distribution Systems and Wastewater Pipeline Systems, including sewerage pipeline systems; \"(5) Seaports; and \"(6) Public Utility Vehicles. \"All concessionaires, joint ventures and other similar entities that wholly operate, manage or control for public use the sectors above are public utilities. \"Nothing in this Act shall be interpreted as a requirement for legislative franchise where the law does not require any. No other person shall be deemed a public utility unless otherwise subsequently provided by law. \"(e) Upon the recommendation of the National Economic and Development Authority (NEDA), the President may recommend to Congress the classification of a public service as a public utility on the basis of the following criteria: \"(1) The person or juridical entity regularly supplies and transmits and distributes to the public through a network a commodity or service of public consequence; \"(2) The commodity or service is a natural monopoly that needs to be regulated when the common good so requires. For this purpose, natural monopoly exists when the market demand for a commodity or service can be supplied by a single entity at a lower cost that by two or more entities; \"(3) The commodity or service is necessary for the maintenance of life and occupation of the public; and \"(4) The commodity or service is obligated to provide adequate service to the public on demand. \"All public services, including those classified as public utilities under this Act, shall continue to be regulated and supervised by the relevant Administrative Agencies under existing laws. \"A public service which is not classified as a public utility under this Act shall be considered a business affected with public interest for purposes of Sections 17 and 18 of Article XII of the Constitution. \"Notwithstanding any law to the contrary, nationality requirements shall not be imposed by the relevant Administrative Agencies on any public service not classified as a public utility. \"The NEDA shall provide periodic advice to Administrative Agencies on the proper application of the constitutional and other legal restrictions to local and foreign-owned subcontractors, without putting operational resiliency at risk.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A6","no":6,"noLabel":{"en":"Section 5."},"text":{"en":"Section 5. Section 15 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 15 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A7","no":7,"noLabel":{"en":"Section 15."},"text":{"en":"Section 15. x x x \"The Commission shall prescribe as a condition for the issuance of the certificate or authorization provided in the preceding paragraph that the service can be acquired by the Republic of the Philippines or any instrumentality thereof, or the issuing local government unit, upon payment of just compensation in accordance with the pertinent laws, rules, and regulations on expropriation; and likewise, that the certificate or authorization shall be valid only for a definite period of time and that the violation of any of theses conditions shall, after hearing, result in the immediate cancellation of the certificate or authorization without the necessity of any express action on the part of the issuing authority. \"x x x.\""},"paragraphs":["x x x \"The Commission shall prescribe as a condition for the issuance of the certificate or authorization provided in the preceding paragraph that the service can be acquired by the Republic of the Philippines or any instrumentality thereof, or the issuing local government unit, upon payment of just compensation in accordance with the pertinent laws, rules, and regulations on expropriation; and likewise, that the certificate or authorization shall be valid only for a definite period of time and that the violation of any of theses conditions shall, after hearing, result in the immediate cancellation of the certificate or authorization without the necessity of any express action on the part of the issuing authority. \"x x x.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A8","no":8,"noLabel":{"en":"Section 6."},"text":{"en":"Section 6. Section 16 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 16 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A9","no":9,"noLabel":{"en":"Section 16."},"text":{"en":"Section 16. Proceedings of the Commission, upon notice and hearing. - The Commission shall have the power, upon notice and hearing in accordance with the rules and provisions of this Act: \"(a) To issue certificates authorizing the operation of public service within the Philippines whenever the Commission finds that the operation of the public service proposed and the authorization to do business will promote the public interest in a proper and suitable manner: Provided, That any certificate authorizing the operation, management or control of a public service shall only be issued to corporations, partnerships, associations or joint stock companies that are constituted and organized under the laws of the Philippines. \"x x x \"(c) To fix and determine the fair and reasonable individual or joint rates, tolls, charges, classifications, tariffs or schedules thereof, as well as commutation, mileage, kilometrage, and other special rates which shall be imposed, observed, and followed thereafter by any public service when the public interest so requires: Provided, That the Commission may, in its discretion, approve rates proposed by public services provisionally and without necessity of any hearing; but it shall call a hearing thereon within fifteen (15) days, thereafter, upon publication and notice to the affected parties in the territory affected, to ratify its prior provisional approval or change, modify or later the approved rate based on public interest: Provided, further, That in case the public service equipment of an operator is used principally or secondarily for the promotion of a private business, the net profits of said private business shall be considered in relation with the public service of such operator for the purpose of fixing the rates: Provided, finally, That when the public interest requires, the Administrative Agency may establish and enforce a methodology for setting rates, taking into account all relevant considerations, including the efficiency of the regulated public service. The rates must be such as to allow the recovery of prudent and efficient costs and a reasonable rate of return to enable the public service to operate viably and efficiently. The Administrative Agency may adopt alternative forms consistent with internationally accepted rate-setting methodology. The adopted rate-setting methodology shall ensure a reasonable price of the commodity or service and that the rates prescribed shall not be discriminatory. \"This provision shall not be interpreted as mandating rate regulation nor amending or repealing: (1) laws providing a deregulation policy, such as Republic Act No. 7925, otherwise known as the \"Public Telecommunications Policy Act of the Philippines', as amended; Republic Act No. 8479, otherwise known as the 'Downstream Oil Industry Deregulation Act of 1998', as amended; Republic Act No. 9136, otherwise known as the 'Electric Power Industry Reform Act of 2001', as amended; Republic Act No. 9295, otherwise known as the 'Domestic Shipping Development Act of 2004', as amended; and Republic Act No. 6957, otherwise known as the 'BOT law', as amended; and (2) regulations promulgated by these Administrative Agencies to deregulate rates. \"x x x \"(l) To fix and determine proper and adequate rates of description of the property of any public service which will be observed in a proper and adequate depreciation account to be carried for the protection of stockholders, bondholders or creditors, in accordance with such rules, regulations, and forms of accounts as the Commission may prescribe. Said rates shall be sufficient to provide the amounts required over and above the expense of maintenance to keep such property in a state of efficiency corresponding to the progress of the industry. Each public service shall conform its depreciation accounts to the rates so determined and fixed, and, as may be required by the proper Administrative Agency, shall set aside the moneys so provided for out of its earnings and carry the same in a depreciation fund. The income from investments of money in such fund shall likewise be carried in such fund. This fund shall not be expended otherwise than for depreciation, improvements, new constructions, extensions or additions to the property of such public service. \"x x x \"(p) To suspend or revoke any certificate issued under the provisions of this Act when the holder thereof has failed for three (3) consecutive years the annual performance audit conducted by an independent evaluation team in accordance with the metrics to be set by the Administrative Agency.\""},"paragraphs":["Proceedings of the Commission, upon notice and hearing. - The Commission shall have the power, upon notice and hearing in accordance with the rules and provisions of this Act: \"(a) To issue certificates authorizing the operation of public service within the Philippines whenever the Commission finds that the operation of the public service proposed and the authorization to do business will promote the public interest in a proper and suitable manner:","Provided,","That any certificate authorizing the operation, management or control of a public service shall only be issued to corporations, partnerships, associations or joint stock companies that are constituted and organized under the laws of the Philippines. \"x x x \"(c) To fix and determine the fair and reasonable individual or joint rates, tolls, charges, classifications, tariffs or schedules thereof, as well as commutation, mileage, kilometrage, and other special rates which shall be imposed, observed, and followed thereafter by any public service when the public interest so requires:","Provided,","That the Commission may, in its discretion, approve rates proposed by public services provisionally and without necessity of any hearing; but it shall call a hearing thereon within fifteen (15) days, thereafter, upon publication and notice to the affected parties in the territory affected, to ratify its prior provisional approval or change, modify or later the approved rate based on public interest:","Provided,","further, That in case the public service equipment of an operator is used principally or secondarily for the promotion of a private business, the net profits of said private business shall be considered in relation with the public service of such operator for the purpose of fixing the rates:","Provided,","finally, That when the public interest requires, the Administrative Agency may establish and enforce a methodology for setting rates, taking into account all relevant considerations, including the efficiency of the regulated public service. The rates must be such as to allow the recovery of prudent and efficient costs and a reasonable rate of return to enable the public service to operate viably and efficiently. The Administrative Agency may adopt alternative forms consistent with internationally accepted rate-setting methodology. The adopted rate-setting methodology shall ensure a reasonable price of the commodity or service and that the rates prescribed shall not be discriminatory. \"This provision shall not be interpreted as mandating rate regulation nor amending or repealing: (1) laws providing a deregulation policy, such as Republic Act No. 7925, otherwise known as the \"Public Telecommunications Policy Act of the Philippines', as amended; Republic Act No. 8479, otherwise known as the 'Downstream Oil Industry Deregulation Act of 1998', as amended; Republic Act No. 9136, otherwise known as the 'Electric Power Industry Reform Act of 2001', as amended; Republic Act No. 9295, otherwise known as the 'Domestic Shipping Development Act of 2004', as amended; and Republic Act No. 6957, otherwise known as the 'BOT law', as amended; and (2) regulations promulgated by these Administrative Agencies to deregulate rates. \"x x x \"(l) To fix and determine proper and adequate rates of description of the property of any public service which will be observed in a proper and adequate depreciation account to be carried for the protection of stockholders, bondholders or creditors, in accordance with such rules, regulations, and forms of accounts as the Commission may prescribe. Said rates shall be sufficient to provide the amounts required over and above the expense of maintenance to keep such property in a state of efficiency corresponding to the progress of the industry. Each public service shall conform its depreciation accounts to the rates so determined and fixed, and, as may be required by the proper Administrative Agency, shall set aside the moneys so provided for out of its earnings and carry the same in a depreciation fund. The income from investments of money in such fund shall likewise be carried in such fund. This fund shall not be expended otherwise than for depreciation, improvements, new constructions, extensions or additions to the property of such public service. \"x x x \"(p) To suspend or revoke any certificate issued under the provisions of this Act when the holder thereof has failed for three (3) consecutive years the annual performance audit conducted by an independent evaluation team in accordance with the metrics to be set by the Administrative Agency.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A10","no":10,"noLabel":{"en":"Section 7."},"text":{"en":"Section 7. Section 17 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 17 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A11","no":11,"noLabel":{"en":"Section 17."},"text":{"en":"Section 17. Proceedings of Commission without previous hearing. - The Commission shall have power, without previous hearing, subject to established limitations and exceptions and saving provisions to the contrary: \"(a) To investigate, upon its own initiative, or upon complaint in writing, any matter concerning any public service as regards matters under its jurisdiction; to require any public service to furnish safe, adequate, and proper service as the public interest may require and warrant; to enforce compliance with any standard, rule, regulation, order or other requirement of this Act or of the Commission, and to prohibit or prevent any public service as herein defined from operating without having first secured a certificate and require existing public services to pay the fees provided for in this Act for the issuance of the certificate, under the penalty, at the discretion of the Commission, of the revocation and cancellation of any acquired right. \"(b) To require any public service to pay the actual expenses incurred by the Commission in any investigation if it shall be found in the same that any rate, toll, charge, schedule, regulation, practice, act or service thereof is in violation of any provision of this Act or any certificate, order, rule, regulation or requirement issued or established by the Commission. The Commission may also assess against any public service reasonable costs with reference to such investigation. \"x x x \"(g) To require any public service to keep its books, records, and accounts so as to afford an intelligent understanding of the conduct of its business and to that end to require every such public service of the same class to adopt a uniform system of accounting. Such system shall conform to any system approved and confirmed by the Commission on Audit. \"x x x.\""},"paragraphs":["Proceedings of Commission without previous hearing. - The Commission shall have power, without previous hearing, subject to established limitations and exceptions and saving provisions to the contrary: \"(a) To investigate, upon its own initiative, or upon complaint in writing, any matter concerning any public service as regards matters under its jurisdiction; to require any public service to furnish safe, adequate, and proper service as the public interest may require and warrant; to enforce compliance with any standard, rule, regulation, order or other requirement of this Act or of the Commission, and to prohibit or prevent any public service as herein defined from operating without having first secured a certificate and require existing public services to pay the fees provided for in this Act for the issuance of the certificate, under the penalty, at the discretion of the Commission, of the revocation and cancellation of any acquired right. \"(b) To require any public service to pay the actual expenses incurred by the Commission in any investigation if it shall be found in the same that any rate, toll, charge, schedule, regulation, practice, act or service thereof is in violation of any provision of this Act or any certificate, order, rule, regulation or requirement issued or established by the Commission. The Commission may also assess against any public service reasonable costs with reference to such investigation. \"x x x \"(g) To require any public service to keep its books, records, and accounts so as to afford an intelligent understanding of the conduct of its business and to that end to require every such public service of the same class to adopt a uniform system of accounting. Such system shall conform to any system approved and confirmed by the Commission on Audit. \"x x x.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A12","no":12,"noLabel":{"en":"Section 8."},"text":{"en":"Section 8. Section 18 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 18 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A13","no":13,"noLabel":{"en":"Section 18."},"text":{"en":"Section 18. It shall be unlawful for any individual, partnership, association, corporation or joint-stock company, their lessees, trustees, or receivers appointed by any court whatsoever, or any municipality, province, or other department of the Government of the Philippines, to engage in any public service business without having first secured from the Commission a certificate as provided for in this Act, except grantees of legislative franchises expressly exempting such grantee from the requirement of securing a certificate from this Commission, as well as concerned at present existing expressly exempted from the jurisdiction of the Commission, either totally or in part, by the provisions of section thirteen of this Act.\""},"paragraphs":["It shall be unlawful for any individual, partnership, association, corporation or joint-stock company, their lessees, trustees, or receivers appointed by any court whatsoever, or any municipality, province, or other department of the Government of the Philippines, to engage in any public service business without having first secured from the Commission a certificate as provided for in this Act, except grantees of legislative franchises expressly exempting such grantee from the requirement of securing a certificate from this Commission, as well as concerned at present existing expressly exempted from the jurisdiction of the Commission, either totally or in part, by the provisions of section thirteen of this Act.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A14","no":14,"noLabel":{"en":"Section 9."},"text":{"en":"Section 9. Section 19 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 19 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A15","no":15,"noLabel":{"en":"Section 19."},"text":{"en":"Section 19. Unlawful act. - It shall be unlawful for any public service: \"x x x \"(c) To refuse or neglect, when requested by the Postmaster General or his authorized representative, to carry public mail on the regular trips of any public land transportation service maintained or operated by any such public service, upon such terms and conditions and for a consideration in such amounts as may be agreed upon between the Postmaster General and the public service carrier or fixed by the Commission in the absence of an agreement between the Postmaster General and the carrier. In case the Postmaster General and the public service carrier are unable to agree on the amount of the compensation to be paid for the carriage of the mail, the Postmaster General shall forthwith request the Commission to fix a just and reasonable compensation for such carriage and the same shall be promptly fixed by the Commission in accordance with section sixteen of this Act. \"(d) To refuse or neglect, when requested by the Administrative Agency to urgently use, deliver or render the public service for the purpose of avoiding further loss on human, material, economic, or environment during a state of calamity.\""},"paragraphs":["Unlawful act. - It shall be unlawful for any public service: \"x x x \"(c) To refuse or neglect, when requested by the Postmaster General or his authorized representative, to carry public mail on the regular trips of any public land transportation service maintained or operated by any such public service, upon such terms and conditions and for a consideration in such amounts as may be agreed upon between the Postmaster General and the public service carrier or fixed by the Commission in the absence of an agreement between the Postmaster General and the carrier. In case the Postmaster General and the public service carrier are unable to agree on the amount of the compensation to be paid for the carriage of the mail, the Postmaster General shall forthwith request the Commission to fix a just and reasonable compensation for such carriage and the same shall be promptly fixed by the Commission in accordance with section sixteen of this Act. \"(d) To refuse or neglect, when requested by the Administrative Agency to urgently use, deliver or render the public service for the purpose of avoiding further loss on human, material, economic, or environment during a state of calamity.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A16","no":16,"noLabel":{"en":"Section 10."},"text":{"en":"Section 10. Section 20 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 20 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A17","no":17,"noLabel":{"en":"Section 20."},"text":{"en":"Section 20. Acts requiring the approval of the Commission. - Subject to established limitations and exceptions and saving provisions to the contrary, it shall be unlawful for any public service or for the owner, lessee or operator thereof, without the approval and authorization of the Commission previously had: \"(a) To adopt, establish, fix, impose, maintain, or collect or carry into effect any individual or joint rates, commutation, mileage or other special rate, toll, fare,charge, classification or itinerary. The Commission shall approve only those that are prudent and efficient and not any that are unjustly discriminatory or unduly preferential, only upon reasonable notice to the public services and other parties concerned. giving them a reasonable opportunity to be heard, and the burden of the proof to show that the proposed rates or regulation are prudent and efficient shall be upon the public service purposing the same. \"(b) To establish, construct, maintain, or operate new units or extend existing facilities or make any other addition to or general extension of the service: Provided, That only assets that are useful and necessary for the provision of the public service shall form part of the rate base as determined and approved by the Administrative Agency: Provided, further, That construction of such asset and implementation of such project may be allowed for emergency and other extraordinary cases: Provided, finally, That the public service provider files for approval of such extension or construction of facilities within sixty (60) days from implementation of the project, and without prejudice to the final determination by the Administrative Agency if the said asset is useful and necessary for inclusion in the rate base. \"The Administrative Agency may issue regulations prescribing a shorter period than that provided in the preceding paragraphs only in cases of emergency, as may be certified by such Administrative Agency, requiring the installation, construction or maintenance of units, facilities or equipment. \"x x x \"(e) To issue any share of stock without par value: Provided, That it shall be the duty of the Commission, after hearing, to approve any such time when satisfied that the same is to be made in accordance with law. \"x x x \"(g) To sell, alienate, mortgage, encumber or lease its property, franchises, certificates, privileges, or rights, or any part thereof, or merge or consolidate its property, franchise, privileges or rights, or any part thereof, with those of any other public service. The approval therein required shall be given, after notice to the public and after hearing the persons interested at a public hearing, if it be shown that there are just and reasonable grounds for making the mortgage or encumbrance, for liabilities of more than one year maturity, or the sale, alienation, lease, merger, or consolidation to be approved, and that the same are not detrimental to the public interest, and in case of sale, the date on which the same is to be consummated shall be fixed in the order of approval: Provided, however, That nothing herein contained shall be construed to prevent the transaction from being negotiated or completed before its approval or to prevent the sale, alienation, or lease by any public service of any of its property in the ordinary course of its business: Provided, finally, That the need for approval of the sale, alienation, mortgage, encumbrance or lease will be required only for properties of the public service that are used and useful in the delivery of the required public service. \"x x x \"(i) To sell, alienate or in any matter transfer shares of its capital stock to any alien if the result of that sale, alienation, or transfer in itself or in connection with another previous sale shall be the reduction to less than sixty percent (60%) of the capital stock belonging to Philippine Nationals in the operation of a public utility as required by the Constitution. Such sale, alienation or transfer shall be void and of no effect and shall be sufficient cause for ordering the cancellation of the certificate. \"x x x.\""},"paragraphs":["Acts requiring the approval of the Commission. - Subject to established limitations and exceptions and saving provisions to the contrary, it shall be unlawful for any public service or for the owner, lessee or operator thereof, without the approval and authorization of the Commission previously had: \"(a) To adopt, establish, fix, impose, maintain, or collect or carry into effect any individual or joint rates, commutation, mileage or other special rate, toll, fare,charge, classification or itinerary. The Commission shall approve only those that are prudent and efficient and not any that are unjustly discriminatory or unduly preferential, only upon reasonable notice to the public services and other parties concerned. giving them a reasonable opportunity to be heard, and the burden of the proof to show that the proposed rates or regulation are prudent and efficient shall be upon the public service purposing the same. \"(b) To establish, construct, maintain, or operate new units or extend existing facilities or make any other addition to or general extension of the service:","Provided,","That only assets that are useful and necessary for the provision of the public service shall form part of the rate base as determined and approved by the Administrative Agency:","Provided,","further, That construction of such asset and implementation of such project may be allowed for emergency and other extraordinary cases:","Provided,","finally, That the public service provider files for approval of such extension or construction of facilities within sixty (60) days from implementation of the project, and without prejudice to the final determination by the Administrative Agency if the said asset is useful and necessary for inclusion in the rate base. \"The Administrative Agency may issue regulations prescribing a shorter period than that provided in the preceding paragraphs only in cases of emergency, as may be certified by such Administrative Agency, requiring the installation, construction or maintenance of units, facilities or equipment. \"x x x \"(e) To issue any share of stock without par value:","Provided,","That it shall be the duty of the Commission, after hearing, to approve any such time when satisfied that the same is to be made in accordance with law. \"x x x \"(g) To sell, alienate, mortgage, encumber or lease its property, franchises, certificates, privileges, or rights, or any part thereof, or merge or consolidate its property, franchise, privileges or rights, or any part thereof, with those of any other public service. The approval therein required shall be given, after notice to the public and after hearing the persons interested at a public hearing, if it be shown that there are just and reasonable grounds for making the mortgage or encumbrance, for liabilities of more than one year maturity, or the sale, alienation, lease, merger, or consolidation to be approved, and that the same are not detrimental to the public interest, and in case of sale, the date on which the same is to be consummated shall be fixed in the order of approval:","Provided,","however, That nothing herein contained shall be construed to prevent the transaction from being negotiated or completed before its approval or to prevent the sale, alienation, or lease by any public service of any of its property in the ordinary course of its business:","Provided,","finally, That the need for approval of the sale, alienation, mortgage, encumbrance or lease will be required only for properties of the public service that are used and useful in the delivery of the required public service. \"x x x \"(i) To sell, alienate or in any matter transfer shares of its capital stock to any alien if the result of that sale, alienation, or transfer in itself or in connection with another previous sale shall be the reduction to less than sixty percent (60%) of the capital stock belonging to Philippine Nationals in the operation of a public utility as required by the Constitution. Such sale, alienation or transfer shall be void and of no effect and shall be sufficient cause for ordering the cancellation of the certificate. \"x x x.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A18","no":18,"noLabel":{"en":"Section 11."},"text":{"en":"Section 11. Section 21 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 21 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A19","no":19,"noLabel":{"en":"Section 21."},"text":{"en":"Section 21. In the absences of any specific fine or penalty imposed under the Charter of the Administrative Agency or the special law governing the particular public service, any public service violating or failing to comply with the terms and conditions of any certificate or any order, decision or regulation of the Commission shall be subject to a fine of not lower than Five thousand pesos (P5,000.00) but not exceeding Two million pesos (P2,000,000.00) per day for every day during which such default or violation continues; and the Commission is hereby authorized and empowered to impose such fine, after due notice and hearing: Provided, That should a lesser fine or penalty be imposed under the Charter of the Administrative Agency or the special law governing the public service, the amount of fine or penalty provided for under this section shall apply. \"In cases where rates collected by the public service exceed the rates authorized by the Administrative Agency, the Administrative Agency may order a refund to consumers in lieu of or in addition to the fine or penalty imposed under this Act or the special law governing the public service. \"The fines so imposed shall be paid to the Government of the Philippine through the Commission, and failure to pay the fine or comply with the order to refund in any case within the time specified in the order or decision of the Commission shall be deemed good and sufficient reason for the suspension of the certificate of said public service until payment shall be made or the order is complied with. Payment may also be enforced by appropriate action brought in a court of competent jurisdiction. The remedy provided in this section shall not be a bar to, or affect any other remedy provided in this Act but shall be cumulative and additional to such remedy or remedies.\""},"paragraphs":["In the absences of any specific fine or penalty imposed under the Charter of the Administrative Agency or the special law governing the particular public service, any public service violating or failing to comply with the terms and conditions of any certificate or any order, decision or regulation of the Commission shall be subject to a fine of not lower than Five thousand pesos (P5,000.00) but not exceeding Two million pesos (P2,000,000.00) per day for every day during which such default or violation continues; and the Commission is hereby authorized and empowered to impose such fine, after due notice and hearing:","Provided,","That should a lesser fine or penalty be imposed under the Charter of the Administrative Agency or the special law governing the public service, the amount of fine or penalty provided for under this section shall apply. \"In cases where rates collected by the public service exceed the rates authorized by the Administrative Agency, the Administrative Agency may order a refund to consumers in lieu of or in addition to the fine or penalty imposed under this Act or the special law governing the public service. \"The fines so imposed shall be paid to the Government of the Philippine through the Commission, and failure to pay the fine or comply with the order to refund in any case within the time specified in the order or decision of the Commission shall be deemed good and sufficient reason for the suspension of the certificate of said public service until payment shall be made or the order is complied with. Payment may also be enforced by appropriate action brought in a court of competent jurisdiction. The remedy provided in this section shall not be a bar to, or affect any other remedy provided in this Act but shall be cumulative and additional to such remedy or remedies.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A20","no":20,"noLabel":{"en":"Section 12."},"text":{"en":"Section 12. Section 23 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""},"paragraphs":["Section 23 of Commonwealth Act No. 146, as amended, is hereby further amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A21","no":21,"noLabel":{"en":"Section 23."},"text":{"en":"Section 23. Any public service corporation that shall perform, commit, or do any act or thing herein forbidden or prohibited or shall neglect, fail, or omit to do or perform any act or thing herein required to be done or performed, shall be punished, after notice and hearing, by a fine not exceeding Two million pesos (P2,000,000.00), or by imprisonment of not lower than six (6) years and one (1) day and not higher than twelve (12) years, or both, at the discretion of the court. \"In case the services of any entity engaged in the operation and management of critical infrastructure are interrupted, it shall act on customer complaints within ten (10) days, or provide an action plan to be accomplished within a reasonable period, from the date the complaint, written or otherwise, was received. For this purpose, entities engaged in the operation and management of critical infrastructure shall file a monthly report to the appropriate regulatory agency detailing the service interruptions that occurred during the covered period, the complaints lodged before it, and the actions taken on each complaint.\""},"paragraphs":["Any public service corporation that shall perform, commit, or do any act or thing herein forbidden or prohibited or shall neglect, fail, or omit to do or perform any act or thing herein required to be done or performed, shall be punished, after notice and hearing, by a fine not exceeding Two million pesos (P2,000,000.00), or by imprisonment of not lower than six (6) years and one (1) day and not higher than twelve (12) years, or both, at the discretion of the court. \"In case the services of any entity engaged in the operation and management of critical infrastructure are interrupted, it shall act on customer complaints within ten (10) days, or provide an action plan to be accomplished within a reasonable period, from the date the complaint, written or otherwise, was received. For this purpose, entities engaged in the operation and management of critical infrastructure shall file a monthly report to the appropriate regulatory agency detailing the service interruptions that occurred during the covered period, the complaints lodged before it, and the actions taken on each complaint.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A22","no":22,"noLabel":{"en":"Section 13."},"text":{"en":"Section 13. Section 24 of Commonwealth Act No. 146, as amended, is hereby amended to read as follows: \""},"paragraphs":["Section 24 of Commonwealth Act No. 146, as amended, is hereby amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A23","no":23,"noLabel":{"en":"Section 24."},"text":{"en":"Section 24. Any person, including juridical persons whether foreign or domestic, who shall knowingly and willfully perform, commit, or do, or participate in performing, committing, or doing, or who shall knowingly and willfully cause, participate, or join with others in causing any public service corporation or company to do, perform, or commit, or who shall advise, solicit, persuade, or knowingly and willfully instruct, direct, or order any officer, agent or employee of any public service corporation or company to perform, commit, or do any act or thing forbidden or prohibited by this Act, shall be punished, after notice and hearing, by a fine of not exceeding Two million pesos (P2,000,000.00), or imprisonment of not lower than six (6) years and one (1) day and not higher that twelve (12) years, or both, at the discretion of the court. \"When the entities involved are juridical persons, the penalty of imprisonment shall be imposed on its officers, directors, or employees holding managerial positions, who are knowingly and willfully responsible for such violation.\""},"paragraphs":["Any person, including juridical persons whether foreign or domestic, who shall knowingly and willfully perform, commit, or do, or participate in performing, committing, or doing, or who shall knowingly and willfully cause, participate, or join with others in causing any public service corporation or company to do, perform, or commit, or who shall advise, solicit, persuade, or knowingly and willfully instruct, direct, or order any officer, agent or employee of any public service corporation or company to perform, commit, or do any act or thing forbidden or prohibited by this Act, shall be punished, after notice and hearing, by a fine of not exceeding Two million pesos (P2,000,000.00), or imprisonment of not lower than six (6) years and one (1) day and not higher that twelve (12) years, or both, at the discretion of the court. \"When the entities involved are juridical persons, the penalty of imprisonment shall be imposed on its officers, directors, or employees holding managerial positions, who are knowingly and willfully responsible for such violation.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A24","no":24,"noLabel":{"en":"Section 14."},"text":{"en":"Section 14. Section 25 of Commonwealth Act No. 146, as amended, is hereby amended to read as follows: \""},"paragraphs":["Section 25 of Commonwealth Act No. 146, as amended, is hereby amended to read as follows: \""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Section 25. Any person, including juridical persons whether foreign or domestic, who shall knowingly and willfully neglect, fail, or omit to do or perform, or who shall knowingly and willfully cause or join or participate with others in causing any public service corporation or company to neglect, fail, or omit to do or perform, or who shall advise, solicit, or persuade, or knowingly and willfully instruct, direct, or order any officer, agent or employee of any public service corporation or company to neglect, fail, or omit to do any act or thing required to be done by this Act, shall be punished, after notice and hearing, by a fine not exceeding Two million pesos (P2,000,000.00) or by imprisonment of not lower than six (6) years and one (1) day and not higher that twelve (12) years, or both, at the discretion of the court. When the entities involved are juridical persons, the penalty of imprisonment shall be imposed on its officers, directors, or employees holding managerial positions, who are knowingly and willfully responsible for such violation.\""},"paragraphs":["Any person, including juridical persons whether foreign or domestic, who shall knowingly and willfully neglect, fail, or omit to do or perform, or who shall knowingly and willfully cause or join or participate with others in causing any public service corporation or company to neglect, fail, or omit to do or perform, or who shall advise, solicit, or persuade, or knowingly and willfully instruct, direct, or order any officer, agent or employee of any public service corporation or company to neglect, fail, or omit to do any act or thing required to be done by this Act, shall be punished, after notice and hearing, by a fine not exceeding Two million pesos (P2,000,000.00) or by imprisonment of not lower than six (6) years and one (1) day and not higher that twelve (12) years, or both, at the discretion of the court. When the entities involved are juridical persons, the penalty of imprisonment shall be imposed on its officers, directors, or employees holding managerial positions, who are knowingly and willfully responsible for such violation.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A26","no":26,"noLabel":{"en":"SEC. 26."},"text":{"en":"SEC. 26. Any person who shall destroy, injure, or interfere with any apparatus or appliance owned or operated by or in charge of the Commission or its agents, shall be deemed guilty of a misdemeanor and upon conviction shall be punished, after notice and hearing, by a fine of the amount equivalent to the actual market value of the apparatus or appliance destroyed or injured plus a fine not exceeding Two million pesos (P2,000,000.00) or imprisonment of not lower than six (6) years and one (1) day and not higher than twelve (12) years, or both, at the discretion of the court.\""},"paragraphs":["Any person who shall destroy, injure, or interfere with any apparatus or appliance owned or operated by or in charge of the Commission or its agents, shall be deemed guilty of a misdemeanor and upon conviction shall be punished, after notice and hearing, by a fine of the amount equivalent to the actual market value of the apparatus or appliance destroyed or injured plus a fine not exceeding Two million pesos (P2,000,000.00) or imprisonment of not lower than six (6) years and one (1) day and not higher than twelve (12) years, or both, at the discretion of the court.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A27","no":27,"noLabel":{"en":"SEC. 28."},"text":{"en":"SEC. 28. Violations of the orders, decisions, and regulations of the Commission and of the terms and conditions of any certificate issued by the Commission and violations of the provisions of this Act shall prescribe in accordance with Act No. 3326, entitled 'An Act to Establish Periods of Prescription for Violations Penalized by Special Acts and Municipal Ordinances and to Provide When Prescription Shall Begin to Run', as amended.\""},"paragraphs":["Violations of the orders, decisions, and regulations of the Commission and of the terms and conditions of any certificate issued by the Commission and violations of the provisions of this Act shall prescribe in accordance with Act No. 3326, entitled 'An Act to Establish Periods of Prescription for Violations Penalized by Special Acts and Municipal Ordinances and to Provide When Prescription Shall Begin to Run', as amended.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A28","no":28,"noLabel":{"en":"SEC. 29."},"text":{"en":"SEC. 29. All hearings and investigations before the Commission shall be governed by rules adopted by the Commission, and in the conduct thereof the Commission shall not be bound by the technical rules of legal evidence: Provided, That the Hearing Officer may summarily punish for contempt by a fine not exceeding Two thousand pesos (P2,000.00) or by imprisonment not exceeding ten days, or both, any person guilty of misconduct in the presence of the Hearing Officer or so near the same as to interrupt the hearing or session or any proceedings before them, including cases in which a person present at a hearing, session, or investigation held by the Hearing Officer refuses to be sworn as a witness or to answer as such when lawfully required to do so. To enforce the provisions of this section, the Commission may, if necessary, request the assistance of the municipal or city police for the execution of any order made for said purpose.\""},"paragraphs":["All hearings and investigations before the Commission shall be governed by rules adopted by the Commission, and in the conduct thereof the Commission shall not be bound by the technical rules of legal evidence:","Provided,","That the Hearing Officer may summarily punish for contempt by a fine not exceeding Two thousand pesos (P2,000.00) or by imprisonment not exceeding ten days, or both, any person guilty of misconduct in the presence of the Hearing Officer or so near the same as to interrupt the hearing or session or any proceedings before them, including cases in which a person present at a hearing, session, or investigation held by the Hearing Officer refuses to be sworn as a witness or to answer as such when lawfully required to do so. To enforce the provisions of this section, the Commission may, if necessary, request the assistance of the municipal or city police for the execution of any order made for said purpose.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A29","no":29,"noLabel":{"en":"SEC. 30."},"text":{"en":"SEC. 30. (a) The Commission may issue subpoenas and subpoenas duces tecum, for witnesses in any matter or inquiry pending before the Commission and require the production of all books, papers, tariffs, contracts, agreements, and all other documents, which the Commission may deem necessary in any proceeding. Such process shall be issued under the seal of the Commission, signed by one of the Hearing Office, and may be served by any person of full age, or by registered mail. Disobedience to or failure to comply with such subpoena, shall constitute indirect contempt, and may be instituted in the manner as provided in the Rules of Court before the appropriate court. \"(b) Any person who shall neglect or refuse to answer any lawful inquiry or produce before the Commission, books, papers, tariffs, contracts, agreements, and documents or other things called for by said Commission, if in his power to do so, in obedience to the subpoena or lawful inquiry of the Commission upon conviction thereof by a court of competent jurisdiction, shall be punished by a fine not exceeding Thirty thousand pesos (P30,000.00) or by imprisonment not exceeding six (6) months, or both, at the discretion of the court. \"(c) The officials and Hearing Officers of the Commission shall have the power to administer oaths in all matters under the jurisdiction of the Commission. \"x x x \"(e) Witnesses appearing before the Commission in obedience to subpoena or subpoena duces tecum shall be entitled to receive the same fees and mileage as witness attending regional trial courts in civil cases. \"(f) Any person who shall obstruct the Commission or either of the Hearing Officers while engaged in the discharge of official duties, or who shall conduct himself in a rude, disrespectful or disorderly manner before the Commission or either of the Hearing Officers, while engaged in the discharge of official duties, or shall orally or in writing be disrespectful to, offend or insult either of the Hearing Officers on occasion or by reason of the performance of his official duties, upon conviction thereof by a court of competent jurisdiction, shall be punished for each offense by a fine not exceeding Thirty thousand pesos (P30,000.00), or by imprisonment not exceeding six (6) months, or both, at the discretion of the Court.\""},"paragraphs":["(a) The Commission may issue subpoenas and subpoenas duces tecum, for witnesses in any matter or inquiry pending before the Commission and require the production of all books, papers, tariffs, contracts, agreements, and all other documents, which the Commission may deem necessary in any proceeding. Such process shall be issued under the seal of the Commission, signed by one of the Hearing Office, and may be served by any person of full age, or by registered mail. Disobedience to or failure to comply with such subpoena, shall constitute indirect contempt, and may be instituted in the manner as provided in the Rules of Court before the appropriate court. \"(b) Any person who shall neglect or refuse to answer any lawful inquiry or produce before the Commission, books, papers, tariffs, contracts, agreements, and documents or other things called for by said Commission, if in his power to do so, in obedience to the subpoena or lawful inquiry of the Commission upon conviction thereof by a court of competent jurisdiction, shall be punished by a fine not exceeding Thirty thousand pesos (P30,000.00) or by imprisonment not exceeding six (6) months, or both, at the discretion of the court. \"(c) The officials and Hearing Officers of the Commission shall have the power to administer oaths in all matters under the jurisdiction of the Commission. \"x x x \"(e) Witnesses appearing before the Commission in obedience to subpoena or subpoena duces tecum shall be entitled to receive the same fees and mileage as witness attending regional trial courts in civil cases. \"(f) Any person who shall obstruct the Commission or either of the Hearing Officers while engaged in the discharge of official duties, or who shall conduct himself in a rude, disrespectful or disorderly manner before the Commission or either of the Hearing Officers, while engaged in the discharge of official duties, or shall orally or in writing be disrespectful to, offend or insult either of the Hearing Officers on occasion or by reason of the performance of his official duties, upon conviction thereof by a court of competent jurisdiction, shall be punished for each offense by a fine not exceeding Thirty thousand pesos (P30,000.00), or by imprisonment not exceeding six (6) months, or both, at the discretion of the Court.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A30","no":30,"noLabel":{"en":"SEC. 32."},"text":{"en":"SEC. 32. The Commission may, i any investigation or hearing, by its order in writing, cause the deposition of witnesses residing within or without the Philippines to be taken in the manner and under the conditions prescribed by the Rules of Court. Where witnesses reside in places distant from Manila and it would be inconvenient and expensive for them to appear personally before the Commission, the Commission may, by proper order, commission any clerk of the Regional Trial Court of the Philippines to take the deposition of witnesses in any case pending before the Commission. It shall be the duty of the official so commissioned, to designate promptly a date or dates for the taking of such deposition, giving timely notice to the parties, and on said date to proceed to take the deposition, reducing it to writing. After the depositions have been taken, the official so commissioned shall certify to the depositions taken and forward them as soon as possible to the Commission. It shall be the duty of the respective parties to furnish stenographers for taking and transcribing the testimony taken. \"The Commission may also, by proper order, authorize any of the attorneys of the legal division or division chiefs of the Commission, if they be lawyers, to hear and investigate any case filed with the Commission and in connection therewith to receive such evidence as may be material thereto. At the conclusion of the hearing or investigation, the attorney or division chief so authorized shall submit the evidence received by him to the Commission to enable the latter to render its decision.\""},"paragraphs":["The Commission may, i any investigation or hearing, by its order in writing, cause the deposition of witnesses residing within or without the Philippines to be taken in the manner and under the conditions prescribed by the Rules of Court. Where witnesses reside in places distant from Manila and it would be inconvenient and expensive for them to appear personally before the Commission, the Commission may, by proper order, commission any clerk of the Regional Trial Court of the Philippines to take the deposition of witnesses in any case pending before the Commission. It shall be the duty of the official so commissioned, to designate promptly a date or dates for the taking of such deposition, giving timely notice to the parties, and on said date to proceed to take the deposition, reducing it to writing. After the depositions have been taken, the official so commissioned shall certify to the depositions taken and forward them as soon as possible to the Commission. It shall be the duty of the respective parties to furnish stenographers for taking and transcribing the testimony taken. \"The Commission may also, by proper order, authorize any of the attorneys of the legal division or division chiefs of the Commission, if they be lawyers, to hear and investigate any case filed with the Commission and in connection therewith to receive such evidence as may be material thereto. At the conclusion of the hearing or investigation, the attorney or division chief so authorized shall submit the evidence received by him to the Commission to enable the latter to render its decision.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A31","no":31,"noLabel":{"en":"SEC. 35."},"text":{"en":"SEC. 35. Any order, ruling, or decision of the Administrative Agency may be appealed in the manner and within the period prescribed under the Rules of Court and other pertinent laws.\""},"paragraphs":["Any order, ruling, or decision of the Administrative Agency may be appealed in the manner and within the period prescribed under the Rules of Court and other pertinent laws.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A32","no":32,"noLabel":{"en":"SEC.38."},"text":{"en":"SEC.38. The chief of the legal division or any other attorneys of the Commission shall represent the same in all judicial proceedings. It shall be the duty of the Solicitor General to represent the Commission in any judicial proceeding if, for special reasons, the Hearing Officer shall request has intervention.\""},"paragraphs":["The chief of the legal division or any other attorneys of the Commission shall represent the same in all judicial proceedings. It shall be the duty of the Solicitor General to represent the Commission in any judicial proceeding if, for special reasons, the Hearing Officer shall request has intervention.\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A33","no":33,"noLabel":{"en":"SEC. 40."},"text":{"en":"SEC. 40. Administrative Fees and Charges. - Administrative Agency may collect from any public service, including any public utility, reasonable fees and charges, and impose appropriate penalties and fines as provided by law: Provided, That such fees, charges, penalties and fines may be adjusted to its present value every five (5) years using the Consumer Price Index (CPI) as published by the Philippine Statistics Authority (PSA).\""},"paragraphs":["Administrative Fees and Charges. - Administrative Agency may collect from any public service, including any public utility, reasonable fees and charges, and impose appropriate penalties and fines as provided by law:","Provided,","That such fees, charges, penalties and fines may be adjusted to its present value every five (5) years using the Consumer Price Index (CPI) as published by the Philippine Statistics Authority (PSA).\""],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A34","no":34,"noLabel":{"en":"Section 23."},"text":{"en":"Section 23. Powers of the President to Suspend or Prohibit Transaction or Investment. - In the interest of national security, the President, after review, evaluation and recommendation of the relevant government department or Administrative Agency, may, within sixty (60) days from the receipt of such recommendation, suspend or prohibit any proposed merger or acquisition transaction, or any investment in a public service that effectively results in the grant of control, whether direct or indirect, to a foreigner or a foreign corporation. The Philippine Competition Commission (PCC) may be consulted on all matters relating to mergers and acquisitions. The NEDA shall promulgate rules and regulations to implement the provisions of this section."},"paragraphs":["Powers of the President to Suspend or Prohibit Transaction or Investment.","- In the interest of national security, the President, after review, evaluation and recommendation of the relevant government department or Administrative Agency, may, within sixty (60) days from the receipt of such recommendation, suspend or prohibit any proposed merger or acquisition transaction, or any investment in a public service that effectively results in the grant of control, whether direct or indirect, to a foreigner or a foreign corporation. The Philippine Competition Commission (PCC) may be consulted on all matters relating to mergers and acquisitions. The NEDA shall promulgate rules and regulations to implement the provisions of this section."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A35","no":35,"noLabel":{"en":"Section 24."},"text":{"en":"Section 24. Investments by an Entity Controlled by or Acting on Behalf of the Foreign Government, or Foreign State-owned Enterprises. - An entity controlled by or acting on behalf of the foreign government or foreign state-owned enterprises shall be prohibited from owning capital in any public service classified as public utility or critical infrastructure: Provided, That the prohibition shall apply only to investments made after the effectivity of this Act: Provided, further, That foreign state-owned enterprises which own capital prior to the effectivity of this law are prohibited from investing in additional capital upon the effectivity of this Act: Provided, finally, That notwithstanding the immediately preceding clause, the sovereign wealth funds and independent pensions funds of each state may collectively own up to thirty percent (30%) of the capital of such public services. In the interest of national security, an entity controlled by or acting on behalf of the foreign government or foreign-owned enterprises shall not make any date or information disclosure, nor extend assistance, support or cooperation to any foreign government, instrumentalities or agents. The NEDA shall promulgate rules and regulations to implement the provisions of this section."},"paragraphs":["Investments by an Entity Controlled by or Acting on Behalf of the Foreign Government, or Foreign State-owned Enterprises.","- An entity controlled by or acting on behalf of the foreign government or foreign state-owned enterprises shall be prohibited from owning capital in any public service classified as public utility or critical infrastructure:","Provided,","That the prohibition shall apply only to investments made after the effectivity of this Act:","Provided,","further, That foreign state-owned enterprises which own capital prior to the effectivity of this law are prohibited from investing in additional capital upon the effectivity of this Act:","Provided,","finally, That notwithstanding the immediately preceding clause, the sovereign wealth funds and independent pensions funds of each state may collectively own up to thirty percent (30%) of the capital of such public services. In the interest of national security, an entity controlled by or acting on behalf of the foreign government or foreign-owned enterprises shall not make any date or information disclosure, nor extend assistance, support or cooperation to any foreign government, instrumentalities or agents. The NEDA shall promulgate rules and regulations to implement the provisions of this section."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A36","no":36,"noLabel":{"en":"Section 25."},"text":{"en":"Section 25. Reciprocity Clause. - Foreign nationals shall not be allowed to own more than fifty percent (50%) of the capital of entities engaged in the operation and management of critical infrastructure unless the country of such foreign national accords reciprocity to Philippine Nationals as may be provided by foreign law, treaty or international agreement. Reciprocity may be satisfied by according rights of similar value in other economic sectors. The NEDA shall promulgate rules and regulations for this purpose. Unless otherwise provided by law, or by any international agreement, a public service shall employ a foreign national only after the determination of non-availability of a Philippine National who is competent, able and willing to perform the services for which the foreign national is desired. Any foreign national seeking admission to the Philippines for employment purposes and any public service which desires to engage a foreign national for employment in the Philippines must obtain an employment permit pursuant to Presidential Decree No. 442, otherwise known as the \"Labor Code of the Philippines\", as amended. Public services employing foreign nationals issued employment permits in industries to be determined by the Department of Labor and Employment (DOLE) shall implement an understudy/skills development program to ensure the transfer of technology/skills to Filipinos, whether next-in-rank or otherwise, with the potential of succeeding the foreign national in the same establishment or its subsidiary, within a specific period as may be determined by the DOLE, upon consultation with relevant government agencies and industry experts."},"paragraphs":["Reciprocity Clause.","- Foreign nationals shall not be allowed to own more than fifty percent (50%) of the capital of entities engaged in the operation and management of critical infrastructure unless the country of such foreign national accords reciprocity to Philippine Nationals as may be provided by foreign law, treaty or international agreement. Reciprocity may be satisfied by according rights of similar value in other economic sectors. The NEDA shall promulgate rules and regulations for this purpose. Unless otherwise provided by law, or by any international agreement, a public service shall employ a foreign national only after the determination of non-availability of a Philippine National who is competent, able and willing to perform the services for which the foreign national is desired. Any foreign national seeking admission to the Philippines for employment purposes and any public service which desires to engage a foreign national for employment in the Philippines must obtain an employment permit pursuant to Presidential Decree No. 442, otherwise known as the \"Labor Code of the Philippines\", as amended. Public services employing foreign nationals issued employment permits in industries to be determined by the Department of Labor and Employment (DOLE) shall implement an understudy/skills development program to ensure the transfer of technology/skills to Filipinos, whether next-in-rank or otherwise, with the potential of succeeding the foreign national in the same establishment or its subsidiary, within a specific period as may be determined by the DOLE, upon consultation with relevant government agencies and industry experts."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A37","no":37,"noLabel":{"en":"Section 26."},"text":{"en":"Section 26. Information Security. - Persons and companies engaged in the telecommunications business shall obtain and maintain certifications from an accredited certification body attesting to compliance with relevant ISO standards on information security, as prescribed by the DICT: Provided, That the maintenance of these certifications shall be a continuing qualification for retention of franchise or other authority to operate: Provided, further, That this section shall not apply to micro, small and medium enterprises under Republic Act No. 6977, otherwise known as the \"Magna Carta for Micro, Small and Medium Enterprises (MSMEs)\", as amended."},"paragraphs":["Information Security.","- Persons and companies engaged in the telecommunications business shall obtain and maintain certifications from an accredited certification body attesting to compliance with relevant ISO standards on information security, as prescribed by the DICT:","Provided,","That the maintenance of these certifications shall be a continuing qualification for retention of franchise or other authority to operate:","Provided,","further, That this section shall not apply to micro, small and medium enterprises under Republic Act No. 6977, otherwise known as the \"Magna Carta for Micro, Small and Medium Enterprises (MSMEs)\", as amended."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A38","no":38,"noLabel":{"en":"Section 27."},"text":{"en":"Section 27. Conduct of Regular Studies and Comprehensive Baseline Survey. - The NEDA shall conduct regular studies on whether regulatory reform is warranted in a public service sector to improve consumer welfare and to submit its recommendation to Congress. The NEDA, in coordination with the relevant government agencies and local government units, shall conduct a comprehensive baseline survey of public services governance within six (6) months from the effectivity of this Act. Copies of the results of said survey shall be furnished to the Congress, the NEDA and the PCC.ℒ&alpha;w&rho;hi&#2551"},"paragraphs":["Conduct of Regular Studies and Comprehensive Baseline Survey.","- The NEDA shall conduct regular studies on whether regulatory reform is warranted in a public service sector to improve consumer welfare and to submit its recommendation to Congress. The NEDA, in coordination with the relevant government agencies and local government units, shall conduct a comprehensive baseline survey of public services governance within six (6) months from the effectivity of this Act. Copies of the results of said survey shall be furnished to the Congress, the NEDA and the PCC.ℒ&alpha;w&rho;hi&#2551"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A39","no":39,"noLabel":{"en":"Section 28."},"text":{"en":"Section 28. Congressional Oversight and Periodic Review. - A Congressional Oversight Committee shall be created that will monitor and evaluate the implementation of this Act every five (5) years commencing from the effectivity of this Act. The Congressional Oversight Committee shall be composed of the Chairperson of the Senate Committee on Public Services, the Chairperson of the House of Representatives Committee on Economic Affairs, and representatives of other relevant congressional committee."},"paragraphs":["Congressional Oversight and Periodic Review.","- A Congressional Oversight Committee shall be created that will monitor and evaluate the implementation of this Act every five (5) years commencing from the effectivity of this Act. The Congressional Oversight Committee shall be composed of the Chairperson of the Senate Committee on Public Services, the Chairperson of the House of Representatives Committee on Economic Affairs, and representatives of other relevant congressional committee."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A40","no":40,"noLabel":{"en":"Section 29."},"text":{"en":"Section 29. Performance Audit. - Administrative agencies must ensure the annual conduct of performance audit by an independent evaluation team to monitor cost, the quality of services provided to the public, and the ability of the public service provider to immediately and adequately respond to emergency cases: Provided, That in the case of critical infrastructure and public utilities, the performance audit shall include risk assessment, emergency response, and cybersecurity, among others. Metrics for various types of services must be established to sustain reliability, security, and safety of the public."},"paragraphs":["Performance Audit.","- Administrative agencies must ensure the annual conduct of performance audit by an independent evaluation team to monitor cost, the quality of services provided to the public, and the ability of the public service provider to immediately and adequately respond to emergency cases:","Provided,","That in the case of critical infrastructure and public utilities, the performance audit shall include risk assessment, emergency response, and cybersecurity, among others. Metrics for various types of services must be established to sustain reliability, security, and safety of the public."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A41","no":41,"noLabel":{"en":"Section 30."},"text":{"en":"Section 30. Implementing Rules and Regulations. - All Administrative Agencies under Section 3 of this Act shall, in coordination with the NEDA, promulgate rules and regulations to implement the provisions of this Act within six (6) months from the effectivity of this Act."},"paragraphs":["Implementing Rules and Regulations.","- All Administrative Agencies under Section 3 of this Act shall, in coordination with the NEDA, promulgate rules and regulations to implement the provisions of this Act within six (6) months from the effectivity of this Act."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A42","no":42,"noLabel":{"en":"Section 31."},"text":{"en":"Section 31. Interpretation. - This Act shall be subject to and consistent with the regulatory powers of the State to promote public interest in Article IX-C, Section 4 and Article XII, Section 17 of the Constitution. No franchise, certificate, concession, or authorization granted by the appropriate Administrative Agencies pursuant to this Act shall be: (a) exclusive in character; (b) for a longer period than fifty (50) years: Provided, That if a public service has maintained an exemplary record in the delivery of services, and has made substantial investments on infrastructure, technology or equipment for its operations, such performance and size of investment shall be taken into consideration, and the application for renewal of the franchise, certificate, concession or authorization of the public service shall be given priority by the appropriate Administrative Agencies; and (c) granted except under the condition that it shall be subject to amendment, alteration, or repeal by Congress when the public interest so requires."},"paragraphs":["Interpretation.","- This Act shall be subject to and consistent with the regulatory powers of the State to promote public interest in Article IX-C, Section 4 and Article XII, Section 17 of the Constitution. No franchise, certificate, concession, or authorization granted by the appropriate Administrative Agencies pursuant to this Act shall be: (a) exclusive in character; (b) for a longer period than fifty (50) years:","Provided,","That if a public service has maintained an exemplary record in the delivery of services, and has made substantial investments on infrastructure, technology or equipment for its operations, such performance and size of investment shall be taken into consideration, and the application for renewal of the franchise, certificate, concession or authorization of the public service shall be given priority by the appropriate Administrative Agencies; and (c) granted except under the condition that it shall be subject to amendment, alteration, or repeal by Congress when the public interest so requires."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A43","no":43,"noLabel":{"en":"Section 32."},"text":{"en":"Section 32. Non-Impairment of Existing Agreements. - The application ad implementation of the pertinent provisions of this Act shall not impair vested rights or obligations of contracts. Current and subsisting concession agreements and other similar contracts of juridical persons with government agencies or government-owned and -controlled corporations covering activities hereunder classified as public utilities shall remain valid and in force in accordance with the existing terms and conditions the parties agreed to thereunder until the expiration or termination thereof."},"paragraphs":["Non-Impairment of Existing Agreements.","- The application ad implementation of the pertinent provisions of this Act shall not impair vested rights or obligations of contracts. Current and subsisting concession agreements and other similar contracts of juridical persons with government agencies or government-owned and -controlled corporations covering activities hereunder classified as public utilities shall remain valid and in force in accordance with the existing terms and conditions the parties agreed to thereunder until the expiration or termination thereof."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A44","no":44,"noLabel":{"en":"Section 33."},"text":{"en":"Section 33. Separability Clause. - Should any portion or provision of this Act be declared unconstitutional, the remainder of this Act or any provision not affected thereby shall remain in force and effect."},"paragraphs":["Separability Clause.","- Should any portion or provision of this Act be declared unconstitutional, the remainder of this Act or any provision not affected thereby shall remain in force and effect."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A45","no":45,"noLabel":{"en":"Section 34."},"text":{"en":"Section 34. Repealing Clause. - All laws, decrees, orders, rules and regulations, or other issuances or parts thereof, inconsistent with the provisions of this Act are hereby repealed or modified accordingly. The provisions on limitation on foreign ownership in the following laws are hereby amended or modified: (a) Republic Act No. 6957, entitled, \"An Act Authorizing the Financing, Construction, Operation and Maintenance of Infrastructure Projects by the Private Sector, and for Other Purposes\", as amended; (b) Republic Act No. 9295, otherwise known as the \"Domestic Shipping Development Act of 2004\", as amended; (c) Republic Act No. 9497, otherwise known as the \"Civil Aviation Authority Act of 2008\", as amended; (d) Republic Act No. 776, otherwise known as the \"The Civil Aeronautics Act of the Philippines\", as amended; (e) Presidential Decree No. 1112, otherwise known as the \"Toll Operation Decree\", as amended; (f) Department of Transportation Department Order No. 2018-13, as amended, on the classification of the Transport Network Companies and Transportation Network Vehicles Service as public utilities; and (g) Republic Act No. 7925, otherwise known as the \"Public Telecommunications Policy Act of the Philippines\", as amended, on the classification of all telecommunications entities as public utilities. Nothing herein shall be construed as amending or repealing laws and administrative regulations deregulating or delisting services, industries and/or rates."},"paragraphs":["Repealing Clause.","- All laws, decrees, orders, rules and regulations, or other issuances or parts thereof, inconsistent with the provisions of this Act are hereby repealed or modified accordingly. The provisions on limitation on foreign ownership in the following laws are hereby amended or modified: (a) Republic Act No. 6957, entitled, \"An Act Authorizing the Financing, Construction, Operation and Maintenance of Infrastructure Projects by the Private Sector, and for Other Purposes\", as amended; (b) Republic Act No. 9295, otherwise known as the \"Domestic Shipping Development Act of 2004\", as amended; (c) Republic Act No. 9497, otherwise known as the \"Civil Aviation Authority Act of 2008\", as amended; (d) Republic Act No. 776, otherwise known as the \"The Civil Aeronautics Act of the Philippines\", as amended; (e) Presidential Decree No. 1112, otherwise known as the \"Toll Operation Decree\", as amended; (f) Department of Transportation Department Order No. 2018-13, as amended, on the classification of the Transport Network Companies and Transportation Network Vehicles Service as public utilities; and (g) Republic Act No. 7925, otherwise known as the \"Public Telecommunications Policy Act of the Philippines\", as amended, on the classification of all telecommunications entities as public utilities. Nothing herein shall be construed as amending or repealing laws and administrative regulations deregulating or delisting services, industries and/or rates."],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},{"id":"PH-PSA-2022-A46","no":46,"noLabel":{"en":"Section 35."},"text":{"en":"Section 35. Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation. Approved, (SGD.)"},"paragraphs":["Effectivity.","- This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation. Approved, (SGD.)"],"sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"}],"pack":"ph-2","fulltextMeta":{"country":"PH","level":"law","status":"active","topics":["investment"],"title":{"zh":"公共服务法修正案","en":"An Act Amending the Public Service Act"},"docNumber":"Republic Act No. 11659","issuingBody":{"zh":"菲律宾国会","en":"Congress of the Philippines"},"promulgatedDate":"2022-03-21","effectiveDate":"2022-04-04","coverage":"full","source":{"name":"The Lawphil Project — Arellano Law Foundation","url":"https://lawphil.net/statutes/repacts/ra2022/ra_11659_2022.html"},"summary":{"zh":"修订 Commonwealth Act No. 146（公共服务法），放开电信等公共服务领域外资限制。","en":"An act amending Commonwealth Act No. 146, otherwise known as the Public Service Act."}},"summary":{"zh":"修订 Commonwealth Act No. 146（公共服务法），放开电信等公共服务领域外资限制。","en":"An act amending Commonwealth Act No. 146, otherwise known as the Public Service Act."}};
